import { useState, useRef, useEffect } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import {
  Bell,
  Search,
  Sun,
  Moon,
  LogOut,
  User,
  Settings,
  ChevronDown,
  AlertTriangle,
  CheckCircle2,
  Info,
  X,
} from 'lucide-react';
import { useAuthStore } from '@byteevolvr/store';
import { AdminService } from '@byteevolvr/api-client';

import { useTheme } from '../contexts/ThemeContext';

import { Sidebar } from './Sidebar';

function formatRelativeTime(date: Date) {
  const now = new Date();
  const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

  if (diffInSeconds < 60) return 'just now';
  if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}m ago`;
  if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}h ago`;
  return `${Math.floor(diffInSeconds / 86400)}d ago`;
}

export function AdminLayout() {
  const { theme, toggleTheme } = useTheme();
  const { user, logout: signOut } = useAuthStore();
  const navigate = useNavigate();

  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [notifMenuOpen, setNotifMenuOpen] = useState(false);
  const [notifications, setNotifications] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [unreadCount, setUnreadCount] = useState(0);

  const menuRef = useRef<HTMLDivElement>(null);
  const notifRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    fetchNotifications(); // eslint-disable-line react-hooks/immutability // eslint-disable-line @typescript-eslint/no-floating-promises
    const interval = setInterval(fetchNotifications, 30000); // Poll every 30s
    return () => clearInterval(interval);
  }, []);

  async function fetchNotifications() {
    try {
      const data = await AdminService.getNotifications();
      setNotifications(data || []);
      setUnreadCount(data?.filter((n: any) => !n.is_read).length || 0); // eslint-disable-line @typescript-eslint/no-explicit-any
    } catch (err) {
      console.error('Failed to fetch notifications:', err);
    }
  }

  const markAsRead = async (id: string) => {
    try {
      await AdminService.markNotificationAsRead(id);
      setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
      setUnreadCount((prev) => Math.max(0, prev - 1));
    } catch (err) {
      console.error('Failed to mark read:', err);
    }
  };

  // Close dropdowns when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setUserMenuOpen(false);
      }
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setNotifMenuOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSignOut = async () => {
    setUserMenuOpen(false);
    await signOut();
    navigate('/login', { replace: true }); // eslint-disable-line @typescript-eslint/no-floating-promises
  };

  const getNotifIcon = (type: string) => {
    switch (type) {
      case 'warning':
        return <AlertTriangle className="h-4 w-4 text-warning" />;
      case 'error':
        return <X className="h-4 w-4 text-error" />;
      case 'success':
        return <CheckCircle2 className="h-4 w-4 text-success" />;
      default:
        return <Info className="h-4 w-4 text-primary" />;
    }
  };

  const userInitial = user?.email?.charAt(0).toUpperCase() ?? 'A';
  const displayName =
    user?.full_name || user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'Admin';

  return (
    <div className="flex h-screen w-full bg-background font-sans text-on-background">
      <Sidebar />
      <div className="flex flex-1 flex-col overflow-hidden">
        <header className="flex h-16 shrink-0 items-center justify-between border-b border-outline-variant bg-surface px-6 z-30">
          <div className="flex flex-1 items-center">
            <div className="relative w-full max-w-md">
              <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                <Search className="h-5 w-5 text-on-surface-variant" />
              </div>
              <input
                type="text"
                className="block w-full rounded-xl border-0 py-2 pl-10 pr-3 bg-surface-container-low text-on-surface placeholder:text-on-surface-variant focus:bg-surface focus:ring-2 focus:ring-primary sm:text-sm transition-all"
                placeholder="Global search..."
              />
            </div>
          </div>

          <div className="ml-4 flex items-center gap-x-3">
            <button
              onClick={toggleTheme}
              className="rounded-full p-2 text-on-surface-variant hover:text-on-surface hover:bg-surface-container transition-all"
            >
              {theme === 'dark' ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}
            </button>

            {/* Notifications Dropdown */}
            <div className="relative" ref={notifRef}>
              <button
                onClick={() => setNotifMenuOpen(!notifMenuOpen)}
                className={`relative rounded-full p-2 transition-all ${notifMenuOpen ? 'bg-primary/10 text-primary' : 'text-on-surface-variant hover:text-on-surface hover:bg-surface-container'}`}
              >
                <Bell className="h-5 w-5" />
                {unreadCount > 0 && (
                  <span className="absolute top-1.5 right-1.5 h-4 min-w-[16px] px-1 rounded-full bg-error text-[10px] font-bold text-white flex items-center justify-center ring-2 ring-surface animate-in zoom-in">
                    {unreadCount}
                  </span>
                )}
              </button>

              {notifMenuOpen && (
                <div className="absolute right-0 top-full mt-2 w-80 rounded-2xl border border-outline-variant bg-surface shadow-2xl py-0 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="p-4 border-b border-outline-variant bg-surface-container-low flex justify-between items-center">
                    <h3 className="font-bold text-on-surface">Notifications</h3>
                    {unreadCount > 0 && (
                      <span className="text-[10px] font-black uppercase tracking-widest text-primary">
                        {unreadCount} New
                      </span>
                    )}
                  </div>
                  <div className="max-h-[400px] overflow-y-auto">
                    {notifications.length === 0 ? (
                      <div className="p-10 text-center text-on-surface-variant">
                        <Bell className="h-8 w-8 mx-auto mb-2 opacity-10" />
                        <p className="text-sm font-medium">All caught up!</p>
                      </div>
                    ) : (
                      notifications.map((n) => (
                        <div
                          key={n.id}
                          onClick={() => !n.is_read && markAsRead(n.id)}
                          className={`p-4 border-b border-outline-variant last:border-0 cursor-pointer transition-all hover:bg-surface-container ${!n.is_read ? 'bg-primary/5' : ''}`}
                        >
                          <div className="flex gap-3">
                            <div
                              className={`h-8 w-8 rounded-lg shrink-0 flex items-center justify-center ${n.priority === 'high' ? 'bg-error/10' : 'bg-surface-container-high'}`}
                            >
                              {getNotifIcon(n.type)}
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="flex justify-between items-start mb-0.5">
                                <span
                                  className={`text-sm font-bold truncate ${!n.is_read ? 'text-on-surface' : 'text-on-surface-variant'}`}
                                >
                                  {n.title}
                                </span>
                                <span className="text-[10px] text-on-surface-variant whitespace-nowrap ml-2">
                                  {formatRelativeTime(new Date(n.created_at))}
                                </span>
                              </div>
                              <p
                                className={`text-xs leading-relaxed line-clamp-2 ${!n.is_read ? 'text-on-surface' : 'text-on-surface-variant'}`}
                              >
                                {n.message}
                              </p>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                  <div className="p-3 border-t border-outline-variant text-center bg-surface-container-low">
                    <button className="text-[10px] font-black uppercase tracking-widest text-primary hover:underline">
                      View All Notifications
                    </button>
                  </div>
                </div>
              )}
            </div>

            {/* User Dropdown */}
            <div className="relative" ref={menuRef}>
              <button
                onClick={() => setUserMenuOpen(!userMenuOpen)}
                className="flex items-center gap-2 rounded-2xl p-1 pr-3 hover:bg-surface-container transition-all"
              >
                <div className="h-9 w-9 rounded-xl bg-primary text-on-primary flex items-center justify-center font-bold shadow-sm">
                  {userInitial}
                </div>
                <div className="hidden md:block text-left">
                  <div className="text-xs font-bold text-on-surface leading-none mb-1 truncate max-w-[100px]">
                    {displayName}
                  </div>
                  <div className="text-[9px] font-black uppercase tracking-tighter text-on-surface-variant leading-none">
                    Administrator
                  </div>
                </div>
                <ChevronDown
                  className={`h-4 w-4 text-on-surface-variant transition-transform duration-200 ${userMenuOpen ? 'rotate-180' : ''}`}
                />
              </button>

              {userMenuOpen && (
                <div className="absolute right-0 top-full mt-2 w-56 rounded-2xl border border-outline-variant bg-surface shadow-2xl py-2 z-50 animate-in fade-in slide-in-from-top-2 duration-150">
                  <button
                    onClick={() => {
                      setUserMenuOpen(false);
                      navigate('/settings'); // eslint-disable-line @typescript-eslint/no-floating-promises
                    }}
                    className="flex w-full items-center gap-3 px-4 py-3 text-sm font-bold text-on-surface hover:bg-surface-container transition-all"
                  >
                    <User className="h-4 w-4 text-on-surface-variant" /> Profile
                  </button>
                  <button
                    onClick={() => {
                      setUserMenuOpen(false);
                      navigate('/settings'); // eslint-disable-line @typescript-eslint/no-floating-promises
                    }}
                    className="flex w-full items-center gap-3 px-4 py-3 text-sm font-bold text-on-surface hover:bg-surface-container transition-all"
                  >
                    <Settings className="h-4 w-4 text-on-surface-variant" /> Settings
                  </button>
                  <div className="h-px bg-outline-variant my-1 mx-2" />
                  <button
                    onClick={handleSignOut}
                    className="flex w-full items-center gap-3 px-4 py-3 text-sm font-bold text-error hover:bg-error/10 transition-all"
                  >
                    <LogOut className="h-4 w-4" /> Sign Out
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto bg-background p-6 lg:p-10">
          <div className="mx-auto max-w-7xl">
            <Outlet />
          </div>
        </main>
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { Card, Button } from '@byteevolvr/ui';
import { Upload, X, Check, AlertCircle, FileText, Download, Loader2 } from 'lucide-react';
import * as XLSX from 'xlsx';
import { AdminService } from '@byteevolvr/api-client';

import { Table, TableHeader, TableRow, TableHead, TableBody, TableCell } from './ui/Table';

interface BulkImportDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export function BulkImportDialog({ isOpen, onClose, onSuccess }: BulkImportDialogProps) {
  const [file, setFile] = useState<File | null>(null);
  const [previewData, setPreviewData] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [importing, setImporting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successCount, setSuccessCount] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
      parseFile(selectedFile);
    }
  };

  const parseFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        const json = XLSX.utils.sheet_to_json(sheet);
        setPreviewData(json.slice(0, 5)); // Show first 5 for preview
        setError(null);
      } catch (err) { // eslint-disable-line @typescript-eslint/no-unused-vars
        setError('Failed to parse file. Please ensure it is a valid CSV or Excel file.');
        setPreviewData([]);
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleImport = async () => {
    if (!file) return;
    setImporting(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        const json = XLSX.utils.sheet_to_json(sheet) as any[]; // eslint-disable-line @typescript-eslint/no-explicit-any

        const products = json
          .map((item) => { // eslint-disable-line complexity
            const imagesFromCols = [
              item.Image1 || item.image1,
              item.Image2 || item.image2,
              item.Image3 || item.image3,
              item.Image4 || item.image4,
              item.Image5 || item.image5,
              item.Image6 || item.image6,
            ].filter((url) => url && url.toString().trim() !== '');

            const imagesFromList = (item.Images || item.images || '')
              .toString()
              .split(',')
              .map((s: string) => s.trim())
              .filter((s: string) => s !== '');

            const allImages = [
              ...imagesFromCols,
              ...imagesFromList,
              item['Image Link'] || item.image_link,
            ]
              .filter((url) => url && url.toString().trim() !== '')
              .map((url) => url.toString())
              .slice(0, 6);

            return {
              name: item.Name || item.name || item.product_name,
              description: item.Description || item.description || '',
              price: parseFloat(item.Price || item.price || '0'),
              original_price:
                item.OriginalPrice || item.original_price
                  ? parseFloat(item.OriginalPrice || item.original_price)
                  : null,
              sku: item.SKU || item.sku || '',
              stock_quantity: parseInt(item.Stock || item.stock || item.stock_quantity || '0'),
              category: item.Category || item.category || 'General',
              brand: item.Brand || item.brand || '',
              status: (item.Status || item.status || 'active').toLowerCase(),
              image_url: allImages[0] || item.ImageUrl || item.image_url || '',
              images: allImages,
            };
          })
          .filter((p) => p.name);

        const result = await AdminService.bulkImportProducts(products);
        setSuccessCount(result.length || products.length);
        onSuccess();
        setTimeout(() => {
          onClose();
          setFile(null);
          setPreviewData([]);
          setSuccessCount(0);
        }, 2000);
      } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
        setError(err.customMessage || err.message || 'An error occurred during import.');
      } finally {
        setImporting(false);
      }
    };
    reader.readAsBinaryString(file);
  };

  const downloadTemplate = () => {
    const template = [
      {
        name: 'Example Product',
        sku: 'EX-SKU-001',
        price: 99.99,
        stock: 50,
        category: 'Electronics',
        brand: 'BrandX',
        description: 'Product description here',
        status: 'active',
        image_link: 'https://example.com/image.jpg',
      },
    ];
    const ws = XLSX.utils.json_to_sheet(template);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Template');
    XLSX.writeFile(wb, 'product_import_template.xlsx');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <Card className="w-full max-w-2xl shadow-2xl animate-in fade-in zoom-in duration-200">
        <div className="flex items-center justify-between p-4 border-b border-outline-variant">
          <h2 className="text-xl font-bold text-on-surface">Bulk Import Products</h2>
          <button
            onClick={onClose}
            className="p-1 rounded-full hover:bg-surface-container transition-colors"
          >
            <X className="h-5 w-5 text-on-surface-variant" />
          </button>
        </div>

        <div className="p-6 space-y-6">
          {!file ? (
            <div
              className="border-2 border-dashed border-outline-variant rounded-xl p-12 text-center hover:bg-surface-container-low transition-colors cursor-pointer group"
              onClick={() => fileInputRef.current?.click()}
            >
              <div className="h-16 w-16 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                <Upload className="h-8 w-8" />
              </div>
              <h3 className="text-lg font-semibold text-on-surface">
                Click to upload or drag and drop
              </h3>
              <p className="text-on-surface-variant text-sm mt-2">Support for .csv, .xlsx, .xls</p>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel"
                className="hidden"
              />
              <Button
                variant="outline"
                className="mt-6 gap-2"
                onClick={(e) => {
                  e.stopPropagation();
                  downloadTemplate();
                }}
              >
                <Download className="h-4 w-4" /> Download Template
              </Button>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="flex items-center justify-between p-3 bg-surface-container rounded-lg">
                <div className="flex items-center gap-3">
                  <div className="h-10 w-10 bg-primary/10 text-primary rounded-lg flex items-center justify-center">
                    <FileText className="h-6 w-6" />
                  </div>
                  <div>
                    <p className="font-medium text-on-surface">{file.name}</p>
                    <p className="text-xs text-on-surface-variant">
                      {(file.size / 1024).toFixed(1)} KB
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => {
                    setFile(null);
                    setPreviewData([]);
                  }}
                  className="text-error hover:bg-error/10 p-2 rounded-lg transition-colors"
                >
                  <X className="h-4 w-4" />
                </button>
              </div>

              {previewData.length > 0 && (
                <div className="border border-outline-variant rounded-lg overflow-hidden">
                  <div className="bg-surface-container-low px-4 py-2 border-b border-outline-variant text-xs font-bold text-on-surface-variant uppercase tracking-wider">
                    Data Preview (First 5 rows)
                  </div>
                  <div className="overflow-x-auto">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead className="text-xs">Name</TableHead>
                          <TableHead className="text-xs">SKU</TableHead>
                          <TableHead className="text-xs">Price</TableHead>
                          <TableHead className="text-xs">Stock</TableHead>
                          <TableHead className="text-xs">Image</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {previewData.map((row, i) => (
                          <TableRow key={i}>
                            <TableCell className="text-xs truncate max-w-[150px]">
                              {row.Name || row.name || '-'}
                            </TableCell>
                            <TableCell className="text-xs font-mono">
                              {row.SKU || row.sku || '-'}
                            </TableCell>
                            <TableCell className="text-xs">
                              ₹{row.Price || row.price || '0'}
                            </TableCell>
                            <TableCell className="text-xs">
                              {row.Stock || row.stock || row.stock_quantity || '0'}
                            </TableCell>
                            <TableCell className="text-xs truncate max-w-[100px]">
                              {row['Image Link'] ||
                                row.image_link ||
                                row.ImageUrl ||
                                row.image_url ||
                                '-'}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </div>
              )}

              {error && (
                <div className="flex items-center gap-3 p-4 bg-error/10 border border-error/20 text-error rounded-lg">
                  <AlertCircle className="h-5 w-5 shrink-0" />
                  <p className="text-sm font-medium">{error}</p>
                </div>
              )}

              {successCount > 0 && (
                <div className="flex items-center gap-3 p-4 bg-success/10 border border-success/20 text-success rounded-lg">
                  <Check className="h-5 w-5 shrink-0" />
                  <p className="text-sm font-medium">
                    Successfully imported {successCount} products!
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center justify-end gap-3 p-4 border-t border-outline-variant bg-surface-container-low/50">
          <Button variant="outline" onClick={onClose} disabled={importing}>
            Cancel
          </Button>
          <Button
            onClick={handleImport}
            disabled={!file || importing || !!successCount}
            className="min-w-[120px] gap-2"
          >
            {importing ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Check className="h-4 w-4" />
            )}
            {importing ? 'Importing...' : 'Start Import'}
          </Button>
        </div>
      </Card>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { AdminService } from '@byteevolvr/api-client';
import {
  Loader2,
  Clock,
  MessageSquare,
  CheckCircle2,
  Package,
  Truck,
  X,
  PlusCircle,
  RotateCcw,
  DollarSign,
} from 'lucide-react';
import { Badge } from '@byteevolvr/ui';

interface ActivityLog {
  id: string;
  status: string;
  notes: string;
  created_at: string;
  user_profiles?: {
    full_name: string;
  };
}

export function OrderActivityLogs({ orderId }: { orderId: string }) {
  const [logs, setLogs] = useState<ActivityLog[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchLogs = async () => {
    try {
      const data = await AdminService.getOrderActivity(orderId);
      setLogs(data || []);
    } catch (err) {
      console.error('Error fetching logs:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs(); // eslint-disable-line react-hooks/set-state-in-effect // eslint-disable-line @typescript-eslint/no-floating-promises
  }, [orderId]); // eslint-disable-line react-hooks/exhaustive-deps

  if (loading)
    return (
      <div className="flex justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-primary" />
      </div>
    );

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'delivered':
        return <CheckCircle2 className="h-4 w-4 text-success" />;
      case 'shipped':
        return <Truck className="h-4 w-4 text-info" />;
      case 'packed':
        return <Package className="h-4 w-4 text-indigo-500" />;
      case 'confirmed':
        return <PlusCircle className="h-4 w-4 text-primary" />;
      case 'cancelled':
        return <X className="h-4 w-4 text-error" />;
      case 'returned':
        return <RotateCcw className="h-4 w-4 text-warning" />;
      case 'refunded':
        return <DollarSign className="h-4 w-4 text-success" />;
      default:
        return <Clock className="h-4 w-4 text-on-surface-variant" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'delivered':
        return 'border-success bg-success/10';
      case 'shipped':
        return 'border-info bg-info/10';
      case 'packed':
        return 'border-indigo-500 bg-indigo-50';
      case 'confirmed':
        return 'border-primary bg-primary/10';
      case 'cancelled':
        return 'border-error bg-error/10';
      case 'returned':
        return 'border-warning bg-warning/10';
      case 'refunded':
        return 'border-success bg-success/10';
      default:
        return 'border-outline-variant bg-surface-container';
    }
  };

  return (
    <div className="space-y-6">
      {logs.length === 0 ? (
        <p className="text-center text-on-surface-variant italic py-4">
          No activity logs found for this order.
        </p>
      ) : (
        <div className="relative space-y-8 before:absolute before:inset-0 before:ml-5 before:-translate-x-px before:h-full before:w-0.5 before:bg-outline-variant">
          {logs.map((log) => (
            <div key={log.id} className="relative flex items-start gap-6">
              <div
                className={`absolute left-0 h-10 w-10 rounded-full border flex items-center justify-center z-10 ${getStatusColor(log.status)}`}
              >
                {getStatusIcon(log.status)}
              </div>
              <div className="ml-10 flex-1 pt-0.5">
                <div className="flex items-center justify-between gap-2 mb-1">
                  <div className="flex items-center gap-2">
                    <Badge
                      variant={
                        ['delivered', 'refunded'].includes(log.status)
                          ? 'success'
                          : ['cancelled'].includes(log.status)
                            ? 'error'
                            : 'secondary'
                      }
                      className="capitalize"
                    >
                      {log.status}
                    </Badge>
                    <span className="text-sm font-bold text-on-surface">
                      {log.user_profiles?.full_name || 'System'}
                    </span>
                  </div>
                  <time className="text-[10px] font-medium text-on-surface-variant uppercase">
                    {new Date(log.created_at).toLocaleString()}
                  </time>
                </div>
                {log.notes && (
                  <div className="p-3 rounded-xl bg-surface-container-low border border-outline-variant flex gap-3 items-start">
                    <MessageSquare className="h-3 w-3 mt-1 text-on-surface-variant opacity-50" />
                    <p className="text-sm text-on-surface-variant leading-relaxed">{log.notes}</p>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Button, Input } from '@byteevolvr/ui';
import { Package, Warehouse, Info, Loader2, X, ChevronDown } from 'lucide-react';

import { useAdmin } from '../modules/admin/hooks/useAdmin';

interface Props {
  product: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export function StockAdjustmentModal({ product, isOpen, onClose, onSuccess }: Props) {
  const [warehouseId, setWarehouseId] = useState('');
  const [quantity, setQuantity] = useState(0);
  const [type, setType] = useState<'in' | 'out' | 'adjustment' | 'return'>('adjustment');
  const [notes, setNotes] = useState('');
  const { warehouses, adjustStock, isUpdating, fetchWarehouses } = useAdmin();

  useEffect(() => {
    if (isOpen) {
      fetchWarehouses(); // eslint-disable-line @typescript-eslint/no-floating-promises
    }
  }, [isOpen]); // eslint-disable-line react-hooks/exhaustive-deps

  const handleAdjust = async () => {
    if (!warehouseId || quantity === 0) return;
    try {
      await adjustStock({
        productId: product.id,
        warehouseId,
        quantity: type === 'out' ? -Math.abs(quantity) : quantity,
        type,
        notes,
      });
      onSuccess();
      onClose();
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      console.error('Adjustment failed:', err);
      const errorMessage =
        err.response?.data?.message ||
        err.customMessage ||
        'Adjustment failed. Please check your stock and warehouse selection.';
      alert(errorMessage);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-md" onClick={onClose} />
      <div
        className="relative bg-surface w-full max-w-[500px] min-w-[320px] shadow-2xl rounded-3xl border border-white/10 flex flex-col overflow-hidden animate-in zoom-in-95 duration-200"
        style={{ width: '500px' }}
      >
        <div className="p-6 border-b border-outline-variant flex justify-between items-center bg-surface-container-low">
          <div className="flex items-center gap-4">
            <div className="h-12 w-12 rounded-2xl bg-primary/10 flex items-center justify-center text-primary shadow-inner">
              <Package className="h-6 w-6" />
            </div>
            <div>
              <h3 className="text-xl font-black text-on-surface tracking-tight uppercase">
                Adjust Stock
              </h3>
              <p className="text-xs font-bold text-on-surface-variant truncate max-w-[280px]">
                {product.name}
              </p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="rounded-full h-10 w-10 p-0 hover:bg-error/10 hover:text-error transition-all"
          >
            <X className="h-5 w-5" />
          </Button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar">
          <div className="p-8 space-y-8">
            <div className="space-y-3 relative">
              <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 flex items-center gap-2">
                <Warehouse className="h-3 w-3" /> Select Warehouse
              </label>
              <div className="relative">
                <select
                  className="w-full h-14 px-4 pr-12 rounded-2xl border border-outline bg-surface text-on-surface font-bold focus:ring-2 focus:ring-primary focus:outline-none transition-all cursor-pointer hover:border-primary/50 appearance-none"
                  value={warehouseId}
                  onChange={(e) => setWarehouseId(e.target.value)}
                >
                  <option value="">Choose a warehouse...</option>
                  {warehouses.map((w) => (
                    <option key={w.id} value={w.id}>
                      {w.name}
                    </option>
                  ))}
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 h-5 w-5 text-on-surface-variant pointer-events-none" />
              </div>
              {warehouses.length === 0 && (
                <p className="text-[10px] text-error font-bold ml-1 uppercase">
                  No active warehouses found
                </p>
              )}
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-3 relative">
                <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1">
                  Operation Type
                </label>
                <div className="relative">
                  <select
                    className="w-full h-14 px-4 pr-12 rounded-2xl border border-outline bg-surface text-on-surface font-bold focus:ring-2 focus:ring-primary focus:outline-none transition-all cursor-pointer hover:border-primary/50 appearance-none"
                    value={type}
                    onChange={(e) => setType(e.target.value as any)} // eslint-disable-line @typescript-eslint/no-explicit-any
                  >
                    <option value="in">Restock (+)</option>
                    <option value="out">Reduce (-)</option>
                    <option value="adjustment">Manual Adjustment</option>
                    <option value="return">Customer Return (+)</option>
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 h-5 w-5 text-on-surface-variant pointer-events-none" />
                </div>
              </div>
              <div className="space-y-3">
                <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1">
                  Quantity
                </label>
                <Input
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(parseInt(e.target.value) || 0)}
                  className="h-14 rounded-2xl text-lg font-black border-outline focus:ring-primary"
                />
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 flex items-center gap-2">
                <Info className="h-3 w-3" /> Adjustment Notes
              </label>
              <Input
                placeholder="Why are you adjusting this stock?"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="h-14 rounded-2xl font-medium border-outline focus:ring-primary"
              />
            </div>

            <div className="pt-6 flex gap-4">
              <Button
                variant="ghost"
                onClick={onClose}
                className="flex-1 h-14 rounded-2xl font-black uppercase tracking-widest hover:bg-surface-container"
              >
                Cancel
              </Button>
              <Button
                onClick={handleAdjust}
                disabled={isUpdating || !warehouseId || quantity === 0}
                className="flex-1 h-14 rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-primary/20"
              >
                {isUpdating ? <Loader2 className="h-5 w-5 animate-spin" /> : 'Confirm Update'}
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { AdminService } from '@byteevolvr/api-client';
import {
  Loader2,
  X,
  Clock,
  ArrowRightLeft,
  ArrowUpRight,
  ArrowDownRight,
  Info,
} from 'lucide-react';
import { Button, Badge } from '@byteevolvr/ui';

export function StockMovementHistoryModal({
  product,
  isOpen,
  onClose,
}: {
  product: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  isOpen: boolean;
  onClose: () => void;
}) {
  const [movements, setMovements] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (isOpen && product) {
      setLoading(true); // eslint-disable-line react-hooks/set-state-in-effect
      AdminService.getStockMovements(product.id)
        .then((data) => setMovements(data || []))
        .catch((err) => console.error(err))
        .finally(() => setLoading(false));
    }
  }, [isOpen, product]);

  if (!isOpen) return null;

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'in':
        return <ArrowDownRight className="h-4 w-4 text-emerald-500" />;
      case 'out':
        return <ArrowUpRight className="h-4 w-4 text-rose-500" />;
      case 'transfer':
        return <ArrowRightLeft className="h-4 w-4 text-indigo-500" />;
      case 'adjustment':
        return <Info className="h-4 w-4 text-warning" />;
      case 'return':
        return <ArrowDownRight className="h-4 w-4 text-orange-500" />;
      default:
        return <Clock className="h-4 w-4 text-on-surface-variant" />;
    }
  };

  const getTypeBadgeVariant = (type: string) => {
    switch (type) {
      case 'in':
        return 'success';
      case 'out':
        return 'error';
      case 'transfer':
        return 'primary';
      case 'adjustment':
        return 'warning';
      case 'return':
        return 'warning';
      default:
        return 'secondary';
    }
  };

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-surface w-full max-w-[600px] shadow-2xl rounded-3xl border border-white/10 flex flex-col overflow-hidden animate-in zoom-in-95 duration-200 h-[80vh]">
        <div className="p-6 border-b border-outline-variant flex justify-between items-center bg-surface-container-low shrink-0">
          <div className="flex items-center gap-4">
            <div className="h-12 w-12 rounded-2xl bg-indigo-600/10 flex items-center justify-center text-indigo-400 shadow-inner">
              <Clock className="h-6 w-6" />
            </div>
            <div>
              <h3 className="text-xl font-bold text-on-surface">Movement History</h3>
              <p className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest">
                {product.name} (SKU: {product.sku})
              </p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-10 w-10 p-0 rounded-xl hover:bg-surface-container"
          >
            <X className="h-5 w-5" />
          </Button>
        </div>

        <div className="p-6 overflow-y-auto flex-1 space-y-6">
          {loading ? (
            <div className="flex justify-center p-12">
              <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
          ) : movements.length === 0 ? (
            <div className="text-center p-12 text-on-surface-variant italic">
              No stock movements recorded for this item.
            </div>
          ) : (
            <div className="relative space-y-8 before:absolute before:inset-0 before:ml-5 before:-translate-x-px before:h-full before:w-0.5 before:bg-outline-variant">
              {movements.map((mov) => (
                <div key={mov.id} className="relative flex items-start gap-6">
                  <div
                    className={`absolute left-0 h-10 w-10 rounded-full border bg-surface-container-lowest flex items-center justify-center z-10`}
                  >
                    {getTypeIcon(mov.type)}
                  </div>
                  <div className="ml-10 flex-1 pt-0.5">
                    <div className="flex flex-wrap items-center justify-between gap-2 mb-1">
                      <div className="flex items-center gap-2">
                        <Badge variant={getTypeBadgeVariant(mov.type)} className="capitalize">
                          {mov.type}
                        </Badge>
                        <span
                          className={`text-sm font-black ${mov.quantity > 0 ? 'text-emerald-500' : 'text-rose-500'}`}
                        >
                          {mov.quantity > 0 ? '+' : ''}
                          {mov.quantity}
                        </span>
                        <span className="text-sm font-bold text-on-surface-variant">
                          • {mov.warehouse_name}
                        </span>
                      </div>
                      <time className="text-[10px] font-medium text-on-surface-variant uppercase">
                        {new Date(mov.created_at).toLocaleString()}
                      </time>
                    </div>
                    {mov.notes && (
                      <p className="text-sm text-on-surface-variant mt-2 bg-surface-container-low p-3 rounded-xl border border-outline-variant">
                        {mov.notes}
                      </p>
                    )}
                    {mov.user_profiles?.full_name && (
                      <p className="text-[10px] text-on-surface-variant uppercase tracking-widest mt-2 font-bold">
                        By {mov.user_profiles.full_name}
                      </p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { AdminService } from '@byteevolvr/api-client';
import { Loader2, X, ArrowRightLeft } from 'lucide-react';
import { Button, Input } from '@byteevolvr/ui';

export function WarehouseTransferModal({
  product,
  warehouses,
  isOpen,
  onClose,
  onSuccess,
}: {
  product: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  warehouses: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}) {
  const [fromWarehouse, setFromWarehouse] = useState('');
  const [toWarehouse, setToWarehouse] = useState('');
  const [quantity, setQuantity] = useState('');
  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleTransfer = async () => {
    if (!fromWarehouse || !toWarehouse || !quantity) {
      setError('Please fill out all required fields.');
      return;
    }
    if (fromWarehouse === toWarehouse) {
      setError('Source and destination warehouses must be different.');
      return;
    }
    if (Number(quantity) <= 0) {
      setError('Quantity must be greater than zero.');
      return;
    }

    setLoading(true);
    setError('');
    try {
      await AdminService.transferStock({
        productId: product.id,
        fromWarehouseId: fromWarehouse,
        toWarehouseId: toWarehouse,
        quantity: Number(quantity),
        notes,
      });
      onSuccess();
      onClose();
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err?.response?.data?.message || err.message || 'Transfer failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-surface w-full max-w-[500px] shadow-2xl rounded-3xl border border-white/10 flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-outline-variant flex justify-between items-center bg-indigo-50 dark:bg-indigo-950/20">
          <div className="flex items-center gap-4">
            <div className="h-12 w-12 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-500 shadow-inner">
              <ArrowRightLeft className="h-6 w-6" />
            </div>
            <div>
              <h3 className="text-xl font-bold text-on-surface">Transfer Stock</h3>
              <p className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest">
                {product.name} (SKU: {product.sku})
              </p>
            </div>
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-10 w-10 p-0 rounded-xl hover:bg-surface-container"
          >
            <X className="h-5 w-5" />
          </Button>
        </div>

        <div className="p-6 space-y-6">
          {error && (
            <div className="p-4 bg-error/10 text-error rounded-xl text-sm font-medium border border-error/20">
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 block mb-2">
                From Warehouse
              </label>
              <select
                className="w-full h-12 px-4 rounded-2xl border border-outline bg-surface text-on-surface font-bold focus:ring-2 focus:ring-indigo-500 focus:outline-none appearance-none"
                value={fromWarehouse}
                onChange={(e) => setFromWarehouse(e.target.value)}
              >
                <option value="">Select Origin</option>
                {warehouses.map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.name}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 block mb-2">
                To Warehouse
              </label>
              <select
                className="w-full h-12 px-4 rounded-2xl border border-outline bg-surface text-on-surface font-bold focus:ring-2 focus:ring-indigo-500 focus:outline-none appearance-none"
                value={toWarehouse}
                onChange={(e) => setToWarehouse(e.target.value)}
              >
                <option value="">Select Destination</option>
                {warehouses.map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.name}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 block mb-2">
                Transfer Quantity
              </label>
              <Input
                type="number"
                value={quantity}
                onChange={(e) => setQuantity(e.target.value)}
                placeholder="Enter quantity"
                className="h-12 rounded-2xl border-outline focus:ring-indigo-500"
              />
            </div>

            <div>
              <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 block mb-2">
                Notes (Optional)
              </label>
              <Input
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="e.g. Replenishment"
                className="h-12 rounded-2xl border-outline focus:ring-indigo-500"
              />
            </div>
          </div>

          <div className="flex gap-3 pt-4">
            <Button
              variant="ghost"
              onClick={onClose}
              className="flex-1 h-12 rounded-2xl font-black uppercase tracking-widest"
            >
              Cancel
            </Button>
            <Button
              onClick={handleTransfer}
              disabled={loading || !fromWarehouse || !toWarehouse || !quantity}
              className="flex-1 h-12 rounded-2xl bg-indigo-600 hover:bg-indigo-700 font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 text-white"
            >
              {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'Confirm Transfer'}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useCallback } from 'react';
import { AdminService } from '@byteevolvr/api-client';
import { useAdminStore } from '@byteevolvr/store';

export const useAdmin = () => {
  const { stats, setStats, recentSales, setRecentSales, chartData, setChartData, error, setError } =
    useAdminStore();

  const [isUpdating, setIsUpdating] = useState(false);
  const [isDashboardLoading, setDashboardLoading] = useState(false);

  const fetchDashboardData = useCallback(async () => {
    setDashboardLoading(true);
    setError(null);
    try {
      const statsData = await AdminService.getDashboardStats();
      const [recentOrdersData, chartDataRaw] = await Promise.all([
        AdminService.getOrders({ limit: 5 }),
        AdminService.getRevenueChart(6),
      ]);

      setStats(statsData);
      setRecentSales(recentOrdersData?.data || recentOrdersData || []);
      setChartData(chartDataRaw || []);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to fetch dashboard data');
    } finally {
      setDashboardLoading(false);
    }
  }, [setError, setStats, setRecentSales, setChartData]);

  const fetchOrderDetail = async (id: string) => {
    try {
      const orderData = await AdminService.getOrderDetail(id);
      return orderData;
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to fetch order details');
      return null;
    }
  };

  const updateOrderStatus = async (orderId: string, data: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
    setIsUpdating(true);
    try {
      await AdminService.updateOrderStatus(orderId, data);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to update order status');
      throw err;
    } finally {
      setIsUpdating(false);
    }
  };

  const getCustomers = async () => {
    try {
      const data = await AdminService.getCustomers();
      return data;
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to fetch customers');
      return [];
    }
  };

  const [warehouses, setWarehouses] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any

  const fetchWarehouses = async () => {
    try {
      const data = await AdminService.getWarehouses();
      setWarehouses(data || []);
      return data;
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to fetch warehouses');
      return [];
    }
  };

  const adjustStock = async (data: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
    setIsUpdating(true);
    try {
      await AdminService.adjustStock(data);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to adjust stock');
      throw err;
    } finally {
      setIsUpdating(false);
    }
  };

  return {
    stats,
    recentSales,
    chartData,
    isLoading: isDashboardLoading,
    error,
    warehouses,
    fetchDashboardData,
    fetchOrderDetail,
    updateOrderStatus,
    getCustomers,
    fetchWarehouses,
    adjustStock,
    isUpdating,
  };
};

import { apiClient } from '@byteevolvr/api-client';

export const AdminService = {
  async getDashboardStats() {
    const response = await apiClient.get('/admin/stats');
    return response.data;
  },

  async getOrders(params?: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
    const response = await apiClient.get('/admin/orders', { params });
    return response.data;
  },

  async getOrderDetail(id: string) {
    const response = await apiClient.get(`/admin/orders/${id}`);
    return response.data;
  },

  async updateOrderStatus(
    orderId: string,
    data: { status?: string; trackingId?: string; courier?: string }
  ) {
    const response = await apiClient.put(`/admin/orders/${orderId}`, data);
    return response.data;
  },

  async getProducts() {
    const response = await apiClient.get('/admin/products');
    return response.data;
  },

  async getCustomers() {
    const response = await apiClient.get('/admin/customers');
    return response.data;
  },
};

