import { apiClient, MarketingService } from '@byteevolvr/api-client';

export function CampaignBuilder() {
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true);

  const [segments, setSegments] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [emailTemplates, setEmailTemplates] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [pushTemplates, setPushTemplates] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  // Assuming whatsappTemplates can be fetched similarly if added to MarketingService. For now we will just use custom_content for WA if template isn't available.

  const [campaign, setCampaign] = useState({
    name: '',
    type: 'email',
    segment_id: '',
    template_id: '',
    custom_content: '',
    scheduled_at: '',
    whatsapp_provider_override: '',
  });

  useEffect(() => {
    const loadData = async () => {
      try {
        const [segs, eTpls, pTpls] = await Promise.all([
          MarketingService.getSegments(),
          MarketingService.getEmailTemplates(),
          MarketingService.getPushTemplates(),
        ]);
        setSegments(segs || []);
        setEmailTemplates(eTpls || []);
        setPushTemplates(pTpls || []);
      } catch (err) {
        console.error('Failed to fetch data for campaign builder', err);
      } finally {
        setFetching(false);
      }
    };
    loadData(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

