  const [emailTemplates, setEmailTemplates] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [pushTemplates, setPushTemplates] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any

  const [newTemplate, setNewTemplate] = useState({
    name: '',
    subject: '',
    title: '',
    body: '',
    html_content: '',
  });

  const loadTemplates = async () => {
    setLoading(true);
    try {
      const [eTpls, pTpls] = await Promise.all([
        MarketingService.getEmailTemplates(),
        MarketingService.getPushTemplates(),
      ]);
      setEmailTemplates(eTpls || []);
      setPushTemplates(pTpls || []);
    } catch (err) {
      console.error('Failed to load templates', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTemplates(); // eslint-disable-line react-hooks/set-state-in-effect // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  const handleCreate = async () => {
    setSaving(true);
    try {
      if (activeTab === 'email') {
        await MarketingService.createEmailTemplate({
          name: newTemplate.name,
          subject: newTemplate.subject,
          html_content: newTemplate.html_content,
        });
      } else if (activeTab === 'push') {
        await MarketingService.createPushTemplate({
          name: newTemplate.name,
          title: newTemplate.title,
          body: newTemplate.body,
        });
      }
      setShowModal(false);
      setNewTemplate({ name: '', subject: '', title: '', body: '', html_content: '' });
      await loadTemplates();
    } catch (err) {
      console.error('Failed to create template', err);
      alert('Failed to create template');
    } finally {
      setSaving(false);
    }
  };

  const currentList = activeTab === 'email' ? emailTemplates : pushTemplates;

  if (loading) {
    return (
      <div className="h-[60vh] flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-6xl">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-display-sm font-semibold text-on-background">Template Manager</h1>
          <p className="text-body-sm text-on-surface-variant mt-1">
            Design and manage reusable campaign templates
          </p>
        </div>
        <Button className="gap-2" onClick={() => setShowModal(true)}>
          <Plus className="h-4 w-4" />
          Create Template
        </Button>
      </div>

      <div className="flex gap-4 border-b border-outline">
        <button
          className={`pb-2 px-1 text-label-md font-medium border-b-2 transition-colors ${
            activeTab === 'email'
              ? 'border-primary text-primary'
              : 'border-transparent text-on-surface-variant hover:text-on-surface'
          }`}
          onClick={() => setActiveTab('email')}
        >
          Email Templates
        </button>
        <button
          className={`pb-2 px-1 text-label-md font-medium border-b-2 transition-colors ${
            activeTab === 'push'
              ? 'border-primary text-primary'
              : 'border-transparent text-on-surface-variant hover:text-on-surface'
          }`}
          onClick={() => setActiveTab('push')}
        >
          Push Notifications
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-6">
        {currentList.length === 0 ? (
          <div className="col-span-3 text-center py-12 bg-surface rounded-xl border border-outline">
            <LayoutTemplate className="h-12 w-12 text-on-surface-variant mx-auto mb-4 opacity-50" />
            <p className="text-on-surface-variant">No templates found for this type.</p>
          </div>
        ) : (
          currentList.map((tpl) => (
            <Card key={tpl.id}>
              <div className="p-4">
                <div className="aspect-video bg-background border border-outline rounded-lg mb-4 flex items-center justify-center relative group">
                  <LayoutTemplate className="h-8 w-8 text-on-surface-variant opacity-20" />
                  <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center rounded-lg">
                    <Button variant="outline" className="bg-surface text-on-surface border-none">
                      Edit
                    </Button>
                  </div>
                </div>
                <h3 className="text-title-md font-medium mb-1">{tpl.name}</h3>
                <p className="text-body-sm text-on-surface-variant truncate">
                  {activeTab === 'email' ? `Subject: ${tpl.subject}` : `Title: ${tpl.title}`}
                </p>
              </div>
            </Card>
          ))
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm"
            onClick={() => setShowModal(false)}
          />
          <div className="relative bg-surface w-full max-w-[600px] shadow-xl rounded-2xl flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-outline-variant flex justify-between items-center bg-surface-container-low">
              <h2 className="text-xl font-bold text-on-surface">
                Create {activeTab === 'email' ? 'Email' : 'Push'} Template
              </h2>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowModal(false)}
                className="rounded-full h-8 w-8 p-0"
              >
                <X className="h-5 w-5" />
              </Button>
            </div>

            <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
              <Input
                label="Template Name"
                placeholder="e.g. Welcome Email"
                value={newTemplate.name}
                onChange={(e) => setNewTemplate({ ...newTemplate, name: e.target.value })}
              />

              {activeTab === 'email' && (
                <>
                  <Input
                    label="Email Subject"
                    placeholder="Welcome to ByteEvolvr!"
                    value={newTemplate.subject}
                    onChange={(e) => setNewTemplate({ ...newTemplate, subject: e.target.value })}
                  />
                  <div>
                    <label className="block text-sm font-medium text-on-surface-variant mb-1">
                      HTML Content
                    </label>
                    <textarea
                      className="w-full h-40 px-3 py-2 rounded-lg border border-outline bg-surface text-body-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary font-mono text-sm"
                      placeholder="<h1>Hello {{customer_name}}</h1>..."
                      value={newTemplate.html_content}
                      onChange={(e) =>
                        setNewTemplate({ ...newTemplate, html_content: e.target.value })
                      }
                    />
                  </div>
                </>
              )}

              {activeTab === 'push' && (
                <>
                  <Input
                    label="Push Title"
                    placeholder="Flash Sale!"
                    value={newTemplate.title}
                    onChange={(e) => setNewTemplate({ ...newTemplate, title: e.target.value })}
                  />
                  <div>
                    <label className="block text-sm font-medium text-on-surface-variant mb-1">
                      Push Body
                    </label>
                    <textarea
                      className="w-full h-24 px-3 py-2 rounded-lg border border-outline bg-surface text-body-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                      placeholder="Check out our new items..."
                      value={newTemplate.body}
                      onChange={(e) => setNewTemplate({ ...newTemplate, body: e.target.value })}
                    />
                  </div>
                </>
              )}
            </div>

            <div className="p-6 border-t border-outline-variant bg-surface-container-low flex justify-end gap-3">
              <Button variant="outline" onClick={() => setShowModal(false)}>
                Cancel
              </Button>
              <Button onClick={handleCreate} disabled={saving || !newTemplate.name}>
                {saving ? (
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                ) : (
                  <Plus className="h-4 w-4 mr-2" />
                )}
                Create Template
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useAdminStore } from '@byteevolvr/store';
import { ProductService } from '@byteevolvr/api-client';

import { ProductFormData } from '../types/product.types';

export const useProduct = () => {
  const { products, setProducts, error, setError } = useAdminStore();
  const [loading, setLoading] = useState(false);

  const fetchProducts = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await ProductService.getProducts();
      setProducts(data);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to fetch products');
    } finally {
      setLoading(false);
    }
  };

  const saveProduct = async (data: ProductFormData) => {
    setLoading(true);
    setError(null);
    try {
      if (data.id) {
        await ProductService.updateProduct(data.id, data);
      } else {
        await ProductService.createProduct(data);
      }
      await fetchProducts();
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to save product');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm('Are you sure you want to delete this product?')) return;

    setLoading(true);
    setError(null);
    try {
      await ProductService.deleteProduct(id);
      await fetchProducts();
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to delete product');
    } finally {
      setLoading(false);
    }
  };

  return {
    products,
    loading,
    error,
    fetchProducts,
    saveProduct,
    deleteProduct,
  };
};

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  original_price?: number;
  image_url?: string;
  category: string;
  brand?: string;
  sku: string;
  stock_quantity: number;
  status: 'active' | 'draft' | 'out_of_stock';
  featured?: boolean;
  sort_order?: number;
  specifications?: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  qna?: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  created_at: string;
}

export interface ProductFormData extends Omit<Product, 'id' | 'created_at'> {
  id?: string;
}

import React, { useState } from 'react';
import { Card, Button } from '@byteevolvr/ui';
import { toast } from 'sonner';
import { apiClient } from '@byteevolvr/api-client';
import * as XLSX from 'xlsx';
import { UploadCloud, MessageSquare, List } from 'lucide-react';

export const WhatsAppCampaigns = () => {
  const [activeTab, setActiveTab] = useState<'single' | 'bulk'>('single');
  const [to, setTo] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [bulkFile, setBulkFile] = useState<File | null>(null);
  const [bulkPreview, setBulkPreview] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [bulkManualNumbers, setBulkManualNumbers] = useState('');
  const [bulkMessage, setBulkMessage] = useState('');

  // Ref guards to prevent double-submission from React StrictMode or rapid clicks
  const singleSendingRef = React.useRef(false);
  const bulkSendingRef = React.useRef(false);

  const updateManualPreview = (nums: string, msg: string) => {
    if (!nums.trim() || !msg.trim()) {
      setBulkPreview([]);
      return;
    }

    const numbersList = nums
      .split(/[\n,]+/)
      .map((n) => n.trim())
      .filter(Boolean);
    const mapped = numbersList.map((n) => ({
      to: n,
      message: msg,
    }));
    setBulkPreview(mapped);
  };

  const handleSendTest = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!to || !message) return toast.error('Phone and message required');
    if (singleSendingRef.current) return;
    singleSendingRef.current = true;
    setLoading(true);
    try {
      await apiClient.post('/whatsapp/test-message', { to, message });
      toast.success('✅ Message queued successfully! Check Task Queue for status.');
      setTo('');
      setMessage('');
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      const msg =
        err?.customMessage ||
        err?.response?.data?.message ||
        err?.message ||
        'Failed to queue message';
      toast.error(`❌ ${msg}`);
    } finally {
      singleSendingRef.current = false;
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setBulkFile(file);

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws);

      const mapped = data
        .map((row: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
          // Try to find columns for phone and message flexibly
          const phoneKey = Object.keys(row).find(
            (k) =>
              k.toLowerCase().includes('phone') ||
              k.toLowerCase().includes('number') ||
              k.toLowerCase().includes('to')
          );
          const msgKey = Object.keys(row).find(
            (k) => k.toLowerCase().includes('message') || k.toLowerCase().includes('content')
          );

          return {
            to: phoneKey ? row[phoneKey].toString() : '',
            message: msgKey ? row[msgKey] : '',
          };
        })
        .filter((r) => r.to && r.message);

      setBulkPreview(mapped);
      if (mapped.length === 0) {
        toast.error('Could not find Phone and Message columns in the file.');
      } else {
        toast.success(`Found ${mapped.length} valid entries.`);
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleSendBulk = async () => {
    if (bulkPreview.length === 0) return toast.error('No valid messages found to send');
    if (bulkSendingRef.current) return;
    bulkSendingRef.current = true;
    setLoading(true);
    try {
      await apiClient.post('/whatsapp/bulk-campaign', { messages: bulkPreview });
      toast.success(`✅ Queued ${bulkPreview.length} messages! Monitor progress in Task Queue.`);
      setBulkFile(null);
      setBulkPreview([]);
      setBulkManualNumbers('');
      setBulkMessage('');
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      const msg =
        err?.customMessage ||
        err?.response?.data?.message ||
        err?.message ||
        'Failed to queue bulk campaign';
      toast.error(`❌ ${msg}`);
    } finally {
      bulkSendingRef.current = false;
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold tracking-tight text-white">WhatsApp Campaigns & Testing</h1>

      <div className="flex gap-4 border-b border-outline-variant pb-2">
        <button
          onClick={() => setActiveTab('single')}
          className={`flex items-center gap-2 px-4 py-2 text-sm font-medium transition-colors ${
            activeTab === 'single'
              ? 'text-primary border-b-2 border-primary'
              : 'text-on-surface-variant hover:text-on-surface'
          }`}
        >
          <MessageSquare className="w-4 h-4" /> Single Message
        </button>
        <button
          onClick={() => setActiveTab('bulk')}
          className={`flex items-center gap-2 px-4 py-2 text-sm font-medium transition-colors ${
            activeTab === 'bulk'
              ? 'text-primary border-b-2 border-primary'
              : 'text-on-surface-variant hover:text-on-surface'
          }`}
        >
          <List className="w-4 h-4" /> Bulk Excel Campaign
        </button>
      </div>

      <Card className="bg-card max-w-2xl">
        {activeTab === 'single' ? (
          <>
            <div>
              <div>Send Manual Test Message</div>
            </div>
            <div>
              <form onSubmit={handleSendTest} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-muted-foreground mb-1">
                    Phone Number (with country code)
                  </label>
                  <input
                    type="text"
                    className="w-full bg-background border border-border rounded-md px-3 py-2 text-white"
                    placeholder="e.g. 1234567890"
                    value={to}
                    onChange={(e) => setTo(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-muted-foreground mb-1">
                    Message Content
                  </label>
                  <textarea
                    className="w-full bg-background border border-border rounded-md px-3 py-2 text-white h-32"
                    placeholder="Hello from ByteEvolvr..."
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                  />
                </div>
                <Button type="submit" disabled={loading} className="w-full">
                  {loading ? 'Queueing...' : 'Send Message'}
                </Button>
              </form>
            </div>
          </>
        ) : (
          <>
            <div>
              <div>Upload Bulk List (Excel/CSV)</div>
            </div>
            <div>
              <div className="space-y-6">
                <div className="border-2 border-dashed border-outline-variant rounded-xl p-8 text-center hover:bg-surface-container transition-colors cursor-pointer relative">
                  <input
                    type="file"
                    accept=".xlsx, .xls, .csv"
                    onChange={handleFileUpload}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  />
                  <UploadCloud className="w-8 h-8 mx-auto text-primary mb-3" />
                  <h3 className="text-sm font-medium text-on-surface mb-1">
                    {bulkFile ? bulkFile.name : 'Click or drag Excel/CSV file here'}
                  </h3>
                  <p className="text-xs text-on-surface-variant mt-2">Or paste numbers below</p>
                </div>

                <div className="space-y-4 pt-4 border-t border-outline-variant">
                  <h3 className="text-sm font-medium text-on-surface mb-2">Manual Input</h3>
                  <div>
                    <label className="block text-xs text-muted-foreground mb-1">
                      Comma or line separated numbers
                    </label>
                    <textarea
                      className="w-full bg-background border border-border rounded-md px-3 py-2 text-white h-24"
                      placeholder="e.g. 1234567890, 0987654321&#10;1122334455"
                      value={bulkManualNumbers}
                      onChange={(e) => {
                        setBulkManualNumbers(e.target.value);
                        updateManualPreview(e.target.value, bulkMessage);
                      }}
                    />
                  </div>
                  <div>
                    <label className="block text-xs text-muted-foreground mb-1">
                      Message Content for Manual Numbers
                    </label>
                    <textarea
                      className="w-full bg-background border border-border rounded-md px-3 py-2 text-white h-24"
                      placeholder="Your promotional message here..."
                      value={bulkMessage}
                      onChange={(e) => {
                        setBulkMessage(e.target.value);
                        updateManualPreview(bulkManualNumbers, e.target.value);
                      }}
                    />
                  </div>
                </div>

                {bulkPreview.length > 0 && (
                  <div className="bg-surface-container rounded-lg p-4 max-h-64 overflow-y-auto">
                    <h4 className="text-sm font-semibold mb-3 flex items-center justify-between">
                      Preview ({bulkPreview.length} items)
                    </h4>
                    <table className="w-full text-xs text-left">
                      <thead>
                        <tr className="text-on-surface-variant">
                          <th className="pb-2">Phone</th>
                          <th className="pb-2">Message</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-outline-variant">
                        {bulkPreview.slice(0, 50).map((row, i) => (
                          <tr key={i}>
                            <td className="py-2 text-on-surface">{row.to}</td>
                            <td
                              className="py-2 text-on-surface-variant max-w-[200px] truncate"
                              title={row.message}
                            >
                              {row.message}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {bulkPreview.length > 50 && (
                      <p className="text-center text-xs text-on-surface-variant mt-2 pt-2 border-t border-outline-variant">
                        ... and {bulkPreview.length - 50} more
                      </p>
                    )}
                  </div>
                )}

                <Button
                  onClick={handleSendBulk}
                  disabled={loading || bulkPreview.length === 0}
                  className="w-full"
                >
                  {loading
                    ? 'Queueing Campaign...'
                    : `Launch Bulk Campaign (${bulkPreview.length} messages)`}
                </Button>
              </div>
            </div>
          </>
        )}
      </Card>
    </div>
  );
};

