import React, { useEffect, useState } from 'react';
import { Card, Button } from '@byteevolvr/ui';
import {
  Loader2,
  RefreshCw,
  MessageCircle,
  CheckCircle2,
  XCircle,
  AlertCircle,
  Send,
  Phone,
  Building2,
  Key,
  Wifi,
  WifiOff,
} from 'lucide-react';
import { apiClient } from '@byteevolvr/api-client';
import { toast } from 'sonner';
import { useQuery } from '@tanstack/react-query';

import { WhatsAppProviderSettings } from './WhatsAppProviderSettings';

// ─── Types ────────────────────────────────────────────────────────────────────
interface SessionStatus {
  status: 'connected' | 'disconnected' | 'pending' | string;
  last_active: string | null;
}

interface SystemStatus {
  session: SessionStatus | null;
  failedCount: number;
}

interface HealthResult {
  connected: boolean;
  message: string;
  phoneInfo: {
    id: string;
    displayPhoneNumber: string;
    verifiedName: string;
  } | null;
}

// ─── Status Badge ─────────────────────────────────────────────────────────────
const StatusBadge = ({ status }: { status: string }) => {
  const isConnected = status === 'connected';
  const isPending = status === 'pending';
  return (
    <span
      className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold ${
        isConnected
          ? 'bg-green-500/20 text-green-400 ring-1 ring-green-500/30'
          : isPending
            ? 'bg-yellow-500/20 text-yellow-400 ring-1 ring-yellow-500/30'
            : 'bg-red-500/20 text-red-400 ring-1 ring-red-500/30'
      }`}
    >
      {isConnected ? <Wifi className="h-3 w-3" /> : <WifiOff className="h-3 w-3" />}
      {status.toUpperCase()}
    </span>
  );
};

// ─── Main Component ───────────────────────────────────────────────────────────
export const WhatsAppDashboard = () => { // eslint-disable-line complexity
  const [status, setStatus] = useState<SystemStatus | null>(null);
  const [logs, setLogs] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [verifying, setVerifying] = useState(false);
  const [healthResult, setHealthResult] = useState<HealthResult | null>(null);

  // Test message state
  const [testTo, setTestTo] = useState('');
  const [testMsg, setTestMsg] = useState('');
  const [sending, setSending] = useState(false);

  // ── Fetch Status & Logs with TanStack Query ────────────────────────────────
  const { data: statusData, refetch: fetchStatus } = useQuery({
    queryKey: ['whatsapp_status'],
    queryFn: async () => {
      const res = await apiClient.get(`/whatsapp/status`);
      return res.data;
    },
    refetchInterval: 15000,
  });

  const { data: logsData } = useQuery({
    queryKey: ['whatsapp_logs'],
    queryFn: async () => {
      const res = await apiClient.get('/whatsapp/logs?limit=15');
      return Array.isArray(res.data) ? res.data : [];
    },
    refetchInterval: 15000,
  });

  useEffect(() => {
    if (statusData) setStatus(statusData); // eslint-disable-line react-hooks/set-state-in-effect
    if (logsData) setLogs(logsData);
    setLoading(false);
  }, [statusData, logsData]);

  // ── Verify Webhook Connection ──────────────────────────────────────────────
  const checkWebhook = async (e: React.MouseEvent) => {
    e.preventDefault();
    setVerifying(true);
    setHealthResult(null);
    try {
      const res = await apiClient.get('/whatsapp/webhook/health');
      // res.data is already the unwrapped inner data object from the interceptor
      // The health endpoint returns { success, connected, message, phoneInfo }
      // After unwrapping: res.data = { connected, message, phoneInfo } if success was true
      // But our new endpoint doesn't wrap in { success, data } — it returns directly
      // So res.data will be the full { success, connected, message, phoneInfo }
      const payload = res.data;

      const isConnected = payload?.connected === true;
      const message = payload?.message || (isConnected ? 'Connected!' : 'Not connected');
      const phoneInfo = payload?.phoneInfo || null;

      setHealthResult({ connected: isConnected, message, phoneInfo });

      // Also refresh the session status to update the badge immediately
      await fetchStatus();

      if (isConnected) {
        toast.success(`✅ ${message}`);
      } else {
        toast.error(`❌ ${message}`);
      }
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      const msg =
        err?.customMessage || err?.message || 'Failed to reach backend. Check server logs.';
      setHealthResult({ connected: false, message: msg, phoneInfo: null });
      toast.error(msg);
    } finally {
      setVerifying(false);
    }
  };

  // Ref guard to prevent double-submissions from React StrictMode or rapid clicks
  const sendingRef = React.useRef(false);

  // ── Send Test Message ──────────────────────────────────────────────────────
  const sendTestMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const phone = testTo.trim();
    const message = testMsg.trim();

    if (!phone || !message) {
      toast.warning('Enter both a phone number and a message.');
      return;
    }

    // Guard: block if already in-flight
    if (sendingRef.current) return;
    sendingRef.current = true;
    setSending(true);
    try {
      await apiClient.post('/whatsapp/test-message', { to: phone, message });
      toast.success('Message queued successfully! Check Recent Messages below.');
      setTestMsg('');
      setTimeout(() => fetchStatus(), 2000);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      const msg = err?.customMessage || err?.message || 'Failed to send test message.';
      toast.error(msg);
    } finally {
      sendingRef.current = false;
      setSending(false);
    }
  };

  // Removed manual interval polling, TanStack Query handles it via refetchInterval

  const sessionStatus = status?.session?.status || 'disconnected';
  const lastActive = status?.session?.last_active;

  return (
    <div className="space-y-6">
      {/* ── Header ── */}
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
          <MessageCircle className="text-green-500 h-6 w-6" />
          WhatsApp Integration
        </h1>
        <Button
          onClick={() => fetchStatus()}
          variant="outline"
          disabled={loading}
          className="gap-2"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </Button>
      </div>

      {/* ── Status + Verify Row ── */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Connection Status Card */}
        <Card>
          <div>
            <div className="flex items-center gap-2">
              <Wifi className="h-4 w-4 text-green-500" />
              Cloud API Status
            </div>
          </div>
          <div className="space-y-4">
            {loading ? (
              <div className="flex items-center gap-2 text-muted-foreground">
                <Loader2 className="h-5 w-5 animate-spin" />
                Loading status...
              </div>
            ) : (
              <>
                <div className="flex justify-between items-center border-b border-border pb-3">
                  <span className="text-sm text-muted-foreground">Provider</span>
                  <span className="text-sm font-semibold text-blue-400">META CLOUD API</span>
                </div>
                <div className="flex justify-between items-center border-b border-border pb-3">
                  <span className="text-sm text-muted-foreground">Connection</span>
                  <StatusBadge status={sessionStatus} />
                </div>
                <div className="flex justify-between items-center border-b border-border pb-3">
                  <span className="text-sm text-muted-foreground">Last Webhook Event</span>
                  <span className="text-sm">
                    {lastActive ? new Date(lastActive).toLocaleString() : 'Never'}
                  </span>
                </div>
                <div className="flex justify-between items-center border-b border-border pb-3">
                  <span className="text-sm text-muted-foreground">Failed Messages</span>
                  <span
                    className={`text-sm font-bold ${(status?.failedCount || 0) > 0 ? 'text-red-400' : 'text-green-400'}`}
                  >
                    {status?.failedCount || 0}
                  </span>
                </div>

                {/* Verify Result */}
                {healthResult && (
                  <div
                    className={`flex items-start gap-2 p-3 rounded-lg text-sm ${
                      healthResult.connected
                        ? 'bg-green-500/10 text-green-400 border border-green-500/20'
                        : 'bg-red-500/10 text-red-400 border border-red-500/20'
                    }`}
                  >
                    {healthResult.connected ? (
                      <CheckCircle2 className="h-4 w-4 mt-0.5 shrink-0" />
                    ) : (
                      <XCircle className="h-4 w-4 mt-0.5 shrink-0" />
                    )}
                    <div>
                      <p className="font-medium">{healthResult.message}</p>
                      {healthResult.phoneInfo && (
                        <div className="mt-2 space-y-1 text-xs opacity-80">
                          <p className="flex items-center gap-1">
                            <Phone className="h-3 w-3" />{' '}
                            {healthResult.phoneInfo.displayPhoneNumber}
                          </p>
                          <p className="flex items-center gap-1">
                            <Building2 className="h-3 w-3" /> {healthResult.phoneInfo.verifiedName}
                          </p>
                          <p className="flex items-center gap-1">
                            <Key className="h-3 w-3" /> ID: {healthResult.phoneInfo.id}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                <div className="flex flex-col gap-2 pt-2">
                  <Button onClick={checkWebhook} disabled={verifying} className="w-full gap-2">
                    {verifying ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <Wifi className="h-4 w-4" />
                    )}
                    {verifying ? 'Verifying...' : 'Verify Webhook Connection'}
                  </Button>
                  <Button
                    variant="outline"
                    className="w-full gap-2"
                    onClick={() => (window.location.href = '/settings')}
                  >
                    <Key className="h-4 w-4" />
                    Configure API Credentials
                  </Button>
                </div>
              </>
            )}
          </div>
        </Card>

        {/* Test Message Card */}
        <Card>
          <div>
            <div className="flex items-center gap-2">
              <Send className="h-4 w-4 text-blue-400" />
              Send Test Message
            </div>
          </div>
          <div>
            <form onSubmit={sendTestMessage} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-muted-foreground mb-1">
                  Recipient Phone Number
                </label>
                <input
                  type="text"
                  value={testTo}
                  onChange={(e) => setTestTo(e.target.value)}
                  placeholder="919876543210 (no + or spaces)"
                  className="w-full rounded-md border border-border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Include country code without +. Example: 919876543210
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-muted-foreground mb-1">
                  Message
                </label>
                <textarea
                  value={testMsg}
                  onChange={(e) => setTestMsg(e.target.value)}
                  placeholder="Hello! This is a test message from ByteEvolvr."
                  rows={4}
                  className="w-full rounded-md border border-border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary resize-none"
                />
              </div>
              <div className="flex items-start gap-2 p-3 bg-amber-500/10 border border-amber-500/20 rounded-lg">
                <AlertCircle className="h-4 w-4 text-amber-400 mt-0.5 shrink-0" />
                <p className="text-xs text-amber-400">
                  You can only send messages to numbers that have messaged your WhatsApp Business
                  number first, OR use an approved message template.
                </p>
              </div>
              <Button type="submit" disabled={sending} className="w-full gap-2">
                {sending ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Send className="h-4 w-4" />
                )}
                {sending ? 'Sending...' : 'Send Test Message'}
              </Button>
            </form>
          </div>
        </Card>
      </div>

      {/* Multi-Provider Configuration */}
      <WhatsAppProviderSettings />

      {/* Recent Messages Log */}
      <Card>
        <div>
          <div className="flex items-center gap-2">
            <MessageCircle className="h-4 w-4" />
            Recent Messages
          </div>
        </div>
        <div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-muted-foreground uppercase bg-muted/50">
                <tr>
                  <th className="px-4 py-3">Recipient</th>
                  <th className="px-4 py-3">Message</th>
                  <th className="px-4 py-3">Provider</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Time</th>
                  <th className="px-4 py-3">Error</th>
                </tr>
              </thead>
              <tbody>
                {logs.map((log) => (
                  <tr
                    key={log.id}
                    className="border-b border-border hover:bg-muted/20 transition-colors"
                  >
                    <td className="px-4 py-3 font-mono text-xs">{log.recipient}</td>
                    <td
                      className="px-4 py-3 max-w-[180px] truncate text-muted-foreground"
                      title={log.payload?.content}
                    >
                      {log.payload?.content || '—'}
                    </td>
                    <td className="px-4 py-3 text-xs uppercase text-muted-foreground font-semibold">
                      {log.provider_used || 'unknown'}
                    </td>
                    <td className="px-4 py-3">
                      <span
                        className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                          log.status === 'delivered'
                            ? 'bg-green-500/20 text-green-400'
                            : log.status === 'sent'
                              ? 'bg-blue-500/20 text-blue-400'
                              : log.status === 'failed'
                                ? 'bg-red-500/20 text-red-400'
                                : 'bg-yellow-500/20 text-yellow-400'
                        }`}
                      >
                        {log.status?.toUpperCase()}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-xs text-muted-foreground whitespace-nowrap">
                      {new Date(log.created_at).toLocaleString()}
                    </td>
                    <td
                      className="px-4 py-3 text-red-400 text-xs max-w-[160px] truncate"
                      title={log.error_log}
                    >
                      {log.error_log || '—'}
                    </td>
                  </tr>
                ))}
                {logs.length === 0 && !loading && (
                  <tr>
                    <td colSpan={5} className="px-4 py-8 text-center text-muted-foreground">
                      No messages sent yet.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </Card>
    </div>
  );
};

import { useState } from 'react';
import { Card, Button, Input } from '@byteevolvr/ui';
import { Server } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiClient } from '@byteevolvr/api-client';

export function WhatsAppProviderSettings() {
  const queryClient = useQueryClient();

  const { data: configs, isLoading } = useQuery({
    queryKey: ['provider_configs'],
    queryFn: async () => {
      const res = await apiClient.get('/whatsapp/providers');
      return res.data;
    },
    // If endpoint doesn't exist yet, we'll gracefully mock it for UI rendering until backend is wired up
    retry: false,
    initialData: [
      {
        id: '1',
        provider_name: 'meta',
        is_enabled: true,
        priority: 1,
        config: { accessToken: '', phoneNumberId: '' },
      },
      {
        id: '2',
        provider_name: 'evolution',
        is_enabled: false,
        priority: 2,
        config: { baseUrl: '', apiKey: '', instanceName: '' },
      },
    ],
  });

  const updateConfig = useMutation({
    mutationFn: async (payload: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
      return apiClient.post('/whatsapp/providers', payload);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['provider_configs'] }); // eslint-disable-line @typescript-eslint/no-floating-promises
      alert('Provider settings updated successfully.');
    },
    onError: (error: any) => // eslint-disable-line @typescript-eslint/no-explicit-any
      alert(
        `Failed to update provider settings: ${error?.customMessage || error?.message || 'Unknown error'}`
      ),
  });

  if (isLoading) return <div>Loading provider configuration...</div>;

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-display-sm font-semibold flex items-center gap-2">
          <Server className="h-5 w-5 text-primary" /> WhatsApp Multi-Provider Configuration
        </h2>
        <p className="text-body-sm text-on-surface-variant mt-1">
          Manage Evolution API and Meta Cloud API. The highest priority enabled provider is the
          default.
        </p>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {configs.map((provider: any) => ( // eslint-disable-line @typescript-eslint/no-explicit-any
          <ProviderCard
            key={provider.provider_name}
            provider={provider}
            onSave={(updatedConfig) => updateConfig.mutate({ ...provider, config: updatedConfig })}
            onToggle={(enabled) => updateConfig.mutate({ ...provider, is_enabled: enabled })}
          />
        ))}
      </div>
    </div>
  );
}

function ProviderCard({
  provider,
  onSave,
  onToggle,
}: {
  provider: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  onSave: (c: any) => void; // eslint-disable-line @typescript-eslint/no-explicit-any
  onToggle: (e: boolean) => void;
}) {
  const [localConfig, setLocalConfig] = useState(provider.config || {});

  return (
    <Card
      className="flex flex-col h-full border-t-4"
      style={{ borderTopColor: provider.is_enabled ? '#10b981' : '#64748b' }}
    >
      <div className="p-6 flex-1 flex flex-col space-y-4">
        <div className="flex justify-between items-start">
          <div>
            <h3 className="text-title-md font-semibold capitalize">
              {provider.provider_name} Provider
            </h3>
            <div className="flex items-center gap-2 mt-1">
              <span
                className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${provider.is_enabled ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}
              >
                {provider.is_enabled ? 'Active' : 'Disabled'}
              </span>
              <span className="text-xs text-on-surface-variant">Priority: {provider.priority}</span>
            </div>
          </div>
          <Button
            variant={provider.is_enabled ? 'outline' : 'primary'}
            size="sm"
            onClick={() => onToggle(!provider.is_enabled)}
          >
            {provider.is_enabled ? 'Disable' : 'Enable'}
          </Button>
        </div>

        <hr className="border-outline" />

        <div className="space-y-4 flex-1">
          {provider.provider_name === 'meta' && (
            <>
              <Input
                label="Access Token"
                type="password"
                value={localConfig.accessToken || ''}
                onChange={(e) => setLocalConfig({ ...localConfig, accessToken: e.target.value })}
              />
              <Input
                label="Phone Number ID"
                value={localConfig.phoneNumberId || ''}
                onChange={(e) => setLocalConfig({ ...localConfig, phoneNumberId: e.target.value })}
              />
            </>
          )}

          {provider.provider_name === 'evolution' && (
            <>
              <Input
                label="Base URL (VPS Endpoint)"
                placeholder="https://wa.byteevolvr.com"
                value={localConfig.baseUrl || ''}
                onChange={(e) => setLocalConfig({ ...localConfig, baseUrl: e.target.value })}
              />
              <Input
                label="Global API Key"
                type="password"
                value={localConfig.apiKey || ''}
                onChange={(e) => setLocalConfig({ ...localConfig, apiKey: e.target.value })}
              />
              <Input
                label="Instance Name"
                placeholder="byteevolvr"
                value={localConfig.instanceName || ''}
                onChange={(e) => setLocalConfig({ ...localConfig, instanceName: e.target.value })}
              />
            </>
          )}
        </div>

        <Button className="w-full mt-4" onClick={() => onSave(localConfig)}>
          Save Credentials
        </Button>
      </div>
    </Card>
  );
}

import { useEffect, useState } from 'react';
import { Play, Pause, RefreshCw, Trash2, AlertCircle, ListTodo, History } from 'lucide-react';
import { apiClient } from '@byteevolvr/api-client';
import { toast } from 'sonner';

export function WhatsAppTasks() { // eslint-disable-line complexity
  const [activeTab, setActiveTab] = useState<'queue' | 'history'>('queue');
  const [tasks, setTasks] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [historyLogs, setHistoryLogs] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [isPaused, setIsPaused] = useState(false);
  const [page, setPage] = useState(1);
  const [totalLogs, setTotalLogs] = useState(0);
  const limit = 50;

  const fetchData = async () => {
    try {
      if (activeTab === 'queue') {
        const res = await apiClient.get('/whatsapp/tasks');
        // interceptor unwraps {success, data} → res.data is the array
        setTasks(Array.isArray(res.data) ? res.data : []);
      } else {
        const res = await apiClient.get(`/whatsapp/logs?limit=${limit}&page=${page}`);
        // getLogs returns {success, data:[...], count, page, limit}
        // after interceptor unwrap: res.data = {data:[...], count, page, limit}
        // BUT if interceptor sees {success:true, data:X} it returns X directly
        // So res.data could be the array directly OR the full object
        const payload = res.data;
        if (Array.isArray(payload)) {
          setHistoryLogs(payload);
          setTotalLogs(payload.length);
        } else {
          setHistoryLogs(payload?.data || []);
          setTotalLogs(payload?.count || 0);
        }
      }
    } catch (error) {
      console.error('Failed to load data', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    setLoading(true); // eslint-disable-line react-hooks/set-state-in-effect
    fetchData(); // eslint-disable-line @typescript-eslint/no-floating-promises
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, [activeTab, page]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggleQueue = async () => {
    try {
      const endpoint = isPaused ? '/whatsapp/queue/resume' : '/whatsapp/queue/pause';
      const res = await apiClient.post(endpoint);
      if (res.data) {
        setIsPaused(!isPaused);
        toast.success(`Queue ${isPaused ? 'resumed' : 'paused'} successfully`);
      }
    } catch {
      toast.error('Failed to toggle queue state');
    }
  };

  const retryTask = async (id: string) => {
    try {
      const res = await apiClient.post(`/whatsapp/tasks/${id}/retry`);
      if (res.data) {
        toast.success('Task queued for retry');
        fetchData(); // eslint-disable-line @typescript-eslint/no-floating-promises
      }
    } catch {
      toast.error('Failed to retry task');
    }
  };

  const bulkRetryFailed = async () => {
    try {
      const res = await apiClient.post('/whatsapp/tasks/retry-failed');
      if (res.data) {
        toast.success(res.data.message || 'Bulk retry initiated');
        fetchData(); // eslint-disable-line @typescript-eslint/no-floating-promises
      }
    } catch {
      toast.error('Failed to bulk retry tasks');
    }
  };

  const cancelTask = async (id: string) => {
    try {
      const res = await apiClient.delete(`/whatsapp/tasks/${id}`);
      if (res.data) {
        toast.success('Task cancelled');
        fetchData(); // eslint-disable-line @typescript-eslint/no-floating-promises
      }
    } catch {
      toast.error('Failed to cancel task');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-on-surface">Task Queue Manager</h2>
          <p className="text-sm text-on-surface-variant">
            Monitor and manage outbound WhatsApp messages
          </p>
        </div>
        <div className="flex items-center gap-2">
          {activeTab === 'queue' && tasks.some((t) => t.state === 'failed') && (
            <button
              onClick={bulkRetryFailed}
              className="px-4 py-2 rounded-lg flex items-center gap-2 font-medium bg-surface-container-high hover:bg-surface-container-highest text-on-surface transition-colors"
            >
              <RefreshCw className="w-4 h-4" /> Bulk Retry Failed
            </button>
          )}
          <button
            onClick={toggleQueue}
            className={`px-4 py-2 rounded-lg flex items-center gap-2 font-medium ${
              isPaused ? 'bg-primary text-on-primary' : 'bg-error text-on-error'
            }`}
          >
            {isPaused ? <Play className="w-4 h-4" /> : <Pause className="w-4 h-4" />}
            {isPaused ? 'Resume All Sending' : 'Pause All Sending'}
          </button>
        </div>
      </div>

      <div className="flex gap-4 border-b border-outline-variant pb-2">
        <button
          onClick={() => setActiveTab('queue')}
          className={`flex items-center gap-2 px-4 py-2 text-sm font-medium transition-colors ${
            activeTab === 'queue'
              ? 'text-primary border-b-2 border-primary'
              : 'text-on-surface-variant hover:text-on-surface'
          }`}
        >
          <ListTodo className="w-4 h-4" /> Active Queue (BullMQ)
        </button>
        <button
          onClick={() => setActiveTab('history')}
          className={`flex items-center gap-2 px-4 py-2 text-sm font-medium transition-colors ${
            activeTab === 'history'
              ? 'text-primary border-b-2 border-primary'
              : 'text-on-surface-variant hover:text-on-surface'
          }`}
        >
          <History className="w-4 h-4" /> Task History (DB Logs)
        </button>
      </div>

      <div className="bg-surface rounded-xl border border-outline-variant overflow-hidden">
        {loading && tasks.length === 0 && historyLogs.length === 0 ? (
          <div className="p-8 text-center text-on-surface-variant">Loading data...</div>
        ) : activeTab === 'queue' ? (
          <table className="min-w-full divide-y divide-outline-variant">
            <thead className="bg-surface-container">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                  Job ID
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                  Recipient
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                  Status
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                  Attempts
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-outline-variant bg-surface">
              {tasks.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-on-surface-variant">
                    No tasks currently in the queue
                  </td>
                </tr>
              ) : (
                tasks.map((task) => (
                  <tr key={task.id}>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-on-surface">
                      #{task.id}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-on-surface-variant">
                      {task.data?.to || task.data?.payload?.to || 'Unknown'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                          task.state === 'completed'
                            ? 'bg-green-100 text-green-800'
                            : task.state === 'failed'
                              ? 'bg-red-100 text-red-800'
                              : task.state === 'active'
                                ? 'bg-blue-100 text-blue-800'
                                : 'bg-gray-100 text-gray-800'
                        }`}
                      >
                        {task.state}
                      </span>
                      {task.failedReason && (
                        <div
                          className="mt-1 flex items-center text-xs text-error max-w-xs truncate"
                          title={task.failedReason}
                        >
                          <AlertCircle className="w-3 h-3 mr-1" />
                          {task.failedReason}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-on-surface-variant">
                      {task.attemptsMade}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {(task.state === 'failed' || task.state === 'waiting') && (
                        <>
                          <button
                            onClick={() => retryTask(task.id)}
                            className="text-primary hover:text-primary-dark mr-4"
                          >
                            <RefreshCw className="w-4 h-4 inline" /> Retry
                          </button>
                          <button
                            onClick={() => cancelTask(task.id)}
                            className="text-error hover:text-error-dark"
                          >
                            <Trash2 className="w-4 h-4 inline" /> Cancel
                          </button>
                        </>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        ) : (
          <>
            <table className="min-w-full divide-y divide-outline-variant">
              <thead className="bg-surface-container">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                    Time
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                    Recipient
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                    Status
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-on-surface-variant uppercase tracking-wider">
                    Error Details
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-outline-variant bg-surface">
                {historyLogs.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="px-6 py-8 text-center text-on-surface-variant">
                      No historical tasks found
                    </td>
                  </tr>
                ) : (
                  historyLogs.map((log) => (
                    <tr key={log.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-on-surface-variant">
                        {new Date(log.created_at).toLocaleString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-on-surface-variant">
                        {log.recipient}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            log.status === 'sent' || log.status === 'delivered'
                              ? 'bg-green-100 text-green-800'
                              : log.status === 'failed'
                                ? 'bg-red-100 text-red-800'
                                : 'bg-yellow-100 text-yellow-800'
                          }`}
                        >
                          {(log.status || 'unknown').toUpperCase()}
                        </span>
                      </td>
                      <td
                        className="px-6 py-4 text-sm text-on-surface-variant max-w-xs truncate"
                        title={log.error_log}
                      >
                        {log.error_log || '-'}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
            {activeTab === 'history' && totalLogs > 0 && (
              <div className="flex items-center justify-between px-6 py-3 border-t border-outline-variant bg-surface-container">
                <span className="text-sm text-on-surface-variant">
                  Showing {(page - 1) * limit + 1} to {Math.min(page * limit, totalLogs)} of{' '}
                  {totalLogs}
                </span>
                <div className="flex gap-2">
                  <button
                    disabled={page === 1}
                    onClick={() => setPage(page - 1)}
                    className="px-3 py-1 text-sm border border-outline-variant rounded hover:bg-surface-container-high disabled:opacity-50"
                  >
                    Previous
                  </button>
                  <button
                    disabled={page * limit >= totalLogs}
                    onClick={() => setPage(page + 1)}
                    className="px-3 py-1 text-sm border border-outline-variant rounded hover:bg-surface-container-high disabled:opacity-50"
                  >
                    Next
                  </button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Plus, Edit2, Trash2, Save } from 'lucide-react';
import { toast } from 'sonner';
import { apiClient } from '@byteevolvr/api-client';

export function WhatsAppTemplates() {
  const [templates, setTemplates] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState({ name: '', content: '', variables: '' });

  const AVAILABLE_VARIABLES = [
    { key: 'customerName', label: 'Customer Name' },
    { key: 'orderId', label: 'Order ID' },
    { key: 'trackingUrl', label: 'Tracking URL' },
    { key: 'amount', label: 'Order Amount' },
    { key: 'status', label: 'Order Status' },
    { key: 'storeName', label: 'Store Name' },
  ];

  const insertVariable = (key: string) => {
    const newContent = editForm.content + ` {{${key}}}`;
    const currentVars = editForm.variables
      .split(',')
      .map((v) => v.trim())
      .filter(Boolean);
    if (!currentVars.includes(key)) {
      currentVars.push(key);
    }

    setEditForm({
      ...editForm,
      content: newContent,
      variables: currentVars.join(', '),
    });
  };

  const fetchTemplates = async () => {
    try {
      setLoading(true);
      const res = await apiClient.get('/whatsapp/templates');
      if (res.data) {
        setTemplates(res.data || []);
      }
    } catch (error) { // eslint-disable-line @typescript-eslint/no-unused-vars
      toast.error('Failed to load templates');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTemplates(); // eslint-disable-line react-hooks/set-state-in-effect // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  const saveTemplate = async () => {
    try {
      if (!editForm.name.trim() || !editForm.content.trim()) {
        toast.error('Template name and content are required');
        return;
      }

      const payload = {
        name: editForm.name,
        content: editForm.content,
        variables: editForm.variables
          .split(',')
          .map((v) => v.trim())
          .filter(Boolean),
      };

      if (editingId === 'new') {
        const res = await apiClient.post('/whatsapp/templates', payload);
        if (res.data) {
          toast.success('Template saved');
          setEditingId(null);
          fetchTemplates(); // eslint-disable-line @typescript-eslint/no-floating-promises
        }
      } else {
        const res = await apiClient.put(`/whatsapp/templates/${editingId}`, payload);
        if (res.data) {
          toast.success('Template saved');
          setEditingId(null);
          fetchTemplates(); // eslint-disable-line @typescript-eslint/no-floating-promises
        }
      }
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      const errorMsg = err?.response?.data?.message || err?.message || 'Failed to save template';
      toast.error(`Error: ${errorMsg}`);
    }
  };

  const deleteTemplate = async (id: string) => {
    if (!confirm('Are you sure you want to delete this template?')) return;
    try {
      await apiClient.delete(`/whatsapp/templates/${id}`);
      toast.success('Template deleted');
      fetchTemplates(); // eslint-disable-line @typescript-eslint/no-floating-promises
    } catch {
      toast.error('Failed to delete template');
    }
  };

  if (loading && templates.length === 0) return <div>Loading templates...</div>;

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-on-surface">Message Templates</h2>
          <p className="text-sm text-on-surface-variant">Manage automated reply structures</p>
        </div>
        <button
          onClick={() => {
            setEditingId('new');
            setEditForm({ name: '', content: '', variables: '' });
          }}
          className="px-4 py-2 bg-primary text-on-primary rounded-lg flex items-center gap-2 font-medium"
        >
          <Plus className="w-4 h-4" /> New Template
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {editingId === 'new' && (
          <div className="bg-surface p-6 rounded-xl border border-primary shadow-sm space-y-4">
            <h3 className="font-semibold text-lg">Create New Template</h3>
            <div>
              <label className="block text-sm font-medium mb-1">
                Template Name (e.g. ORDER_CREATED)
              </label>
              <input
                value={editForm.name}
                onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                className="w-full p-2 border rounded-lg"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1 flex justify-between items-center">
                Message Content
                <span className="text-xs text-on-surface-variant font-normal">
                  Click a variable below to insert
                </span>
              </label>
              <div className="flex flex-wrap gap-2 mb-2">
                {AVAILABLE_VARIABLES.map((v) => (
                  <button
                    key={v.key}
                    onClick={() => insertVariable(v.key)}
                    className="px-2 py-1 bg-surface-container-high hover:bg-primary/20 text-xs rounded border border-outline-variant transition-colors"
                  >
                    + {v.label}
                  </button>
                ))}
              </div>
              <textarea
                rows={4}
                value={editForm.content}
                onChange={(e) => setEditForm({ ...editForm, content: e.target.value })}
                className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-primary outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">
                Detected Variables (comma separated)
              </label>
              <input
                value={editForm.variables}
                onChange={(e) => setEditForm({ ...editForm, variables: e.target.value })}
                placeholder="orderId, customerName"
                className="w-full p-2 border rounded-lg bg-surface-container-low"
              />
            </div>
            <div className="flex justify-end gap-2">
              <button onClick={() => setEditingId(null)} className="px-4 py-2 border rounded-lg">
                Cancel
              </button>
              <button
                onClick={saveTemplate}
                className="px-4 py-2 bg-primary text-on-primary rounded-lg flex items-center"
              >
                <Save className="w-4 h-4 mr-2" /> Save
              </button>
            </div>
          </div>
        )}

        {templates.map((t) =>
          editingId === t.id ? (
            <div
              key={t.id}
              className="bg-surface p-6 rounded-xl border border-primary shadow-sm space-y-4"
            >
              <h3 className="font-semibold text-lg">Edit Template</h3>
              <div>
                <label className="block text-sm font-medium mb-1">Template Name</label>
                <input
                  value={editForm.name}
                  onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                  className="w-full p-2 border rounded-lg"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1 flex justify-between items-center">
                  Message Content
                  <span className="text-xs text-on-surface-variant font-normal">
                    Click a variable below to insert
                  </span>
                </label>
                <div className="flex flex-wrap gap-2 mb-2">
                  {AVAILABLE_VARIABLES.map((v) => (
                    <button
                      key={v.key}
                      onClick={() => insertVariable(v.key)}
                      className="px-2 py-1 bg-surface-container-high hover:bg-primary/20 text-xs rounded border border-outline-variant transition-colors"
                    >
                      + {v.label}
                    </button>
                  ))}
                </div>
                <textarea
                  rows={4}
                  value={editForm.content}
                  onChange={(e) => setEditForm({ ...editForm, content: e.target.value })}
                  className="w-full p-2 border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">
                  Detected Variables (comma separated)
                </label>
                <input
                  value={editForm.variables}
                  onChange={(e) => setEditForm({ ...editForm, variables: e.target.value })}
                  className="w-full p-2 border rounded-lg bg-surface-container-low"
                />
              </div>
              <div className="flex justify-end gap-2">
                <button onClick={() => setEditingId(null)} className="px-4 py-2 border rounded-lg">
                  Cancel
                </button>
                <button
                  onClick={saveTemplate}
                  className="px-4 py-2 bg-primary text-on-primary rounded-lg flex items-center"
                >
                  <Save className="w-4 h-4 mr-2" /> Save
                </button>
              </div>
            </div>
          ) : (
            <div
              key={t.id}
              className="bg-surface p-6 rounded-xl border border-outline-variant shadow-sm space-y-3 relative group"
            >
              <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button
                  onClick={() => {
                    setEditingId(t.id);
                    setEditForm({
                      name: t.name,
                      content: t.content,
                      variables: (t.variables || []).join(', '),
                    });
                  }}
                  className="p-1.5 text-on-surface-variant hover:text-primary bg-surface-container rounded-md"
                >
                  <Edit2 className="w-4 h-4" />
                </button>
                <button
                  onClick={() => deleteTemplate(t.id)}
                  className="p-1.5 text-on-surface-variant hover:text-error bg-surface-container rounded-md"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
              <h3 className="font-bold text-on-surface text-lg">{t.name}</h3>
              <div className="bg-surface-container-low p-3 rounded-lg text-sm font-mono text-on-surface-variant whitespace-pre-wrap">
                {t.content}
              </div>
              <div className="flex gap-2 flex-wrap">
                {(t.variables || []).map((v: string) => (
                  <span
                    key={v}
                    className="px-2 py-1 bg-secondary-container text-on-secondary-container text-xs rounded-full font-medium"
                  >
                    {`{{${v}}}`}
                  </span>
                ))}
              </div>
            </div>
          )
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, Button, Input } from '@byteevolvr/ui';
import {
  Search,
  Filter,
  ShieldAlert,
  UserPlus,
  Settings,
  Package,
  ShoppingCart,
} from 'lucide-react';
import { AdminService } from '@byteevolvr/api-client';
import { formatDistanceToNow } from 'date-fns';

import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from '../components/ui/Table';

export function ActivityLogPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [logs, setLogs] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchLogs = async () => {
      try {
        setError(null);
        const data = await AdminService.getAuditLogs();
        setLogs(data || []);
      } catch (err) {
        console.error('Failed to fetch logs:', err);
        setError('Failed to load system activity logs. Please try again later.');
      } finally {
        setLoading(false);
      }
    };
    fetchLogs(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  const getLogIcon = (module: string) => {
    switch (module) {
      case 'auth':
        return ShieldAlert;
      case 'users':
        return UserPlus;
      case 'products':
        return Package;
      case 'orders':
        return ShoppingCart;
      default:
        return Settings;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-display-sm font-semibold text-on-background">System Activity Log</h1>
          <p className="text-body-sm text-on-surface-variant mt-1">
            Audit trail of all administrative actions and security events
          </p>
        </div>
        <Button variant="outline">Export CSV</Button>
      </div>

      <Card>
        <div className="flex items-center justify-between p-4 border-b border-outline-variant">
          <div className="flex items-center gap-2 max-w-sm w-full">
            <div className="relative w-full">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-on-surface-variant" />
              <Input
                placeholder="Search events, users, or IP addresses..."
                className="pl-9"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2">
            <select className="h-10 px-3 rounded-md border border-outline bg-surface text-sm text-on-surface focus:ring-2 focus:ring-primary focus:outline-none">
              <option>All Events</option>
              <option>Security Only</option>
              <option>User Actions</option>
            </select>
            <Button variant="outline" className="gap-2">
              <Filter className="h-4 w-4" /> Filters
            </Button>
          </div>
        </div>
        <div className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Event</TableHead>
                <TableHead>User / Source</TableHead>
                <TableHead>Details</TableHead>
                <TableHead className="text-right">Timestamp</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={4} className="text-center py-8 text-on-surface-variant">
                    Loading audit logs...
                  </TableCell>
                </TableRow>
              ) : error ? (
                <TableRow>
                  <TableCell colSpan={4} className="text-center py-8 text-error">
                    {error}
                  </TableCell>
                </TableRow>
              ) : logs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={4} className="text-center py-8 text-on-surface-variant">
                    No activity logs found.
                  </TableCell>
                </TableRow>
              ) : (
                logs.map((log) => {
                  const Icon = getLogIcon(log.module);
                  return (
                    <TableRow key={log.id}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <div
                            className={`h-8 w-8 rounded flex items-center justify-center shrink-0 ${
                              log.module === 'auth'
                                ? 'bg-error/10 text-error'
                                : log.module === 'system'
                                  ? 'bg-primary/10 text-primary'
                                  : 'bg-surface-container text-on-surface-variant'
                            }`}
                          >
                            <Icon className="h-4 w-4" />
                          </div>
                          <span className="font-medium text-on-surface">
                            {log.action.replace(/_/g, ' ')}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className="text-on-surface-variant">
                        {log.user_profiles?.full_name || 'System'}
                      </TableCell>
                      <TableCell className="text-sm text-on-surface-variant max-w-md truncate">
                        {log.notes ||
                          (log.new_data ? JSON.stringify(log.new_data) : 'No details available')}
                      </TableCell>
                      <TableCell className="text-right text-sm text-on-surface-variant">
                        {formatDistanceToNow(new Date(log.created_at), { addSuffix: true })}
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </div>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, Button } from '@byteevolvr/ui';
import {
  Download,
  TrendingUp,
  Users,
  ShoppingCart,
  DollarSign,
  Loader2,
  RefreshCcw,
} from 'lucide-react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
} from 'recharts';
import { AdminService } from '@byteevolvr/api-client';

export function AnalyticsPage() {
  const [loading, setLoading] = useState(true);
  const [metrics, setMetrics] = useState({ revenue: 0, orders: 0, customers: 0, avgValue: 0 });
  const [salesData, setSalesData] = useState<{ name: string; revenue: number }[]>([]);
  const [topProducts, setTopProducts] = useState<{ name: string; sales: number }[]>([]);

  useEffect(() => {
    fetchAnalytics(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  async function fetchAnalytics() {
    setLoading(true);
    try {
      // 1. Fetch data from AdminService
      const stats = await AdminService.getDashboardStats();
      const orders = await AdminService.getOrders();
      await AdminService.getCustomers();

      // 3. Process Metrics
      setMetrics({
        revenue: stats.totalRevenue || 0,
        orders: stats.salesCount || 0,
        customers: stats.customerCount || 0,
        avgValue: stats.avgOrderValue || 0,
      });

      // 4. Process Revenue Over Time (Daily)
      const last7Days: { name: string; revenue: number }[] = [];

      const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

      for (let i = 6; i >= 0; i--) {
        const d = new Date();
        d.setDate(d.getDate() - i);
        const dayName = days[d.getDay()];
        const dateStr = d.toISOString().split('T')[0];

        const dayRevenue =
          orders
            ?.filter((o: any) => o.created_at.startsWith(dateStr)) // eslint-disable-line @typescript-eslint/no-explicit-any
            .reduce((sum: number, o: any) => sum + Number(o.total_amount), 0) || 0; // eslint-disable-line @typescript-eslint/no-explicit-any

        last7Days.push({ name: dayName, revenue: dayRevenue });
      }
      setSalesData(last7Days);

      // 5. Process Top Products (This would ideally come from a specialized backend route)
