                <Input
                  value={tempCustomer.phone}
                  onChange={(e) => setTempCustomer({ ...tempCustomer, phone: e.target.value })}
                  className="h-11 w-full"
                  placeholder="00000 00000"
                />
              </div>
              <div className="pt-4 flex gap-3">
                <Button
                  variant="ghost"
                  onClick={() => setShowCustomerModal(false)}
                  className="flex-1 rounded-xl font-bold h-12"
                >
                  Cancel
                </Button>
                <Button onClick={saveCustomer} className="flex-1 rounded-xl font-bold h-12">
                  Save Details
                </Button>
              </div>
            </div>
          </Card>
        </div>
      )}
    </>
  );
}

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Card, Button } from '@byteevolvr/ui';
import {
  ArrowLeft,
  Save,
  Image as ImageIcon,
  UploadCloud,
  X,
  Plus,
  Loader2,
  CheckCircle2,
} from 'lucide-react';
import { ProductService } from '@byteevolvr/api-client';

export function ProductFormPage() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    original_price: '',
    sku: '',
    stock_quantity: '0',
    category: 'Electronics',
    brand: '',
    status: 'active' as 'active' | 'draft' | 'out_of_stock',
    image_url: '',
    images: [] as string[],
    variants: [] as any[], // eslint-disable-line @typescript-eslint/no-explicit-any
    slug: '',
    tags: '',
  });

  useEffect(() => {
    if (id) {
      const fetchProduct = async () => { // eslint-disable-line complexity
        setLoading(true);
        try {
          const product = await ProductService.getProduct(id);
          setFormData({
            name: product.name || '',
            description: product.description || '',
            price: product.price?.toString() || '',
            original_price: product.original_price?.toString() || '',
            sku: product.sku || '',
            stock_quantity: product.stock_quantity?.toString() || '0',
            category: product.category || 'Electronics',
            brand: product.brand || '',
            status: product.status || 'active',
            image_url: product.image_url || '',
            images: (product as any).images || [], // eslint-disable-line @typescript-eslint/no-explicit-any
            variants: (product as any).variants || [], // eslint-disable-line @typescript-eslint/no-explicit-any
            slug: (product as any).slug || '', // eslint-disable-line @typescript-eslint/no-explicit-any
            tags: (product as any).tags?.join(', ') || '', // eslint-disable-line @typescript-eslint/no-explicit-any
          });
        } catch (err: any) { // eslint-disable-line @typescript-eslint/no-unused-vars // eslint-disable-line @typescript-eslint/no-explicit-any
          setError('Failed to load product details.');
        } finally {
          setLoading(false);
        }
      };
      fetchProduct(); // eslint-disable-line @typescript-eslint/no-floating-promises
    }
  }, [id]);

  const handleImageUpload = async (
    e: React.ChangeEvent<HTMLInputElement>,
    isPrimary: boolean,
    index?: number
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploading(true);
    try {
      const url = await ProductService.uploadImage(file);
      if (isPrimary) {
        setFormData({ ...formData, image_url: url });
      } else if (index !== undefined) {
        const newImages = [...formData.images];
        newImages[index] = url;
        setFormData({ ...formData, images: newImages });
      }
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-unused-vars // eslint-disable-line @typescript-eslint/no-explicit-any
      setError('Failed to upload image. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const handleSave = async () => {
    if (!formData.name || !formData.price) {
      setError('Product Name and Price are required.');
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const payload = {
        ...formData,
        price: parseFloat(formData.price),
        original_price: formData.original_price ? parseFloat(formData.original_price) : undefined,
        stock_quantity: parseInt(formData.stock_quantity),
        slug: formData.slug || undefined,
        tags: formData.tags
          ? formData.tags
              .split(',')
              .map((t) => t.trim())
              .filter(Boolean)
          : [],
      };

      if (id) {
        await ProductService.updateProduct(id, payload as any); // eslint-disable-line @typescript-eslint/no-explicit-any
      } else {
        await ProductService.createProduct(payload as any); // eslint-disable-line @typescript-eslint/no-explicit-any
      }

      setSuccess(true);
      setTimeout(() => navigate('/products'), 1500);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'An error occurred while saving the product.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-20">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" className="px-2" onClick={() => navigate('/products')}>
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </Button>
          <h1 className="text-display-sm font-semibold text-on-background">
            {id ? 'Edit Product' : 'Add New Product'}
          </h1>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={() => navigate('/products')}>
            Discard
          </Button>
          <Button className="gap-2 min-w-[140px]" onClick={handleSave} disabled={loading}>
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
            {success ? 'Saved!' : id ? 'Update Product' : 'Save Product'}
          </Button>
        </div>
      </div>

      {error && (
        <div className="p-4 bg-error/10 border border-error text-error rounded-lg text-sm font-medium">
          {error}
        </div>
      )}

      {success && (
        <div className="p-4 bg-success/10 border border-success text-success rounded-lg text-sm font-medium flex items-center gap-2">
          <CheckCircle2 className="h-5 w-5" />
          Product successfully {id ? 'updated' : 'created'}! Redirecting...
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Content Area */}
        <div className="lg:col-span-2 space-y-6">
          <Card>
            <div className="p-4 border-b border-outline-variant">
