export function ReportsPage() {
  const handleExport = async (type: string, format: string) => {
    try {
      const token = localStorage.getItem('admin_token');
      const response = await fetch(
        `http://localhost:8080/api/reports/export?type=${type}&format=${format}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `report_${type}_${Date.now()}.${format === 'excel' ? 'xlsx' : 'csv'}`; // eslint-disable-line react-hooks/purity
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
      } else {
        alert('Failed to export report');
      }
    } catch (error) { // eslint-disable-line @typescript-eslint/no-unused-vars
      alert('Error connecting to server');
    }
  };

  return (
    <main style={{ padding: 48 }}>
      <h1>Reports</h1>
      <p style={{ color: '#8B9BB8' }}>
        Daily/monthly sales summaries and CSV or Excel export workflows.
      </p>
      <section
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
          gap: 16,
          marginTop: 24,
        }}
      >
        {[
          {
            title: 'Daily Sales',
            description: 'Export day-wise revenue, order count, and returns.',
          },
          {
            title: 'Monthly Sales',
            description: 'Export monthly GMV, AOV, top categories, and repeat rate.',
          },
          {
            title: 'Shipment Report',
            description: 'Export AWB, courier, tracking status, and SLA exceptions.',
          },
        ].map((report) => (
          <article
            key={report.title}
            style={{
              padding: 24,
              borderRadius: 20,
              border: '1px solid rgba(255,255,255,0.08)',
              background: 'rgba(255,255,255,0.03)',
            }}
          >
            <h2>{report.title}</h2>
            <p style={{ color: '#8B9BB8', lineHeight: 1.6 }}>{report.description}</p>
            <div style={{ display: 'flex', gap: 10, marginTop: 14 }}>
              <button
                onClick={() => handleExport(report.title.toLowerCase().replace(' ', '_'), 'csv')}
                style={{
                  flex: 1,
                  padding: '10px 14px',
                  borderRadius: 12,
                  border: '1px solid rgba(255,255,255,0.1)',
                  color: '#fff',
                  background: 'rgba(255,255,255,0.05)',
                  cursor: 'pointer',
                }}
              >
                CSV
              </button>
              <button
                onClick={() => handleExport(report.title.toLowerCase().replace(' ', '_'), 'excel')}
                style={{
                  flex: 1,
                  padding: '10px 14px',
                  borderRadius: 12,
                  border: 0,
                  color: '#fff',
                  background: 'linear-gradient(135deg, #1A4FD6, #3B7BF8)',
                  cursor: 'pointer',
                }}
              >
                Excel
              </button>
            </div>
          </article>
        ))}
      </section>
    </main>
  );
}

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Input } from '@byteevolvr/ui';
import {
  Search,
  Filter,
  RefreshCcw,
  Check,
  X,
  AlertCircle,
  Loader2,
  ExternalLink,
} from 'lucide-react';
import { AdminService } from '@byteevolvr/api-client';
import { useNavigate } from 'react-router-dom';

import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from '../components/ui/Table';

export function ReturnsPage() {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [returns, setReturns] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);

  useEffect(() => {
    fetchReturns(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  async function fetchReturns() {
    setLoading(true);
    try {
      const data = await AdminService.getRmaReturns();
      // data from backend ReturnService returns: *, user_profiles(full_name), orders(order_number)
      const mappedData = data?.map((r: any) => ({ // eslint-disable-line @typescript-eslint/no-explicit-any
        ...r,
        user: r.user_profiles,
        order: r.orders,
      }));
      setReturns(mappedData || []);
    } catch (err) {
      console.error('Error fetching returns:', err);
    } finally {
      setLoading(false);
    }
  }

  const updateReturnStatus = async (id: string, newStatus: string) => {
    setProcessingId(id);
    try {
      await AdminService.updateRmaStatus(id, { status: newStatus });
      await fetchReturns();
    } catch (err) {
      console.error('Error updating return status:', err);
      alert('Failed to update status');
    } finally {
      setProcessingId(null);
    }
  };

  const filteredReturns = returns.filter(
    (r) =>
      r.rma_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (r.order?.order_number &&
        r.order.order_number.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (r.user?.full_name && r.user.full_name.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const stats = {
    pending: returns.filter((r) => r.status === 'pending').length,
    approved: returns.filter((r) => r.status === 'approved').length,
    rejected: returns.filter((r) => r.status === 'rejected').length,
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-display-sm font-semibold text-on-background">Returns & Refunds</h1>
          <p className="text-body-sm text-on-surface-variant mt-1">
            Manage RMAs and process customer refunds
          </p>
        </div>
        <Button className="gap-2" onClick={fetchReturns}>
          <RefreshCcw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} /> Refresh
        </Button>
      </div>

      <div className="flex gap-6 overflow-x-auto pb-2">
        <Card className="min-w-[250px] flex-1 border-primary/20 bg-primary/5">
          <div className="p-4 flex items-center justify-between">
            <div>
              <div className="text-primary font-medium text-sm mb-1">Pending Approval</div>
              <div className="text-3xl font-bold text-primary">{stats.pending}</div>
            </div>
            <AlertCircle className="h-8 w-8 text-primary opacity-50" />
          </div>
        </Card>
        <Card className="min-w-[250px] flex-1">
          <div className="p-4 flex items-center justify-between">
            <div>
              <div className="text-on-surface-variant font-medium text-sm mb-1">Approved</div>
              <div className="text-3xl font-bold text-on-surface">{stats.approved}</div>
            </div>
            <Check className="h-8 w-8 text-success opacity-50" />
          </div>
        </Card>
        <Card className="min-w-[250px] flex-1">
          <div className="p-4 flex items-center justify-between">
            <div>
              <div className="text-on-surface-variant font-medium text-sm mb-1">Rejected</div>
              <div className="text-3xl font-bold text-on-surface">{stats.rejected}</div>
            </div>
            <X className="h-8 w-8 text-error opacity-50" />
          </div>
        </Card>
      </div>

      <Card>
        <div className="flex items-center justify-between p-4 border-b border-outline-variant">
          <div className="flex items-center gap-2 max-w-sm w-full">
            <div className="relative w-full">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-on-surface-variant" />
              <Input
                placeholder="Search RMAs, orders or customers..."
                className="pl-9"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" className="gap-2">
              <Filter className="h-4 w-4" /> Filters
            </Button>
          </div>
        </div>
        <div className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>RMA Number</TableHead>
                <TableHead>Order</TableHead>
                <TableHead>Customer</TableHead>
                <TableHead>Reason</TableHead>
                <TableHead>Date</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={7} className="text-center py-12">
                    <Loader2 className="h-6 w-6 animate-spin mx-auto text-primary" />
                    <span className="text-sm text-on-surface-variant mt-2 block">
                      Loading returns...
                    </span>
                  </TableCell>
                </TableRow>
              ) : filteredReturns.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} className="text-center py-12 text-on-surface-variant">
                    No returns found.
                  </TableCell>
                </TableRow>
              ) : (
                filteredReturns.map((rma) => (
                  <TableRow key={rma.id}>
                    <TableCell className="font-medium text-on-surface">{rma.rma_number}</TableCell>
                    <TableCell
                      className="text-primary hover:underline cursor-pointer flex items-center gap-1"
                      onClick={() => navigate(`/orders/${rma.order_id}`)}
                    >
                      {rma.order?.order_number} <ExternalLink className="h-3 w-3" />
                    </TableCell>
                    <TableCell className="text-on-surface-variant">
                      {rma.user?.full_name || 'Walk-in Customer'}
                    </TableCell>
                    <TableCell>
                      <div className="text-sm text-on-surface">{rma.reason}</div>
                      {rma.condition && (
                        <div className="text-xs text-on-surface-variant mt-0.5">
                          Condition: {rma.condition}
                        </div>
                      )}
                    </TableCell>
                    <TableCell className="text-on-surface-variant text-sm">
                      {new Date(rma.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant={
                          rma.status === 'approved' || rma.status === 'refunded'
                            ? 'success'
                            : rma.status === 'rejected'
                              ? 'error'
                              : 'warning'
                        }
                      >
                        {rma.status.charAt(0).toUpperCase() + rma.status.slice(1)}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        {rma.status === 'pending' ? (
                          <>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-8 w-8 p-0 text-success hover:bg-success/10"
                              onClick={() => updateReturnStatus(rma.id, 'approved')}
                              disabled={processingId === rma.id}
                            >
                              <Check className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-8 w-8 p-0 text-error hover:bg-error/10"
                              onClick={() => updateReturnStatus(rma.id, 'rejected')}
                              disabled={processingId === rma.id}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </>
                        ) : rma.status === 'approved' ? (
                          <Button
                            variant="outline"
                            size="sm"
                            className="text-xs h-8"
                            onClick={() => updateReturnStatus(rma.id, 'refunded')}
                            disabled={processingId === rma.id}
                          >
                            Process Refund
                          </Button>
                        ) : (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => navigate(`/orders/${rma.order_id}`)}
                          >
                            View Order
                          </Button>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Input } from '@byteevolvr/ui';
import { Star, MessageSquare, Check, X, Search, Filter, Loader2, RefreshCcw } from 'lucide-react';
import { useAdminStore } from '@byteevolvr/store';
import { ReviewService } from '@byteevolvr/api-client';

import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from '../components/ui/Table';

export function ReviewsPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [reviews, setReviews] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(false);
  const { setError } = useAdminStore();
  const [processingId, setProcessingId] = useState<string | null>(null);

  useEffect(() => {
    fetchReviews(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  async function fetchReviews() {
    setLoading(true);
    try {
      const data = await ReviewService.getAllReviews();
      setReviews(data || []);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      console.error('Error fetching reviews:', err);
      setError(err.customMessage || 'Failed to load reviews');
    } finally {
      setLoading(false);
    }
  }

  const updateReviewStatus = async (id: string, newStatus: string) => {
    setProcessingId(id);
    try {
      await ReviewService.updateReviewStatus(id, newStatus);
      await fetchReviews();
    } catch (err) {
      console.error('Error updating review status:', err);
      alert('Failed to update status');
    } finally {
      setProcessingId(null);
    }
  };

  const renderStars = (rating: number) => {
    return Array(5)
      .fill(0)
      .map((_, i) => (
        <Star
          key={i}
          className={`h-4 w-4 ${i < rating ? 'text-amber-400 fill-amber-400' : 'text-outline-variant'}`}
        />
      ));
  };

  const filteredReviews = reviews.filter(
    (r) =>
      (r.product?.name && r.product.name.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (r.comment && r.comment.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (r.user?.full_name && r.user.full_name.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const stats = {
    avg:
      reviews.length > 0
        ? (reviews.reduce((acc, r) => acc + r.rating, 0) / reviews.length).toFixed(1)
        : '0.0',
    total: reviews.length,
    pending: reviews.filter((r) => r.status === 'pending').length,
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-display-sm font-semibold text-on-background">Customer Reviews</h1>
          <p className="text-body-sm text-on-surface-variant mt-1">
            Moderate and respond to product reviews
          </p>
        </div>
        <Button variant="outline" onClick={fetchReviews} disabled={loading}>
          <RefreshCcw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card>
          <div className="p-6 flex items-center justify-between">
            <div>
              <div className="text-on-surface-variant font-medium text-sm mb-1">Average Rating</div>
              <div className="text-3xl font-bold text-on-surface flex items-center gap-2">
                {loading ? '...' : stats.avg}{' '}
                <Star className="h-6 w-6 text-amber-400 fill-amber-400" />
              </div>
            </div>
          </div>
        </Card>
        <Card>
          <div className="p-6 flex items-center justify-between">
            <div>
              <div className="text-on-surface-variant font-medium text-sm mb-1">Total Reviews</div>
              <div className="text-3xl font-bold text-on-surface">
                {loading ? '...' : stats.total}
              </div>
            </div>
          </div>
        </Card>
        <Card
          className={
            stats.pending > 0
              ? 'bg-warning-container border-warning-container text-on-warning-container'
              : ''
          }
        >
          <div className="p-6 flex items-center justify-between">
            <div>
              <div className="font-medium text-sm mb-1 opacity-90">Pending Moderation</div>
              <div className="text-3xl font-bold">{loading ? '...' : stats.pending}</div>
            </div>
            {stats.pending > 0 && (
              <Badge variant="warning" className="bg-warning text-on-warning">
                Action Needed
              </Badge>
            )}
          </div>
        </Card>
      </div>

      <Card>
        <div className="flex items-center justify-between p-4 border-b border-outline-variant">
          <div className="flex items-center gap-2 max-w-sm w-full">
            <div className="relative w-full">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-on-surface-variant" />
              <Input
                placeholder="Search reviews or products..."
                className="pl-9"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" className="gap-2">
              <Filter className="h-4 w-4" />
              Filters
            </Button>
          </div>
        </div>
        <div className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Customer</TableHead>
                <TableHead>Product</TableHead>
                <TableHead>Rating & Comment</TableHead>
                <TableHead>Date</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center py-12">
                    <Loader2 className="h-6 w-6 animate-spin mx-auto text-primary" />
                    <span className="text-sm text-on-surface-variant mt-2 block">
                      Loading reviews...
                    </span>
                  </TableCell>
                </TableRow>
              ) : filteredReviews.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center py-12 text-on-surface-variant">
                    No reviews found.
                  </TableCell>
                </TableRow>
              ) : (
                filteredReviews.map((review) => (
                  <TableRow key={review.id} className="items-start">
                    <TableCell className="align-top pt-4">
                      <div className="font-medium text-on-surface">
                        {review.user?.full_name || 'Anonymous'}
                      </div>
                    </TableCell>
                    <TableCell className="align-top pt-4">
                      <div className="text-primary hover:underline cursor-pointer font-medium text-sm">
                        {review.product?.name}
                      </div>
                    </TableCell>
                    <TableCell className="max-w-md py-4">
                      <div className="flex gap-1 mb-2">{renderStars(review.rating)}</div>
                      <p className="text-sm text-on-surface-variant leading-relaxed">
                        "{review.comment}"
                      </p>
                    </TableCell>
                    <TableCell className="align-top pt-4 text-on-surface-variant whitespace-nowrap text-sm">
                      {new Date(review.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="align-top pt-4">
                      <Badge
                        variant={
                          review.status === 'approved'
                            ? 'success'
                            : review.status === 'flagged'
                              ? 'error'
                              : 'warning'
                        }
                      >
                        {(review.status || 'pending').charAt(0).toUpperCase() +
                          (review.status || 'pending').slice(1)}
                      </Badge>
                    </TableCell>
                    <TableCell className="align-top pt-4 text-right">
                      <div className="flex justify-end gap-2">
                        {review.status === 'pending' && (
                          <>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-8 w-8 p-0 text-success bg-success/10 hover:bg-success/20"
                              onClick={() => updateReviewStatus(review.id, 'approved')}
                              disabled={processingId === review.id}
                            >
                              <Check className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-8 w-8 p-0 text-error bg-error/10 hover:bg-error/20"
                              onClick={() => updateReviewStatus(review.id, 'rejected')}
                              disabled={processingId === review.id}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </>
                        )}
                        <Button variant="outline" size="sm" className="h-8 gap-2">
                          <MessageSquare className="h-4 w-4" /> Reply
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      </Card>
    </div>
  );
}

