import { useState, useEffect } from 'react';
import { Card, Input, Button } from '@byteevolvr/ui';
import { CMSService } from '@byteevolvr/api-client';
import { useQueryClient } from '@tanstack/react-query';
import { Loader2, Save, CheckCircle2, XCircle, RefreshCw } from 'lucide-react';

type SaveStatus = { type: 'success' | 'error'; msg: string } | null;

export function SettingsPage() { // eslint-disable-line complexity
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [storeStatus, setStoreStatus] = useState<SaveStatus>(null);
  const [waStatus, setWaStatus] = useState<SaveStatus>(null);
  const [emailStatus, setEmailStatus] = useState<SaveStatus>(null);
  const [pushStatus, setPushStatus] = useState<SaveStatus>(null);
  const queryClient = useQueryClient();
  const [settings, setSettings] = useState({
    storeName: '',
    supportEmail: '',
    phone: '',
    address: '',
    currency: 'USD ($)',
    panNumber: '',
    gstNumber: '',
  });

  const [apiConfig, setApiConfig] = useState({
    publicKey: '',
    secretKey: '',
  });

  const [whatsappConfig, setWhatsappConfig] = useState({
    accessToken: '',
    phoneNumberId: '',
    businessAccountId: '',
    webhookVerifyToken: '',
  });

  const [emailConfig, setEmailConfig] = useState({
    activeProvider: 'resend', // 'resend' | 'brevo' | 'smtp'
    resendApiKey: '',
    brevoApiKey: '',
    smtpHost: '',
    smtpPort: '',
    smtpUser: '',
    smtpPass: '',
    smtpSecure: false,
    defaultFromAddress: 'noreply@byteevolvr.com',
  });

  const [pushConfig, setPushConfig] = useState({
    fcmServerKey: '',
  });

  useEffect(() => {
    fetchSettings(); // eslint-disable-line react-hooks/immutability // eslint-disable-line @typescript-eslint/no-floating-promises
    fetchApiConfig(); // eslint-disable-line react-hooks/immutability // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  const fetchApiConfig = async () => { // eslint-disable-line complexity
    try {
      const data = await CMSService.getContent('global');

      const api = data?.find((s: any) => s.section_key === 'api_config')?.content || {}; // eslint-disable-line @typescript-eslint/no-explicit-any
      setApiConfig({
        publicKey: api.publicKey || '',
        secretKey: api.secretKey || '',
      });

      const wa = data?.find((s: any) => s.section_key === 'whatsapp_config')?.content || {}; // eslint-disable-line @typescript-eslint/no-explicit-any
      setWhatsappConfig({
        accessToken: wa.accessToken || '',
        phoneNumberId: wa.phoneNumberId || '',
        businessAccountId: wa.businessAccountId || '',
        // IMPORTANT: Do NOT generate a random token here. Show blank if not saved.
