                        {supplier.name}
                      </TableCell>
                      <TableCell>
                        <div className="text-sm text-on-surface">{supplier.contact_name}</div>
                        <div className="text-xs text-on-surface-variant">{supplier.email}</div>
                      </TableCell>
                      <TableCell>
                        <Badge variant={supplier.status === 'active' ? 'success' : 'warning'}>
                          {supplier.status.charAt(0).toUpperCase() + supplier.status.slice(1)}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        {purchaseOrders.filter((po) => po.supplier_id === supplier.id).length}
                      </TableCell>
                      <TableCell className="text-on-surface-variant text-sm">
                        {purchaseOrders.filter((po) => po.supplier_id === supplier.id)[0]
                          ?.created_at
                          ? new Date(
                              purchaseOrders.filter((po) => po.supplier_id === supplier.id)[0]
                                ?.created_at
                            ).toLocaleDateString()
                          : 'N/A'}
                      </TableCell>
                      <TableCell className="flex justify-end gap-2">
                        <button
                          onClick={() => setSelectedSupplierForPO(supplier)}
                          title="Create Purchase Order"
                          className="text-primary hover:bg-primary/10 p-1.5 rounded-md transition-colors"
                        >
                          <FilePlus className="h-4 w-4" />
                        </button>
                        <button className="text-on-surface-variant hover:text-on-surface p-1.5 rounded-md hover:bg-surface-container transition-colors">
                          <ExternalLink className="h-4 w-4" />
                        </button>
                      </TableCell>
                    </TableRow>
                  ))
              )}
            </TableBody>
          </Table>
        </div>
      </Card>

      {/* Add Supplier Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm"
