import { Plus, Search, Filter, Trash2, Shield, Mail, X } from 'lucide-react';
import { TeamService } from '@byteevolvr/api-client';

import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from '../components/ui/Table';

const mockTeam = [
  {
    id: '1',
    name: 'Admin User',
    email: 'admin@byteevolvr.com',
    role: 'Super Admin',
    status: 'active',
    lastActive: 'Just now',
  },
  {
    id: '2',
    name: 'John Doe',
    email: 'john@byteevolvr.com',
    role: 'Store Manager',
    status: 'active',
    lastActive: '2 hours ago',
  },
  {
    id: '3',
    name: 'Jane Smith',
    email: 'jane@byteevolvr.com',
    role: 'Support Agent',
    status: 'active',
    lastActive: 'Yesterday',
  },
  {
    id: '4',
    name: 'Mike Ross',
    email: 'mike@byteevolvr.com',
    role: 'Support Agent',
    status: 'invited',
    lastActive: 'Never',
  },
];

export function TeamPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [team, setTeam] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const [inviteData, setInviteData] = useState({ email: '', full_name: '', role: 'manager' });
  const [inviting, setInviting] = useState(false);
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  const fetchTeam = async () => {
    setLoading(true);
    try {
      const data = await TeamService.getTeamMembers();
      if (data && data.length > 0) {
        const mapped = data.map((user: any) => ({ // eslint-disable-line @typescript-eslint/no-explicit-any
          id: user.id,
          name: user.full_name || user.email.split('@')[0],
          email: user.email,
          role: user.role,
          status: 'active',
          lastActive: new Date(user.updated_at).toLocaleDateString(),
        }));
        setTeam(mapped);
      } else {
        setTeam(mockTeam);
      }
    } catch (error) {
      console.warn('Failed to fetch team members, falling back to mock:', error);
      setTeam(mockTeam);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTeam(); // eslint-disable-line react-hooks/set-state-in-effect // eslint-disable-line @typescript-eslint/no-floating-promises
  }, []);

  const handleInvite = async () => {
    if (!inviteData.email) return;
    setInviting(true);
    try {
      await TeamService.addTeamMember(inviteData);
      setIsInviteModalOpen(false);
      setInviteData({ email: '', full_name: '', role: 'manager' });
      fetchTeam(); // eslint-disable-line @typescript-eslint/no-floating-promises
    } catch (error) {
      console.error('Failed to invite member', error);
      alert('Failed to invite member');
    } finally {
      setInviting(false);
    }
  };

  const handleRoleChange = async (id: string, newRole: string) => {
    setUpdatingId(id);
    try {
      await TeamService.updateTeamMemberRole(id, newRole);
      fetchTeam(); // eslint-disable-line @typescript-eslint/no-floating-promises
    } catch (error) {
      console.error('Failed to update role', error);
      alert('Failed to update role');
    } finally {
      setUpdatingId(null);
    }
  };

  const handleRemove = async (id: string) => {
    if (!window.confirm('Are you sure you want to remove this member?')) return;
    setUpdatingId(id);
    try {
      // Use existing service if it exists, or handle directly
      // Assuming TeamService.removeTeamMember exists, if not we will just filter the state for now
      if ((TeamService as any).removeTeamMember) { // eslint-disable-line @typescript-eslint/no-explicit-any
        await (TeamService as any).removeTeamMember(id); // eslint-disable-line @typescript-eslint/no-explicit-any
        fetchTeam(); // eslint-disable-line @typescript-eslint/no-floating-promises
      } else {
        setTeam(team.filter((m) => m.id !== id));
      }
    } catch (error) {
      console.error('Failed to remove member', error);
      alert('Failed to remove member');
    } finally {
      setUpdatingId(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-display-sm font-semibold text-on-background">Team Management</h1>
          <p className="text-body-sm text-on-surface-variant mt-1">Manage staff access and roles</p>
        </div>
        <Button className="gap-2" onClick={() => setIsInviteModalOpen(true)}>
          <Plus className="h-4 w-4" />
          Invite Member
        </Button>
      </div>

      <Card>
        <div className="flex items-center justify-between p-4 border-b border-outline-variant">
          <div className="flex items-center gap-2 max-w-sm w-full">
            <div className="relative w-full">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-on-surface-variant" />
              <Input
                placeholder="Search team members..."
                className="pl-9"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" className="gap-2">
              <Filter className="h-4 w-4" />
              Filters
            </Button>
          </div>
        </div>
        <div className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>User</TableHead>
                <TableHead>Role</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Last Active</TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={5} className="text-center py-8 text-on-surface-variant">
                    Loading team...
                  </TableCell>
                </TableRow>
              ) : (
                team.map((member) => (
                  <TableRow key={member.id}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <div className="h-10 w-10 rounded-full bg-primary-container text-on-primary-container flex items-center justify-center font-bold text-sm">
                          {member.name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <div className="font-medium text-on-surface">{member.name}</div>
                          <div className="text-sm text-on-surface-variant flex items-center gap-1 mt-0.5">
                            <Mail className="h-3 w-3" />
                            {member.email}
                          </div>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1.5 text-on-surface">
                        <Shield
                          className={`h-4 w-4 ${member.role === 'super-admin' ? 'text-primary' : 'text-on-surface-variant'}`}
                        />
                        <select
                          className="bg-transparent text-sm border-none focus:ring-0 cursor-pointer"
                          value={member.role}
                          disabled={updatingId === member.id}
                          onChange={(e) => handleRoleChange(member.id, e.target.value)}
                        >
                          <option value="super-admin">Super Admin</option>
                          <option value="admin">Admin</option>
                          <option value="manager">Manager</option>
                          <option value="support">Support</option>
                          <option value="warehouse-staff">Warehouse Staff</option>
                        </select>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant={member.status === 'active' ? 'success' : 'warning'}>
                        {member.status.charAt(0).toUpperCase() + member.status.slice(1)}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-on-surface-variant">{member.lastActive}</TableCell>
                    <TableCell>
                      <button
                        onClick={() => handleRemove(member.id)}
                        disabled={updatingId === member.id}
                        title="Remove Member"
                        className="text-error/70 hover:text-error p-1 rounded-md hover:bg-error/10 transition-colors"
                      >
                        <Trash2 className="h-5 w-5" />
                      </button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      </Card>

      {isInviteModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-surface rounded-xl shadow-xl w-full max-w-md overflow-hidden">
            <div className="px-6 py-4 border-b border-outline-variant flex items-center justify-between">
              <h2 className="text-title-lg font-semibold">Invite Team Member</h2>
              <button
                onClick={() => setIsInviteModalOpen(false)}
                className="text-on-surface-variant hover:text-on-surface"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-2">
                <label className="text-sm font-medium text-on-surface">Email Address</label>
                <Input
                  placeholder="colleague@example.com"
                  type="email"
                  value={inviteData.email}
                  onChange={(e) => setInviteData({ ...inviteData, email: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-medium text-on-surface">Full Name</label>
                <Input
                  placeholder="John Doe"
                  value={inviteData.full_name}
                  onChange={(e) => setInviteData({ ...inviteData, full_name: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-medium text-on-surface">Role</label>
                <select
                  className="flex h-10 w-full rounded-md border border-outline bg-surface px-3 py-2 text-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2"
                  value={inviteData.role}
                  onChange={(e) => setInviteData({ ...inviteData, role: e.target.value })}
                >
                  <option value="super-admin">Super Admin</option>
                  <option value="admin">Admin</option>
                  <option value="manager">Manager</option>
                  <option value="support">Support</option>
                  <option value="warehouse-staff">Warehouse Staff</option>
                </select>
              </div>
            </div>
            <div className="px-6 py-4 border-t border-outline-variant flex justify-end gap-3 bg-surface-container-lowest">
              <Button variant="outline" onClick={() => setIsInviteModalOpen(false)}>
                Cancel
              </Button>
              <Button onClick={handleInvite} disabled={inviting || !inviteData.email}>
                {inviting ? 'Inviting...' : 'Send Invitation'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Input } from '@byteevolvr/ui';
import {
  ScanBarcode,
  PackageCheck,
  AlertTriangle,
  Loader2,
  CheckCircle2,
  RefreshCcw,
  Building2,
  MapPin,
  Plus,
  Edit2,
  X,
} from 'lucide-react';
import { AdminService } from '@byteevolvr/api-client';

export function WarehousePage() {
  const [activeTab, setActiveTab] = useState<'management' | 'operations'>('management');
  const [warehouses, setWarehouses] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [pickTasks, setPickTasks] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [editingWarehouse, setEditingWarehouse] = useState<any>(null); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    address: '',
    is_active: true,
  });

  useEffect(() => {
    fetchData(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, [activeTab]); // eslint-disable-line react-hooks/exhaustive-deps

  async function fetchData() {
    setLoading(true);
    try {
      if (activeTab === 'management') {
        const data = await AdminService.getWarehouses();
        setWarehouses(data || []);
      } else {
        const data = await AdminService.getWarehouseTasks();
        setPickTasks(data || []);
      }
    } catch (err) {
      console.error('Error fetching warehouse data:', err);
    } finally {
      setLoading(false);
    }
  }

  const handleSaveWarehouse = async () => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      if (editingWarehouse) {
        await AdminService.updateWarehouse(editingWarehouse.id, formData);
      } else {
        await AdminService.createWarehouse(formData);
      }
      setShowModal(false);
      setEditingWarehouse(null);
      await fetchData();
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      console.error('Error saving warehouse:', err);
      alert(err.customMessage || 'Failed to save warehouse. Please check your connection.');
    } finally {
      setIsSaving(false);
    }
  };

  const markAsPicked = async (task: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
    // Optimistic UI update
    setPickTasks((prev) => prev.map((t) => (t.id === task.id ? { ...t, picked: true } : t)));
    try {
      await AdminService.markTaskPicked({
        orderId: task.order?.id || task.order_id,
        productId: task.product_id,
        notes: `Picked: ${task.product_name} (x${task.quantity}) — SKU: ${task.sku}`,
      });
    } catch (err) {
      console.error('Failed to persist pick:', err);
      // Roll back optimistic update on failure
      setPickTasks((prev) => prev.map((t) => (t.id === task.id ? { ...t, picked: false } : t)));
    }
  };

  return (
    <div className="space-y-8 max-w-6xl mx-auto pb-20">
      {/* Header & Tabs */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h1 className="text-4xl font-black tracking-tight text-on-surface uppercase italic">
            Warehouse Console
          </h1>
          <div className="flex gap-1 mt-4 p-1 bg-surface-container rounded-2xl w-fit">
            <button
              onClick={() => setActiveTab('management')}
              className={`px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'management' ? 'bg-white text-primary shadow-sm' : 'text-on-surface-variant hover:text-on-surface'}`}
            >
              Management
            </button>
            <button
              onClick={() => setActiveTab('operations')}
              className={`px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${activeTab === 'operations' ? 'bg-white text-primary shadow-sm' : 'text-on-surface-variant hover:text-on-surface'}`}
            >
              Operations
            </button>
          </div>
        </div>

        <div className="flex gap-3">
          <Button
            variant="outline"
            className="h-12 w-12 p-0 rounded-2xl"
            onClick={fetchData}
            disabled={loading}
          >
            <RefreshCcw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
          </Button>
          {activeTab === 'management' ? (
            <Button
              className="h-12 px-6 rounded-2xl gap-2 font-bold"
              onClick={() => {
                setEditingWarehouse(null);
                setFormData({ name: '', location: '', address: '', is_active: true });
                setShowModal(true);
              }}
            >
              <Plus className="h-4 w-4" /> Add Warehouse
            </Button>
          ) : (
            <Button className="h-12 px-6 rounded-2xl gap-2 font-bold bg-primary text-on-primary">
              <ScanBarcode className="h-4 w-4" /> Scan Item
            </Button>
          )}
        </div>
      </div>

      {activeTab === 'management' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {loading
            ? Array(3)
                .fill(0)
                .map((_, i) => (
                  <div
                    key={i}
                    className="h-48 rounded-3xl bg-surface-container animate-pulse"
                  ></div>
                ))
            : warehouses.map((w) => (
                <Card
                  key={w.id}
                  className="border-none shadow-sm group hover:shadow-md transition-all overflow-hidden bg-surface-container-low"
                >
                  <div className="p-6">
                    <div className="flex justify-between items-start mb-6">
                      <div className="h-12 w-12 rounded-2xl bg-primary/10 flex items-center justify-center text-primary">
                        <Building2 className="h-6 w-6" />
                      </div>
                      <Badge variant={w.is_active ? 'success' : 'secondary'}>
                        {w.is_active ? 'ACTIVE' : 'INACTIVE'}
                      </Badge>
                    </div>
                    <h3 className="text-xl font-bold text-on-surface mb-1">{w.name}</h3>
                    <div className="flex items-center gap-2 text-sm text-on-surface-variant mb-6">
                      <MapPin className="h-4 w-4 text-primary" />
                      {w.location}
                    </div>
                    <div className="pt-4 border-t border-outline-variant flex justify-end items-center">
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-9 w-9 p-0 rounded-xl bg-surface hover:bg-primary/10 hover:text-primary transition-all shadow-sm border border-outline-variant flex items-center justify-center"
                        onClick={() => {
                          setEditingWarehouse(w);
                          setFormData({
                            name: w.name,
                            location: w.location,
                            address: w.address || '',
                            is_active: w.is_active,
                          });
                          setShowModal(true);
                        }}
                      >
                        <Edit2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                </Card>
              ))}
        </div>
      ) : (
        <div className="space-y-6">
          <div className="bg-warning-container text-on-warning-container p-6 rounded-3xl border border-warning/20 flex items-start gap-4">
            <AlertTriangle className="h-6 w-6 shrink-0 text-warning" />
            <div>
              <h4 className="font-bold">Pending Picking Tasks</h4>
              <p className="text-sm mt-1 opacity-90">
                There are {pickTasks.filter((t) => !t.picked).length} items waiting to be picked
                across the system.
              </p>
            </div>
          </div>

          <div className="space-y-4">
            {loading ? (
              <div className="py-20 flex flex-col items-center justify-center text-on-surface-variant">
                <Loader2 className="h-8 w-8 animate-spin text-primary mb-2" />
                Retrieving manifest...
              </div>
            ) : pickTasks.length === 0 ? (
              <div className="py-20 text-center text-on-surface-variant bg-surface-container-low rounded-3xl border-2 border-dashed border-outline-variant">
                <PackageCheck className="h-16 w-16 mx-auto mb-4 opacity-10" />
                <p className="text-lg font-medium">All tasks completed. Warehouse is clear!</p>
              </div>
            ) : (
              pickTasks.map((task) => (
                <Card
                  key={task.id}
                  className={`border-none shadow-sm transition-all ${task.picked ? 'opacity-50 grayscale bg-surface-container' : 'hover:shadow-md'}`}
                >
                  <div className="p-6 flex items-center justify-between">
                    <div className="flex items-center gap-6">
                      <div
                        className={`h-16 w-16 rounded-2xl flex items-center justify-center shrink-0 ${task.picked ? 'bg-success/10 text-success' : 'bg-surface-container border border-outline-variant text-on-surface'}`}
                      >
                        {task.picked ? (
                          <CheckCircle2 className="h-8 w-8" />
                        ) : (
                          <span className="font-black text-2xl">{task.quantity}</span>
                        )}
                      </div>
                      <div>
                        <div className="flex items-center gap-3 mb-1">
                          <span
                            className={`text-lg font-bold ${task.picked ? 'line-through decoration-2' : 'text-on-surface'}`}
                          >
                            {task.product_name}
                          </span>
                          <Badge
                            variant="primary"
                            className="font-mono text-[10px] tracking-tighter uppercase"
                          >
                            {task.order?.order_number}
                          </Badge>
                        </div>
                        <div className="text-xs text-on-surface-variant flex gap-6 font-medium uppercase tracking-widest">
                          <span>
                            SKU: <span className="font-bold text-on-surface">{task.sku}</span>
                          </span>
                          <span className="flex items-center gap-1 text-primary">
                            <MapPin className="h-3 w-3" />{' '}
                            {task.product?.warehouse_location || 'ZONE-A'}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div>
                      {!task.picked && (
                        <Button
                          size="sm"
                          className="h-10 px-6 rounded-xl font-bold uppercase tracking-widest text-[10px]"
                          onClick={() => markAsPicked(task)}
                        >
                          Mark Picked
                        </Button>
                      )}
                    </div>
                  </div>
                </Card>
              ))
            )}
          </div>
        </div>
      )}

      {/* Warehouse Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-slate-900/70 backdrop-blur-md"
            onClick={() => setShowModal(false)}
          />
          <div
            className="relative bg-surface w-full max-w-[500px] min-w-[320px] shadow-2xl rounded-3xl border border-white/10 flex flex-col overflow-hidden animate-in zoom-in-95 duration-200"
            style={{ width: '500px' }}
          >
            <div className="p-8 border-b border-outline-variant flex justify-between items-center bg-surface-container-low">
              <div className="flex items-center gap-5">
                <div className="h-14 w-14 rounded-2xl bg-primary/10 flex items-center justify-center text-primary shadow-inner">
                  <Building2 className="h-8 w-8" />
                </div>
                <div>
                  <h3 className="text-2xl font-black text-on-surface tracking-tight uppercase">
                    {editingWarehouse ? 'Update Warehouse' : 'New Warehouse'}
                  </h3>
                  <p className="text-xs font-bold text-on-surface-variant tracking-widest uppercase opacity-70">
                    Logistics Node Configuration
                  </p>
                </div>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowModal(false)}
                className="rounded-full h-10 w-10 p-0 hover:bg-error/10 hover:text-error transition-all"
              >
                <X className="h-6 w-6" />
              </Button>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-8">
              <div className="space-y-8">
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 flex items-center gap-2">
                    <Building2 className="h-3 w-3" /> Entity Name
                  </label>
                  <Input
                    placeholder="e.g. Mumbai North Hub"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="h-14 px-6 rounded-2xl font-black border-outline focus:ring-primary"
                  />
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 flex items-center gap-2">
                    <MapPin className="h-3 w-3" /> Location Region
                  </label>
                  <Input
                    placeholder="e.g. Maharashtra"
                    value={formData.location}
                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                    className="h-14 px-6 rounded-2xl font-black border-outline focus:ring-primary"
                  />
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-black text-on-surface-variant uppercase tracking-widest ml-1 flex items-center gap-2">
                    <MapPin className="h-3 w-3" /> Full Logistics Address
                  </label>
                  <Input
                    placeholder="Detailed street address..."
                    value={formData.address}
                    onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                    className="h-14 px-6 rounded-2xl font-bold border-outline focus:ring-primary"
                  />
                </div>

                <div className="flex items-center gap-4 p-4 bg-surface-container-low rounded-2xl border border-outline-variant">
                  <input
                    type="checkbox"
                    id="is_active"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                    className="h-6 w-6 rounded-lg border-outline accent-primary cursor-pointer"
                  />
                  <label
                    htmlFor="is_active"
                    className="text-sm font-black text-on-surface uppercase tracking-tight cursor-pointer"
                  >
                    Mark Hub as Operational
                  </label>
                </div>

                <div className="pt-6 flex gap-4">
                  <Button
                    variant="ghost"
                    onClick={() => setShowModal(false)}
                    className="flex-1 h-14 rounded-2xl font-black uppercase tracking-widest hover:bg-surface-container transition-colors"
                  >
                    Cancel
                  </Button>
                  <Button
                    onClick={handleSaveWarehouse}
                    disabled={!formData.name || !formData.location || isSaving}
                    className="flex-1 h-14 rounded-2xl font-black uppercase tracking-widest text-xs shadow-lg shadow-primary/20"
                  >
                    {isSaving ? (
                      <Loader2 className="h-5 w-5 animate-spin" />
                    ) : editingWarehouse ? (
                      'Update Hub'
                    ) : (
                      'Initialize Hub'
                    )}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Card, Button, Input } from '@byteevolvr/ui';
import { Plus, Search, FileText } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { apiClient, CMSService } from '@byteevolvr/api-client';

import { CreateInvoiceModal } from './components/CreateInvoiceModal';

export function InvoicesPage() {
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const { data: invoicesResponse, isLoading } = useQuery({
    queryKey: ['invoices'],
    queryFn: async () => {
      const res = await apiClient.get('/accounting/invoices');
      return res.data;
    },
  });

  const { data: globalSettings } = useQuery({
    queryKey: ['global-settings'],
    queryFn: async () => {
      const cmsData = await CMSService.getContent('global');
      return cmsData?.find((s: any) => s.section_key === 'contact')?.content || {}; // eslint-disable-line @typescript-eslint/no-explicit-any
    },
  });

  const currencyRaw = globalSettings?.currency || 'USD ($)';
  const symbolMatch = currencyRaw.match(/\(([^)]+)\)/);
  const currencySymbol = symbolMatch ? symbolMatch[1] : '$';

  const invoices = Array.isArray(invoicesResponse)
    ? invoicesResponse
    : (invoicesResponse as any)?.data || []; // eslint-disable-line @typescript-eslint/no-explicit-any

  const filteredInvoices = invoices.filter(
    (inv: any) => // eslint-disable-line @typescript-eslint/no-explicit-any
      inv.customer_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      inv.invoice_number.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-display-sm font-bold text-on-surface">Invoices</h1>
          <p className="text-body-md text-on-surface-variant">
            Manage B2B and B2C billing with GST compliance
          </p>
        </div>
        <Button onClick={() => setShowCreateModal(true)} className="flex items-center gap-2">
          <Plus className="w-5 h-5" />
          Create Invoice
        </Button>
      </div>

      <Card className="p-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <div className="relative w-full sm:w-96">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-on-surface-variant w-5 h-5" />
            <Input
              placeholder="Search invoices..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 w-full"
            />
          </div>
        </div>

        {isLoading ? (
          <div>Loading invoices...</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse whitespace-nowrap">
              <thead>
                <tr className="border-b border-outline">
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">
                    Invoice #
                  </th>
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">
                    Customer
                  </th>
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">Type</th>
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">Status</th>
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">Date</th>
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">Total</th>
                  <th className="py-3 px-4 font-medium text-sm text-on-surface-variant">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredInvoices.map((inv: any) => ( // eslint-disable-line @typescript-eslint/no-explicit-any
                  <tr key={inv.id} className="hover:bg-surface-container/50 transition-colors">
                    <td className="py-3 px-4 font-medium">{inv.invoice_number}</td>
                    <td className="py-3 px-4">
                      <div className="font-medium text-on-surface">{inv.customer_name}</div>
                      {inv.type === 'b2b' && inv.customer_gst && (
                        <div className="text-xs font-semibold text-primary/80 mt-0.5">
                          GSTIN: {inv.customer_gst}
                        </div>
                      )}
                    </td>
                    <td className="py-3 px-4">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-medium uppercase ${inv.type === 'b2b' ? 'bg-blue-500/10 text-blue-500' : 'bg-green-500/10 text-green-500'}`}
                      >
                        {inv.type}
                      </span>
                    </td>
                    <td className="py-3 px-4">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-medium capitalize ${
                          inv.status === 'paid'
                            ? 'bg-green-500/10 text-green-500'
                            : inv.status === 'sent'
                              ? 'bg-blue-500/10 text-blue-500'
                              : 'bg-yellow-500/10 text-yellow-500'
                        }`}
                      >
                        {inv.status}
                      </span>
                    </td>
                    <td className="py-3 px-4">{new Date(inv.created_at).toLocaleDateString()}</td>
                    <td className="py-3 px-4 font-semibold">
                      {currencySymbol}
                      {Number(inv.total).toFixed(2)}
                    </td>
                    <td className="py-3 px-4">
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-primary hover:text-primary/80"
                      >
                        <FileText className="w-4 h-4 mr-2" /> View
                      </Button>
                    </td>
                  </tr>
                ))}
                {filteredInvoices.length === 0 && (
                  <tr>
                    <td colSpan={7} className="text-center py-8 text-on-surface-variant">
                      No invoices found.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {showCreateModal && (
        <CreateInvoiceModal
          onClose={() => setShowCreateModal(false)}
          currencySymbol={currencySymbol}
        />
      )}
    </div>
  );
}

import { useState } from 'react';
import { Card, Button, Input } from '@byteevolvr/ui';
import { Plus, ChevronDown } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { apiClient } from '@byteevolvr/api-client';

import { CustomDatePicker } from './CustomDatePicker';
import { ProductAutocomplete } from './ProductAutocomplete';

export function CreateInvoiceModal({
  onClose,
  currencySymbol,
}: {
  onClose: () => void;
  currencySymbol: string;
}) {
  const queryClient = useQueryClient();
  const [formData, setFormData] = useState({
    type: 'b2c',
    customer_name: '',
    customer_email: '',
    customer_phone: '',
    customer_gst: '',
    customer_address: '',
    status: 'draft',
    due_date: new Date().toISOString().split('T')[0], // Default to today
    supply_type: 'intra-state', // intra-state (CGST+SGST) or inter-state (IGST)
  });

  const [lineItems, setLineItems] = useState([
    { description: '', hsn_code: '', quantity: 1, unit_price: 0, tax_rate: 18 },
  ]);

  const createMutation = useMutation({
    mutationFn: async () => {
      return apiClient.post('/accounting/invoices', {
        invoice: formData,
        lineItems,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['invoices'] }); // eslint-disable-line @typescript-eslint/no-floating-promises
      onClose();
    },
    onError: (err: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
      alert(`Error creating invoice: ${err.message}`);
    },
  });

  const handleSave = () => {
    if (!formData.customer_name) return alert('Customer name required');
    if (formData.type === 'b2b' && !formData.customer_gst)
      return alert('GST is required for B2B invoices');

    // Check if line items are filled
    const invalidItem = lineItems.find((item) => !item.description || item.unit_price <= 0);
    if (invalidItem) return alert('All line items must have a description and price > 0');

    createMutation.mutate();
  };

  // Calculate totals
  const subtotal = lineItems.reduce((sum, item) => sum + item.quantity * item.unit_price, 0);
  const taxTotal = lineItems.reduce(
    (sum, item) => sum + item.quantity * item.unit_price * (item.tax_rate / 100),
    0
  );
  const grandTotal = subtotal + taxTotal;

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <Card className="w-full max-w-5xl max-h-[90vh] overflow-y-auto flex flex-col bg-surface shadow-2xl">
        <div className="p-6 border-b border-outline bg-surface sticky top-0 z-10 flex justify-between items-center">
          <div>
            <h2 className="text-title-lg font-bold text-on-surface">Create GST Invoice</h2>
            <p className="text-sm text-on-surface-variant">
              Fill in the details to generate a new invoice.
            </p>
          </div>
          <Button
            variant="ghost"
            onClick={onClose}
            className="text-on-surface-variant hover:text-on-surface"
          >
            ✕
          </Button>
        </div>

        <div className="p-6 space-y-8 flex-1">
          {/* Customer & Invoice Details Cards */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Invoice Configuration Card */}
            <div className="bg-surface-container/20 border border-outline-variant/30 border-l-4 border-l-primary rounded-xl p-5 space-y-4">
              <h3 className="text-xs font-semibold text-primary uppercase tracking-wider">
                Invoice Configuration
              </h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-on-surface">Invoice Type</label>
                  <div className="relative">
                    <select
                      className="w-full px-3 py-2 bg-surface border border-outline rounded-md focus:outline-none focus:ring-2 focus:ring-primary text-on-surface appearance-none pr-10"
                      value={formData.type}
                      onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                    >
                      <option value="b2c">B2C (Retail)</option>
                      <option value="b2b">B2B (Business)</option>
                    </select>
                    <ChevronDown className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-on-surface-variant" />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-on-surface">Supply Type (GST)</label>
                  <div className="relative">
                    <select
                      className="w-full px-3 py-2 bg-surface border border-outline rounded-md focus:outline-none focus:ring-2 focus:ring-primary text-on-surface appearance-none pr-10"
                      value={formData.supply_type}
                      onChange={(e) => setFormData({ ...formData, supply_type: e.target.value })}
                    >
                      <option value="intra-state">Intra-State (CGST + SGST)</option>
                      <option value="inter-state">Inter-State (IGST)</option>
                    </select>
                    <ChevronDown className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-on-surface-variant" />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-on-surface">Status</label>
                  <div className="relative">
                    <select
                      className="w-full px-3 py-2 bg-surface border border-outline rounded-md focus:outline-none focus:ring-2 focus:ring-primary text-on-surface appearance-none pr-10"
                      value={formData.status}
                      onChange={(e) => setFormData({ ...formData, status: e.target.value })}
                    >
                      <option value="draft">Draft</option>
                      <option value="sent">Sent</option>
                      <option value="paid">Paid</option>
                    </select>
                    <ChevronDown className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-on-surface-variant" />
                  </div>
                </div>

                <CustomDatePicker
                  label="Due Date *"
                  value={formData.due_date}
                  onChange={(val) => setFormData({ ...formData, due_date: val })}
                />
              </div>
            </div>

            {/* Customer & Billing Card */}
            <div className="bg-surface-container/20 border border-outline-variant/30 border-l-4 border-l-emerald-500 rounded-xl p-5 space-y-4">
              <h3 className="text-xs font-semibold text-emerald-500 uppercase tracking-wider">
                Customer & Billing Info
              </h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="sm:col-span-2">
                  <Input
                    label="Customer Name *"
                    placeholder="e.g. Acme Corp"
                    value={formData.customer_name}
                    onChange={(e) => setFormData({ ...formData, customer_name: e.target.value })}
                    className="w-full"
                  />
                </div>

                <Input
                  label="Customer Email"
                  type="email"
                  placeholder="billing@acme.com"
                  value={formData.customer_email}
                  onChange={(e) => setFormData({ ...formData, customer_email: e.target.value })}
                />

                {formData.type === 'b2b' ? (
                  <Input
                    label="GSTIN Number *"
                    placeholder="22AAAAA0000A1Z5"
                    value={formData.customer_gst}
                    onChange={(e) => setFormData({ ...formData, customer_gst: e.target.value })}
                  />
                ) : (
                  <div className="hidden sm:block" />
                )}
              </div>
            </div>
          </div>

          <hr className="border-outline-variant" />

          {/* Line Items */}
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <div>
                <h3 className="text-title-md font-bold text-on-surface">Itemized Bill</h3>
                <p className="text-sm text-on-surface-variant">
                  Add products or services to this invoice.
                </p>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() =>
                  setLineItems([
                    ...lineItems,
                    { description: '', hsn_code: '', quantity: 1, unit_price: 0, tax_rate: 18 },
                  ])
                }
                className="bg-primary/5 hover:bg-primary/10 border-primary/20 text-primary"
              >
                <Plus className="w-4 h-4 mr-1" /> Add Row
              </Button>
            </div>

            <div className="bg-surface-container/20 border border-outline rounded-lg p-1 overflow-visible pb-32">
              <table className="w-full text-left border-collapse whitespace-nowrap min-w-[800px] table-fixed">
                <thead>
                  <tr className="bg-surface-container/50">
                    <th className="py-2 px-3 text-xs font-semibold text-on-surface-variant uppercase w-[38%]">
                      Item Description
                    </th>
                    <th className="py-2 px-3 text-xs font-semibold text-on-surface-variant uppercase w-[15%]">
                      HSN/SAC
                    </th>
                    <th className="py-2 px-3 text-xs font-semibold text-on-surface-variant uppercase w-[10%]">
                      Qty
                    </th>
                    <th className="py-2 px-3 text-xs font-semibold text-on-surface-variant uppercase w-[15%]">
                      Rate ({currencySymbol})
                    </th>
                    <th className="py-2 px-3 text-xs font-semibold text-on-surface-variant uppercase w-[10%]">
                      GST %
                    </th>
                    <th className="py-2 px-3 text-xs font-semibold text-on-surface-variant uppercase w-[10%] text-right">
                      Amount
                    </th>
                    <th className="py-2 px-3 w-[2%]"></th>
                  </tr>
                </thead>
                <tbody className="space-y-2">
                  {lineItems.map((item, idx) => {
                    const lineAmount = item.quantity * item.unit_price;

                    return (
                      <tr
                        key={idx}
                        className="border-b border-outline-variant/50 last:border-0 group"
                      >
                        <td className="p-2 w-[38%]">
                          <ProductAutocomplete
                            value={item.description}
                            onChange={(val) => {
                              const newItems = [...lineItems];
                              newItems[idx].description = val;
                              setLineItems(newItems);
                            }}
                            onSelectProduct={(p) => {
                              const newItems = [...lineItems];
                              newItems[idx].description = p.name;
                              newItems[idx].unit_price = Number(p.price) || 0;
                              newItems[idx].tax_rate = p.tax_rate || 18;
                              if (p.sku) newItems[idx].hsn_code = p.sku;
                              setLineItems(newItems);
                            }}
                          />
                        </td>
                        <td className="p-2 w-[15%]">
                          <Input
                            placeholder="HSN"
                            value={item.hsn_code}
                            onChange={(e) => {
                              const newItems = [...lineItems];
                              newItems[idx].hsn_code = e.target.value;
                              setLineItems(newItems);
                            }}
                          />
                        </td>
                        <td className="p-2 w-[10%]">
                          <Input
                            type="number"
                            placeholder="1"
                            min="1"
                            value={item.quantity}
                            onChange={(e) => {
                              const newItems = [...lineItems];
                              newItems[idx].quantity = Number(e.target.value) || 0;
                              setLineItems(newItems);
                            }}
                          />
                        </td>
                        <td className="p-2 w-[15%]">
                          <Input
                            type="number"
                            placeholder="0.00"
                            value={item.unit_price}
                            onChange={(e) => {
                              const newItems = [...lineItems];
                              newItems[idx].unit_price = Number(e.target.value) || 0;
                              setLineItems(newItems);
                            }}
                          />
                        </td>
                        <td className="p-2 w-[10%]">
                          <div className="relative">
                            <select
                              className="w-full px-3 py-2 bg-surface border border-outline rounded-md focus:outline-none focus:ring-2 focus:ring-primary text-on-surface appearance-none pr-8"
                              value={item.tax_rate}
                              onChange={(e) => {
                                const newItems = [...lineItems];
                                newItems[idx].tax_rate = Number(e.target.value);
                                setLineItems(newItems);
                              }}
                            >
                              <option value="0">0%</option>
                              <option value="5">5%</option>
                              <option value="12">12%</option>
                              <option value="18">18%</option>
                              <option value="28">28%</option>
                            </select>
                            <ChevronDown className="w-4 h-4 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-on-surface-variant" />
                          </div>
                        </td>
                        <td className="p-2 w-[10%] text-right font-medium text-on-surface">
                          {currencySymbol}
                          {lineAmount.toFixed(2)}
                        </td>
                        <td className="p-2 w-[2%] text-center">
                          <button
                            className="p-1.5 text-on-surface-variant hover:text-red-500 hover:bg-red-500/10 rounded-md transition-colors opacity-0 group-hover:opacity-100 disabled:opacity-50"
                            onClick={() => setLineItems(lineItems.filter((_, i) => i !== idx))}
                            disabled={lineItems.length === 1}
                            title="Remove row"
                          >
                            ✕
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            {/* Totals Section */}
            <div className="flex justify-end pt-4">
              <div className="w-full sm:w-1/3 space-y-3 bg-surface-container/30 p-4 rounded-lg border border-outline">
                <div className="flex justify-between text-sm text-on-surface-variant">
                  <span>Subtotal</span>
                  <span className="font-medium text-on-surface">
                    {currencySymbol}
                    {subtotal.toFixed(2)}
                  </span>
                </div>

                {formData.supply_type === 'intra-state' ? (
                  <>
                    <div className="flex justify-between text-sm text-on-surface-variant">
                      <span>CGST (Total)</span>
                      <span className="font-medium text-on-surface">
                        {currencySymbol}
                        {(taxTotal / 2).toFixed(2)}
                      </span>
                    </div>
                    <div className="flex justify-between text-sm text-on-surface-variant">
                      <span>SGST (Total)</span>
                      <span className="font-medium text-on-surface">
                        {currencySymbol}
                        {(taxTotal / 2).toFixed(2)}
                      </span>
                    </div>
                  </>
                ) : (
                  <div className="flex justify-between text-sm text-on-surface-variant">
                    <span>IGST (Total)</span>
                    <span className="font-medium text-on-surface">
                      {currencySymbol}
                      {taxTotal.toFixed(2)}
                    </span>
                  </div>
                )}

                <hr className="border-outline-variant" />
                <div className="flex justify-between items-center text-lg font-bold text-primary">
                  <span>Grand Total</span>
                  <span>
                    {currencySymbol}
                    {grandTotal.toFixed(2)}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="p-4 sm:p-6 border-t border-outline flex justify-end gap-3 bg-surface sticky bottom-0 z-10 rounded-b-xl">
          <Button variant="outline" onClick={onClose} disabled={createMutation.isPending}>
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            disabled={createMutation.isPending}
            className="min-w-[140px]"
          >
            {createMutation.isPending ? 'Saving...' : 'Create Invoice'}
          </Button>
        </div>
      </Card>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { Input } from '@byteevolvr/ui';
import { useQuery } from '@tanstack/react-query';
import { apiClient, CMSService } from '@byteevolvr/api-client';

export function ProductAutocomplete({
  value,
  onChange,
  onSelectProduct,
}: {
  value: string;
  onChange: (val: string) => void;
  onSelectProduct: (product: any) => void; // eslint-disable-line @typescript-eslint/no-explicit-any
}) {
  const [isOpen, setIsOpen] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  const { data } = useQuery({
    queryKey: ['admin-products'],
    queryFn: async () => {
      const res = await apiClient.get('/admin/products');
      return res.data;
    },
  });

  const { data: globalSettings } = useQuery({
    queryKey: ['global-settings'],
    queryFn: async () => {
      const cmsData = await CMSService.getContent('global');
      return cmsData?.find((s: any) => s.section_key === 'contact')?.content || {}; // eslint-disable-line @typescript-eslint/no-explicit-any
    },
  });

  const currencyRaw = globalSettings?.currency || 'USD ($)';
  const symbolMatch = currencyRaw.match(/\(([^)]+)\)/);
  const currencySymbol = symbolMatch ? symbolMatch[1] : '$';

  const products = Array.isArray(data) ? data : (data as any)?.data || []; // eslint-disable-line @typescript-eslint/no-explicit-any

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [wrapperRef]);

  const filteredProducts = products.filter(
    (p: any) => // eslint-disable-line @typescript-eslint/no-explicit-any
      (p.name && p.name.toLowerCase().includes((value || '').toLowerCase())) ||
      (p.sku && p.sku.toLowerCase().includes((value || '').toLowerCase()))
  );

  return (
    <div className="relative w-full" ref={wrapperRef}>
      <Input
        placeholder="Search for item..."
        value={value}
        onChange={(e) => {
          onChange(e.target.value);
          setIsOpen(true);
        }}
        onFocus={() => setIsOpen(true)}
      />
      {isOpen && (
        <div className="absolute z-[100] w-full mt-1 bg-surface border border-outline rounded-md shadow-2xl max-h-60 overflow-y-auto">
          {filteredProducts.length > 0 ? (
            filteredProducts.map((p: any) => ( // eslint-disable-line @typescript-eslint/no-explicit-any
              <div
                key={p.id}
                className="px-4 py-2.5 hover:bg-surface-container/80 cursor-pointer flex justify-between items-center transition-colors border-b border-outline-variant/30 last:border-0"
                onClick={() => {
                  onSelectProduct(p);
                  setIsOpen(false);
                }}
              >
                <div>
                  <div className="font-medium text-sm text-on-surface hover:text-primary transition-colors">
                    {p.name}
                  </div>
                  <div className="text-[11px] text-on-surface-variant flex items-center gap-1.5 mt-0.5">
                    <span className="bg-surface-container px-1.5 py-0.5 rounded border border-outline-variant/30">
                      SKU: {p.sku || 'N/A'}
                    </span>
                    {p.category && <span className="text-primary font-medium">{p.category}</span>}
                  </div>
                </div>
                <div className="text-sm font-semibold text-primary">
                  {currencySymbol}
                  {Number(p.price).toFixed(2)}
                </div>
              </div>
            ))
          ) : value.trim() !== '' ? (
            <div className="px-4 py-3 text-sm text-on-surface-variant text-center">
              No matching products found
            </div>
          ) : null}
        </div>
      )}
    </div>
  );
}

import { Button } from '@byteevolvr/ui';
import { MapPin, Phone, Mail, Globe } from 'lucide-react';

