interface CheckoutOrderSummaryProps {
  items: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  currencySymbol: string;
  subtotal: number;
  tax: number;
  shipping: number;
  shippingRates: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  selectedRate: number;
  setSelectedRate: (rate: number) => void;
  calculatingShipping: boolean;
  finalTotalAmount: number;
  loading: boolean;
  paymentMethod: string;
  couponCode: string;
  setCouponCode: (code: string) => void;
  appliedDiscount: { code: string; discount: number; couponId: string } | null;
  setAppliedDiscount: (
    discount: { code: string; discount: number; couponId: string } | null
  ) => void;
  discountLoading: boolean;
  setDiscountLoading: (loading: boolean) => void;
  discountError: string;
  setDiscountError: (error: string) => void;
  subtotalForDiscount: number;
}

export function CheckoutOrderSummary({
  items,
  currencySymbol,
  subtotal,
  tax,
  shipping,
  shippingRates,
  selectedRate,
  setSelectedRate,
  calculatingShipping,
  finalTotalAmount,
  loading,
  paymentMethod,
  couponCode,
  setCouponCode,
  appliedDiscount,
  setAppliedDiscount,
  discountLoading,
  setDiscountLoading,
  discountError,
  setDiscountError,
  subtotalForDiscount,
}: CheckoutOrderSummaryProps) {
  const handleApplyDiscount = async () => {
    if (!couponCode) return;
    setDiscountLoading(true);
    setDiscountError('');
    try {
      const res = await MarketingService.validateCoupon(couponCode, subtotalForDiscount);
      if (res.couponId && res.code) {
        setAppliedDiscount({
          code: res.code,
          discount: res.discount,
          couponId: res.couponId,
        });
        setCouponCode('');
      } else {
        setDiscountError(res.message || 'Invalid coupon'); // eslint-disable-line @typescript-eslint/no-explicit-any
      }
    } catch (err: any) {
      setDiscountError(
        err.customMessage || err.response?.data?.message || 'Failed to apply coupon'
      );
    } finally {
      setDiscountLoading(false);
    }
  };

  const handleRemoveDiscount = () => {
    setAppliedDiscount(null);
  };
  return (
    <aside className="lg:col-span-4 sticky top-24 space-y-stitch-gutter">
      <div className="stitch-glass-panel p-8 rounded-xl overflow-hidden relative">
        {/* Subtle Glow Ornament */}
        <div className="absolute -top-12 -right-12 w-32 h-32 bg-stitch-primary/10 blur-[60px] rounded-full"></div>

        <h2 className="font-stitch-headline-lg text-stitch-headline-lg text-white mb-6 relative z-10">
          ORDER_SUMMARY
        </h2>

        {/* Product Teaser(s) */}
        <div className="space-y-4 mb-8 max-h-60 overflow-y-auto stitch-no-scrollbar relative z-10">
          {items.map((item) => (
            <div
              key={item.id}
              className="flex gap-4 p-4 rounded-lg bg-stitch-surface-container-lowest border border-stitch-outline-variant/10"
            >
              <div className="w-20 h-20 bg-stitch-surface-variant rounded flex-shrink-0 overflow-hidden">
                <img
                  className="w-full h-full object-cover transition-all duration-500"
                  src={item.image_url || 'https://via.placeholder.com/150'}
                  alt={item.name}
                />
              </div>
              <div className="flex flex-col justify-center">
                <h3 className="font-stitch-cta-button text-stitch-cta-button text-white">
                  {item.quantity}x {item.name}
                </h3>
                <p className="font-stitch-label-sm text-stitch-label-sm text-stitch-primary mt-1">
                  {currencySymbol}
                  {(item.price * item.quantity).toFixed(2)}
                </p>
              </div>
            </div>
          ))}
        </div>

        {/* Price Breakdown */}
        <div className="space-y-3 font-stitch-body-md text-stitch-body-md border-b border-stitch-outline-variant/20 pb-6 mb-6 relative z-10">
          <div className="flex justify-between">
            <span className="text-stitch-outline">Subtotal</span>
            <span className="text-white">
              {currencySymbol}
              {subtotal.toFixed(2)}
            </span>
          </div>

          {/* Discount Section */}
          <div className="pt-4 border-t border-stitch-outline-variant/20 mt-4 mb-4">
            {!appliedDiscount ? (
              <div className="space-y-2">
                <div className="flex gap-2">
                  <input
                    type="text"
                    placeholder="Discount code"
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value)}
                    className="flex-1 bg-stitch-surface-container-lowest border border-stitch-outline-variant/50 text-white rounded px-3 py-2 text-sm focus:outline-none focus:border-stitch-primary"
                  />
                  <button
                    type="button"
                    onClick={handleApplyDiscount}
                    disabled={discountLoading || !couponCode}
                    className="bg-stitch-primary/20 text-stitch-primary hover:bg-stitch-primary/30 px-4 py-2 rounded text-sm font-bold transition-colors disabled:opacity-50"
                  >
                    {discountLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'APPLY'}
                  </button>
                </div>
                {discountError && <p className="text-stitch-error text-xs">{discountError}</p>}
              </div>
            ) : (
              <div className="flex justify-between items-center bg-stitch-primary/10 border border-stitch-primary/30 rounded p-3">
                <div className="flex flex-col">
                  <span className="text-stitch-primary font-bold flex items-center gap-2">
                    <Award className="w-4 h-4" /> {appliedDiscount.code}
                  </span>
                  <button
                    type="button"
                    onClick={handleRemoveDiscount}
                    className="text-xs text-stitch-outline hover:text-white text-left mt-1 underline"
                  >
                    Remove
                  </button>
                </div>
                <span className="text-stitch-primary font-bold">
                  -{currencySymbol}
                  {appliedDiscount.discount.toFixed(2)}
                </span>
              </div>
            )}
          </div>

          <div className="flex justify-between items-center">
            <div className="flex flex-col">
              <span className="text-stitch-outline">Shipping</span>
              {shippingRates.length > 0 && (
                <select
                  value={selectedRate}
                  onChange={(e) => setSelectedRate(Number(e.target.value))}
                  className="text-[10px] bg-transparent border-none text-stitch-secondary focus:ring-0 p-0 cursor-pointer w-32"
                >
                  {shippingRates.map((r, i) => (
                    <option
                      key={i}
                      value={r.rate}
                      className="bg-stitch-surface-container text-white"
                    >
                      {r.courier_name} ({currencySymbol}
                      {r.rate})
                    </option>
                  ))}
                </select>
              )}
            </div>
            <span className="text-stitch-secondary">
              {calculatingShipping ? (
                <Loader2 className="h-4 w-4 animate-spin text-stitch-secondary" />
              ) : shipping === 0 ? (
                'FREE'
              ) : (
                `${currencySymbol}${shipping.toFixed(2)}`
              )}
            </span>
          </div>

          <div className="flex justify-between">
            <span className="text-stitch-outline">Estimated Tax (18%)</span>
            <span className="text-white">
              {currencySymbol}
              {tax.toFixed(2)}
            </span>
          </div>
        </div>

        {/* Delivery Date Badge */}
        <div className="flex items-center gap-3 p-4 bg-stitch-secondary-container/10 border border-stitch-secondary/20 rounded-lg mb-8 relative z-10">
          <Truck className="w-6 h-6 text-stitch-secondary" />
          <div>
            <p className="font-stitch-label-sm text-stitch-label-sm text-stitch-secondary-fixed-dim uppercase font-bold">
              Estimated Delivery
            </p>
            <p className="font-stitch-body-md text-stitch-body-md text-white">3-5 Business Days</p>
          </div>
        </div>

        {/* Total */}
        <div className="flex justify-between items-end mb-8 relative z-10">
          <span className="font-stitch-headline-lg-mobile text-stitch-headline-lg-mobile text-white">
            TOTAL
          </span>
          <div className="text-right">
            <span className="font-stitch-display-lg-mobile text-stitch-display-lg-mobile text-stitch-primary">
              {currencySymbol}
              {finalTotalAmount.toFixed(2)}
            </span>
          </div>
        </div>

        {/* Terms and Checkout */}
        <div className="space-y-6 relative z-10">
          <label className="flex items-start gap-3 cursor-pointer group">
            <input
              required
              className="mt-1 bg-stitch-surface-container-lowest border-stitch-outline-variant/50 text-stitch-primary focus:ring-stitch-primary rounded"
              type="checkbox"
            />
            <span className="font-stitch-label-sm text-stitch-label-sm text-stitch-outline leading-tight group-hover:text-white transition-colors">
              I AGREE TO THE{' '}
              <Link
                to="/legal/terms"
                target="_blank"
                className="text-stitch-primary hover:underline hover:text-stitch-secondary"
              >
                TERMS OF SERVICE
              </Link>{' '}
              AND{' '}
              <Link
                to="/legal/refund"
                target="_blank"
                className="text-stitch-primary hover:underline hover:text-stitch-secondary"
              >
                REFUND POLICY
              </Link>
              .
            </span>
          </label>

          <button
            type="submit"
            disabled={loading}
            className="w-full py-4 bg-stitch-primary text-stitch-on-primary font-stitch-cta-button text-stitch-cta-button rounded-xl flex items-center justify-center gap-2 hover:brightness-110 active:scale-95 transition-all shadow-[0_0_20px_rgba(173,198,255,0.3)] disabled:opacity-50"
          >
            {loading ? (
              <Loader2 className="animate-spin w-5 h-5" />
            ) : (
              <Lock className="w-5 h-5 fill-current" />
            )}
            {paymentMethod === 'cod' ? 'PLACE ORDER' : 'CONTINUE TO SECURE PAYMENT'}
          </button>
        </div>
      </div>

      {/* Secondary Trust Badge */}
      <div className="flex justify-center gap-8 py-4 opacity-50 grayscale hover:opacity-100 hover:grayscale-0 transition-all text-white">
        <Shield className="w-10 h-10" />
        <CheckCircle className="w-10 h-10" />
        <Award className="w-10 h-10" />
      </div>
    </aside>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useCartStore } from '@byteevolvr/store';
import { ProductService, Product, MarketingService } from '@byteevolvr/api-client';
import {
  Loader2,
  ShoppingCart,
  Minus,
  Plus,
  Trash2,
  ArrowRight,
  ShieldCheck,
  Lock,
  ArrowLeft,
  Award,
} from 'lucide-react';

import { useStoreCurrency } from '@/features/shop/hooks/useStoreCurrency';

export function CartPage() {
  const navigate = useNavigate();
  const {
    items,
    removeItem,
    updateQuantity,
    totalAmount,
    addItem,
    appliedDiscount,
    setAppliedDiscount,
  } = useCartStore();
  const total = totalAmount();
  const currencySymbol = useStoreCurrency();

  const [relatedProducts, setRelatedProducts] = useState<Product[]>([]);

  const [couponCode, setCouponCode] = useState('');
  const [discountLoading, setDiscountLoading] = useState(false); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [discountError, setDiscountError] = useState('');

  const handleApplyDiscount = async () => {
    if (!couponCode) return;
    setDiscountLoading(true);
    setDiscountError('');
    try {
      const res = await MarketingService.validateCoupon(couponCode, total);
      if (res.couponId && res.code) {
        setAppliedDiscount({
          code: res.code,
          discount: res.discount,
          couponId: res.couponId,
        });
        setCouponCode('');
      } else {
        setDiscountError(res.message || 'Invalid coupon');
      }
    } catch (err: any) {
      setDiscountError(
        err.customMessage || err.response?.data?.message || 'Failed to apply coupon'
      );
    } finally {
      setDiscountLoading(false);
    }
  };

  const handleRemoveDiscount = () => {
    setAppliedDiscount(null);
  };

  const finalTotalAmount = Math.max(0, total + total * 0.1 - (appliedDiscount?.discount || 0));

  useEffect(() => {
    if (items.length > 0) { // eslint-disable-line @typescript-eslint/no-floating-promises
      const fetchRelated = async () => {
        try {
          const allProducts = await ProductService.getProducts();
          const cartItemIds = items.map((item) => item.id);
          const cartProducts = allProducts.filter((p) => cartItemIds.includes(p.id!));
          const cartCategories = [...new Set(cartProducts.map((p) => p.category))];

          let related = allProducts.filter(
            (p) => cartCategories.includes(p.category) && !cartItemIds.includes(p.id!)
          );

          if (related.length === 0) {
            related = allProducts.filter((p) => !cartItemIds.includes(p.id!));
          }

          setRelatedProducts(related.slice(0, 4));
        } catch (error) {
          console.error('Failed to fetch related products:', error);
        }
      };
      fetchRelated();
    }
  }, [items]);

  if (items.length === 0) {
    return (
      <div className="flex h-[calc(100vh-160px)] flex-col items-center justify-center space-y-4">
        <ShoppingCart className="w-16 h-16 text-stitch-outline" />
        <h2 className="text-2xl font-bold text-white">Your Crate is Empty</h2>
        <p className="text-stitch-on-surface-variant">Looks like you haven't added any gear yet.</p>
        <Link
          to="/shop"
          className="mt-4 bg-stitch-primary text-stitch-on-primary px-8 py-3 rounded-full font-stitch-cta-button hover:brightness-110 transition-all uppercase"
        >
          Explore Shop
        </Link>
      </div>
    );
  }

  return (
    <main className="flex-grow pt-24 pb-stitch-section-gap px-stitch-container-padding-mobile md:px-stitch-container-padding-desktop max-w-7xl mx-auto w-full min-h-[calc(100vh-160px)]">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-stitch-gutter items-start">
        {/* Shopping Cart Items (8 Cols) */}
        <div className="lg:col-span-8 space-y-stitch-gutter">
          <div className="flex items-baseline justify-between mb-4">
            <h2 className="font-stitch-headline-lg text-stitch-headline-lg text-white">
              YOUR_CRATE
            </h2>
            <span className="font-stitch-label-sm text-stitch-label-sm text-stitch-outline uppercase">
              [ {items.length < 10 ? `0${items.length}` : items.length} Items ]
            </span>
          </div>

          {items.map((item) => (
            <div
              key={item.id}
              className="stitch-glass-panel rounded-xl p-stitch-base md:p-6 flex flex-col md:flex-row gap-6 relative overflow-hidden group"
            >
              <div className="w-full md:w-48 h-48 bg-stitch-surface-container rounded-lg overflow-hidden flex-shrink-0 border border-stitch-outline-variant/10">
                <img
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                  src={item.image_url || 'https://via.placeholder.com/150'}
                  alt={item.name}
                />
              </div>
              <div className="flex-grow flex flex-col justify-between">
                <div>
                  <div className="flex justify-between items-start">
                    <h3 className="font-stitch-headline-lg-mobile text-stitch-headline-lg-mobile text-stitch-primary">
                      {item.name}
                    </h3>
                    <p className="font-stitch-label-sm text-stitch-headline-lg-mobile text-white">
                      {currencySymbol}
                      {(item.price * item.quantity).toFixed(2)}
                    </p>
                  </div>
                  <p className="font-stitch-body-md text-stitch-on-surface-variant mt-2 line-clamp-2">
                    Premium Tech Gear
                  </p>
                  <div className="mt-4 flex items-center gap-2">
                    <span
                      className="w-2 h-2 rounded-full bg-stitch-secondary animate-pulse"
                      style={{ animationDuration: '2s' }}
                    ></span>
                    <span className="font-stitch-label-sm text-stitch-secondary uppercase">
                      In Stock &amp; Ready for Dispatch
                    </span>
                  </div>
                </div>
                <div className="flex items-center justify-between mt-6">
                  <div className="flex items-center border border-stitch-outline-variant/30 rounded-full bg-stitch-surface-container-low px-2 py-1">
                    <button
                      onClick={() => updateQuantity(item.id, Math.max(0, item.quantity - 1))}
                      className="p-2 text-stitch-outline hover:text-stitch-primary transition-colors"
                    >
                      <Minus className="w-4 h-4" />
                    </button>
                    <span className="px-4 font-stitch-label-sm text-white">
                      {item.quantity < 10 ? `0${item.quantity}` : item.quantity}
                    </span>
                    <button
                      onClick={() => updateQuantity(item.id, item.quantity + 1)}
                      className="p-2 text-stitch-outline hover:text-stitch-primary transition-colors"
                    >
                      <Plus className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="flex gap-4">
                    <button
                      onClick={() => removeItem(item.id)}
                      className="font-stitch-label-sm text-stitch-error hover:text-stitch-error/80 transition-colors uppercase tracking-widest flex items-center gap-1"
                    >
                      <Trash2 className="w-4 h-4" />
                      REMOVE
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ))}

          {/* You Might Also Like Carousel */}
          {relatedProducts.length > 0 && (
            <div className="pt-8">
              <h3 className="font-stitch-label-sm text-stitch-label-sm text-stitch-on-surface-variant mb-4 tracking-widest uppercase">
                SYNERGIZE_YOUR_SETUP
              </h3>
              <div className="flex gap-stitch-gutter overflow-x-auto pb-4 stitch-no-scrollbar">
                {relatedProducts.map((product) => (
                  <div
                    key={product.id}
                    className="min-w-[200px] stitch-glass-panel rounded-xl p-4 group flex flex-col justify-between"
                  >
                    <Link
                      to={`/shop/product/${product.id}`}
                      className="block h-32 bg-stitch-surface rounded mb-3 overflow-hidden cursor-pointer"
                    >
                      <img
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                        src={product.image_url || 'https://via.placeholder.com/200'}
                        alt={product.name}
                      />
                    </Link>
                    <div>
                      <Link
                        to={`/shop/product/${product.id}`}
                        className="font-stitch-label-sm text-white text-xs truncate block hover:text-stitch-primary transition-colors"
                      >
                        {product.name}
                      </Link>
                      <p className="font-stitch-label-sm text-stitch-secondary text-xs mt-1 mb-3">
                        {currencySymbol}
                        {product.price.toFixed(2)}
                      </p>
                      <button
                        onClick={() => addItem(product)}
                        className="w-full py-2 bg-white/5 hover:bg-white/10 text-white text-xs rounded transition-colors flex items-center justify-center gap-2"
                      >
                        <Plus className="w-3 h-3" /> ADD
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Summary Sidebar (4 Cols) */}
        <div className="lg:col-span-4 lg:sticky lg:top-24 space-y-stitch-gutter">
          <div className="stitch-glass-panel rounded-xl p-6 border-stitch-primary/20 bg-stitch-surface-container-high/60">
            <h3 className="font-stitch-headline-lg-mobile text-stitch-headline-lg-mobile text-white mb-6 uppercase">
              ORDER_MANIFEST
            </h3>

            <div className="space-y-4 mb-6">
              <div className="flex justify-between font-stitch-body-md text-stitch-on-surface-variant">
                <span>Subtotal</span>
                <span>
                  {currencySymbol}
                  {total.toFixed(2)}
                </span>
              </div>
              <div className="flex justify-between font-stitch-body-md text-stitch-on-surface-variant">
                <span>Shipping</span>
                <span className="text-stitch-secondary">FREE</span>
              </div>
              <div className="flex justify-between font-stitch-body-md text-stitch-on-surface-variant">
                <span>Tax (Calculated)</span>
                <span>
                  {currencySymbol}
                  {(total * 0.1).toFixed(2)}
                </span>
              </div>
            </div>

            <div className="border-t border-stitch-outline-variant/30 pt-6 mb-8">
              {appliedDiscount && (
                <div className="flex justify-between items-baseline mb-4">
                  <span className="font-stitch-body-md text-stitch-primary">Discount</span>
                  <span className="font-stitch-body-md text-stitch-primary">
                    -{currencySymbol}
                    {appliedDiscount.discount.toFixed(2)}
                  </span>
                </div>
              )}
              <div className="flex justify-between items-baseline">
                <span className="font-stitch-headline-lg-mobile text-white">TOTAL</span>
                <span className="font-stitch-display-lg-mobile text-stitch-display-lg-mobile text-stitch-primary">
                  {currencySymbol}
                  {finalTotalAmount.toFixed(2)}
                </span>
              </div>
            </div>

            {/* Coupon Input */}
            <div className="mb-8">
              {!appliedDiscount ? (
                <div className="space-y-2">
                  <div className="relative flex items-center bg-stitch-surface-container-lowest border border-stitch-outline-variant/30 rounded-lg p-1 transition-all focus-within:border-stitch-primary focus-within:shadow-[0_0_15px_rgba(173,198,255,0.3)]">
                    <input
                      className="bg-transparent border-none focus:ring-0 font-stitch-label-sm text-stitch-label-sm w-full px-4 text-white placeholder:text-stitch-outline/50 uppercase"
                      placeholder="COUPON_CODE"
                      type="text"
                      value={couponCode}
                      onChange={(e) => setCouponCode(e.target.value)}
                    />
                    <button
                      onClick={handleApplyDiscount}
                      disabled={discountLoading || !couponCode}
                      className="bg-stitch-surface-variant text-white font-stitch-label-sm text-stitch-label-sm px-4 py-2 rounded-md hover:bg-stitch-outline-variant transition-colors disabled:opacity-50"
                    >
                      {discountLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'APPLY'}
                    </button>
                  </div>
                  {discountError && <p className="text-stitch-error text-xs">{discountError}</p>}
                </div>
              ) : (
                <div className="flex justify-between items-center bg-stitch-primary/10 border border-stitch-primary/30 rounded p-3">
                  <div className="flex flex-col">
                    <span className="text-stitch-primary font-bold flex items-center gap-2">
                      <Award className="w-4 h-4" /> {appliedDiscount.code}
                    </span>
                    <button
                      type="button"
                      onClick={handleRemoveDiscount}
                      className="text-xs text-stitch-outline hover:text-white text-left mt-1 underline"
                    >
                      Remove
                    </button>
                  </div>
                  <span className="text-stitch-primary font-bold">
                    -{currencySymbol}
                    {appliedDiscount.discount.toFixed(2)}
                  </span>
                </div>
              )}
            </div>

            {/* Checkout CTA */}
            <button
              onClick={() => navigate('/shop/checkout')}
              className="w-full bg-stitch-primary-container text-stitch-on-primary-container font-stitch-cta-button text-stitch-cta-button py-4 rounded-xl flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(77,142,255,0.4)] hover:shadow-[0_0_30px_rgba(77,142,255,0.6)] transition-all active:scale-[0.98] uppercase"
            >
              PROCEED TO CHECKOUT
              <ArrowRight className="w-6 h-6" />
            </button>

            {/* Trust Badges */}
            <div className="mt-8 flex justify-center items-center gap-6">
              <div className="flex flex-col items-center gap-1 opacity-60">
                <ShieldCheck className="w-6 h-6 text-stitch-secondary" />
                <span className="font-stitch-label-sm text-[10px] uppercase text-white">
                  Secure Tx
                </span>
              </div>
              <div className="w-px h-8 bg-stitch-outline-variant/30"></div>
              <div className="flex flex-col items-center gap-1 opacity-60">
                <Lock className="w-6 h-6 text-stitch-secondary" />
                <span className="font-stitch-label-sm text-[10px] uppercase text-white">
                  Encrypted
                </span>
              </div>
            </div>
          </div>

          {/* Back to Shopping */}
          <Link
            to="/shop"
            className="flex items-center justify-center gap-2 font-stitch-label-sm text-stitch-outline hover:text-stitch-primary transition-colors group uppercase tracking-widest mt-4"
          >
            <ArrowLeft className="w-6 h-6 group-hover:-translate-x-1 transition-transform" />
            CONTINUE EXPLORING
          </Link>
        </div>
      </div>
    </main>
  );
}

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ProductService, Product } from '@byteevolvr/api-client';
import { useCartStore } from '@byteevolvr/store';
import {
  Loader2,
  LayoutGrid,
  List,
  SlidersHorizontal,
  ChevronDown,
  Heart,
  Star,
  Plus,
  Check,
} from 'lucide-react';

import { useStoreCurrency } from '@/features/shop/hooks/useStoreCurrency';
export function CategoryPage() {
  const { id } = useParams<{ id: string }>();
  const { addItem } = useCartStore();
  const currencySymbol = useStoreCurrency();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        setLoading(true);
        // Fetch products; ideally filter by category (id)
        const data = await ProductService.getProducts();
        // Since we don't have categories in dummy API, let's just use all
        setProducts(data);
      } catch (err) {
        console.error('Failed to fetch products', err);
      } finally {
        setLoading(false);
      }
    };
    fetchProducts(); // eslint-disable-line @typescript-eslint/no-floating-promises
  }, [id]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      const x = (e.clientX / window.innerWidth) * 100;
      const y = (e.clientY / window.innerHeight) * 100;
      document.body.style.backgroundImage = `radial-gradient(circle at ${x}% ${y}%, rgba(173, 198, 255, 0.05) 0%, transparent 50%)`;
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="flex w-full">
      {/* Sidebar (Desktop Filters) */}
      <aside className="hidden md:block sticky top-0 left-0 w-80 h-screen pt-24 pb-8 border-r border-stitch-outline-variant/30 bg-stitch-surface/80 backdrop-blur-xl px-8 overflow-y-auto stitch-no-scrollbar">
        <h2 className="font-stitch-headline-lg text-stitch-headline-lg-mobile uppercase text-stitch-primary mb-8">
          Filters
        </h2>
        <div className="space-y-10">
          <section>
            <h3 className="font-stitch-label-sm text-stitch-label-sm text-stitch-outline uppercase mb-4">
              Brand
            </h3>
            <div className="space-y-4">
              <label className="flex items-center gap-3 cursor-pointer group">
                <div className="w-5 h-5 rounded border border-stitch-outline-variant bg-stitch-surface-container-high flex items-center justify-center group-hover:border-stitch-primary transition-colors">
                  {/* Unchecked state */}
