import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCartStore, useAuthStore } from '@byteevolvr/store';
import { OrderService, ShippingService, UserService, PaymentService } from '@byteevolvr/api-client';

declare global {
  interface Window {
    Razorpay: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  }
}

import { CheckoutProgressIndicator } from '../components/checkout/CheckoutProgressIndicator';
import { CheckoutShippingForm } from '../components/checkout/CheckoutShippingForm';
import { CheckoutPaymentMethod } from '../components/checkout/CheckoutPaymentMethod';
import { CheckoutOrderSummary } from '../components/checkout/CheckoutOrderSummary';

import { useStoreCurrency } from '@/features/shop/hooks/useStoreCurrency';

export function CheckoutPage() {
  const { items, clearCart, totalAmount, appliedDiscount, setAppliedDiscount } = useCartStore();
  const { user } = useAuthStore();
  const navigate = useNavigate();
  const currencySymbol = useStoreCurrency();

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [paymentMethod, setPaymentMethod] = useState<'razorpay' | 'cod'>('cod');
  const [shippingAddress, setShippingAddress] = useState({
    full_name: user?.full_name || '',
    phone: '',
    line_1: '',
    city: '',
    state: '',
    postal_code: '',
  });

  const [guestEmail, setGuestEmail] = useState('');
  const [guestPassword, setGuestPassword] = useState('');

  const subtotal = totalAmount();

  const [shippingRates, setShippingRates] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [selectedRate, setSelectedRate] = useState<number>(0);
  const [calculatingShipping, setCalculatingShipping] = useState(false);

  const [couponCode, setCouponCode] = useState('');
  const [discountLoading, setDiscountLoading] = useState(false);
  const [discountError, setDiscountError] = useState('');

  React.useEffect(() => {
    const fetchRates = async () => {
      if (shippingAddress.postal_code.length === 6) {
        setCalculatingShipping(true);
        try {
          const data = await ShippingService.calculateShippingRates({
            pincode: shippingAddress.postal_code,
            weight: 1, // Default weight
            subtotal,
          });

          if (data.rates && data.rates.length > 0) {
            setShippingRates(data.rates);
            // Default to cheapest rate
            const cheapest = data.rates.reduce(
              (min: any, r: any) => (r.rate < min.rate ? r : min), // eslint-disable-line @typescript-eslint/no-explicit-any
              data.rates[0]
            );
            setSelectedRate(cheapest.rate);
          } else if (data.data?.available_courier_companies) {
            // Shiprocket format
            const rates = data.data.available_courier_companies.map((c: any) => ({ // eslint-disable-line @typescript-eslint/no-explicit-any
              courier_name: c.courier_name,
              rate: Number(c.rate),
              estimated_delivery_days: c.estimated_delivery_days,
            }));
            setShippingRates(rates);
            setSelectedRate(rates[0]?.rate || 0);
          }
        } catch (err) {
          console.error('Failed to fetch shipping rates', err);
        } finally {
          setCalculatingShipping(false);
        }
      } else {
        setShippingRates([]);
        setSelectedRate(0);
      }
    };

    void fetchRates();
  }, [shippingAddress.postal_code, subtotal]);

  React.useEffect(() => {
    async function fetchLatestAddress() {
      if (!user) return;
      try {
        const response = await UserService.getAddresses();
        const data = response.data?.[0];

        if (data) {
          setShippingAddress((prev) => ({
            ...prev,
            full_name: data.full_name || prev.full_name,
            phone: data.phone || prev.phone,
            line_1: data.line_1 || prev.line_1,
            city: data.city || prev.city,
            state: data.state || prev.state,
            postal_code: data.postal_code || prev.postal_code,
          }));
        }
      } catch (err) {
        console.error('Failed to fetch latest address', err);
      }
    }
    void fetchLatestAddress();
  }, [user]);

  const tax = subtotal * 0.18; // 18% GST
  const shipping = selectedRate;
  const discountAmount = appliedDiscount?.discount || 0;
  const finalTotalAmount = Math.max(0, subtotal + tax + shipping - discountAmount);

  // Redirect if cart is empty
  if (items.length === 0 && !loading) {
    navigate('/shop/cart'); // eslint-disable-line @typescript-eslint/no-floating-promises
    return null;
  }

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setShippingAddress((prev) => ({ ...prev, [name]: value }));
  };

  const loadRazorpayScript = () => {
    return new Promise((resolve) => {
      if (window.Razorpay) {
        resolve(true);
        return;
      }
      const script = document.createElement('script');
      script.src = 'https://checkout.razorpay.com/v1/checkout.js';
      script.onload = () => resolve(true);
      script.onerror = () => resolve(false);
      document.body.appendChild(script);
    });
  };

  const handlePlaceOrder = async (e: React.FormEvent) => {
    e.preventDefault();

    setLoading(true);
    setError('');

    try {
      const payload = {
        userId: user?.id,
        email: !user ? guestEmail : undefined,
        password: !user ? guestPassword : undefined,
        items: items.map((item) => ({
          productId: item.id!,
          name: item.name,
          sku: item.sku,
          quantity: item.quantity,
          price: item.price,
        })),
        shippingAddress,
        paymentMethod,
        shippingFee: selectedRate,
        discountAmount: appliedDiscount?.discount || 0,
        couponCode: appliedDiscount?.code,
        couponId: appliedDiscount?.couponId,
        totalAmount: finalTotalAmount,
      };

      if (paymentMethod === 'razorpay') {
        const scriptLoaded = await loadRazorpayScript();
        if (!scriptLoaded) {
          throw new Error('Razorpay SDK failed to load. Are you online?');
        }

        // Generate Razorpay Order
        const rzpOrderData = await PaymentService.createRazorpayOrder({
          items: payload.items,
          receipt: `rcpt_${Date.now()}`,
          shippingFee: selectedRate,
          discountAmount: appliedDiscount?.discount || 0,
        });

        if (!rzpOrderData || !rzpOrderData.order) {
          throw new Error('Failed to create Razorpay order');
        }

        const options = {
          key: rzpOrderData.key,
          amount: rzpOrderData.order.amount,
          currency: rzpOrderData.order.currency,
          name: 'ByteEvolvr',
          description: 'Order Checkout',
          order_id: rzpOrderData.order.id,
          handler: async function (response: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
            try {
              const verified = await PaymentService.verifyRazorpayPayment({
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
              });

              if (verified?.verified) {
                // Now create the actual order in our system
                await OrderService.createOrder({
                  ...payload,
                  status: 'confirmed',
                });
                clearCart();
                navigate('/shop/order-success'); // eslint-disable-line @typescript-eslint/no-floating-promises
              } else {
                throw new Error('Payment verification failed');
              }
            } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
              console.error('Payment verification error', err);
              setError(
                'Payment verification failed. Please contact support if amount was deducted.'
              );
              setLoading(false);
            }
          },
          prefill: {
            name: shippingAddress.full_name,
            email: user?.email || guestEmail,
            contact: shippingAddress.phone,
          },
          theme: {
            color: '#0f172a',
          },
          modal: {
            ondismiss: function () {
              setLoading(false);
            },
          },
        };
 // eslint-disable-line @typescript-eslint/no-explicit-any
        const rzp = new window.Razorpay(options);
        rzp.on('payment.failed', function (response: any) {
          setError(`Payment failed: ${response.error.description}`);
          setLoading(false);
        });
        rzp.open();
      } else {
        // COD logic
        await OrderService.createOrder(payload);
        clearCart(); // eslint-disable-line @typescript-eslint/no-floating-promises
        navigate('/shop/order-success');
      }
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      console.error('Order creation failed:', err);
      setError(
        err.response?.data?.message || err.message || 'Failed to place order. Please try again.'
      );
      setLoading(false);
    }
  };

  return (
    <div className="w-full">
      <main className="pt-24 pb-stitch-section-gap px-stitch-container-padding-mobile md:px-stitch-container-padding-desktop max-w-7xl mx-auto w-full min-h-[calc(100vh-160px)]">
        <CheckoutProgressIndicator />

        {error && (
          <div className="mb-6 p-4 rounded-xl bg-stitch-error/10 border border-stitch-error/20 text-stitch-error text-sm">
            {error}
          </div>
        )}

        <form
          id="checkout-form"
          onSubmit={(e) => void handlePlaceOrder(e)}
          className="grid grid-cols-1 lg:grid-cols-12 gap-stitch-gutter items-start"
        >
          {/* Left Column: Checkout Forms */}
          <section className="lg:col-span-8 space-y-stitch-gutter">
            <CheckoutShippingForm
              user={user}
              guestEmail={guestEmail}
              setGuestEmail={setGuestEmail}
              guestPassword={guestPassword}
              setGuestPassword={setGuestPassword}
              shippingAddress={shippingAddress}
              handleInputChange={handleInputChange}
            />

            <CheckoutPaymentMethod
              paymentMethod={paymentMethod}
              setPaymentMethod={setPaymentMethod}
            />
          </section>

          {/* Right Column: Order Summary Sidebar */}
          <CheckoutOrderSummary
            items={items}
            currencySymbol={currencySymbol}
            subtotal={subtotal}
            tax={tax}
            shipping={shipping}
            shippingRates={shippingRates}
            selectedRate={selectedRate}
            setSelectedRate={setSelectedRate}
            calculatingShipping={calculatingShipping}
            finalTotalAmount={finalTotalAmount}
            loading={loading}
            paymentMethod={paymentMethod}
            couponCode={couponCode}
            setCouponCode={setCouponCode}
            appliedDiscount={appliedDiscount}
            setAppliedDiscount={setAppliedDiscount}
            discountLoading={discountLoading}
            setDiscountLoading={setDiscountLoading}
            discountError={discountError}
            setDiscountError={setDiscountError}
            subtotalForDiscount={subtotal}
          />
        </form>
      </main>
    </div>
  );
}

import React, { useEffect, useState, useCallback } from 'react';
import { useAuthStore } from '@byteevolvr/store';
import { UserService, OrderService, SocketService, CMSService } from '@byteevolvr/api-client';
import { Card, Badge, Button } from '@byteevolvr/ui';
import {
  Package,
  MapPin,
  LogOut,
  Edit2,
  Save,
  Plus,
  Trash2,
  Phone,
  X,
  Printer,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { printInvoice } from '@byteevolvr/ui';

import { useStoreCurrency } from '@/features/shop/hooks/useStoreCurrency';

const inputStyle: React.CSSProperties = {
  width: '100%',
  padding: '10px 14px',
  borderRadius: 10,
  background: 'rgba(255,255,255,0.05)',
  border: '1px solid rgba(255,255,255,0.1)',
  color: '#fff',
  fontSize: 14,
  outline: 'none',
  boxSizing: 'border-box',
};

const labelStyle: React.CSSProperties = {
  display: 'block',
  marginBottom: 6,
  fontSize: 12,
  color: '#8B9BB8',
  textTransform: 'uppercase',
  letterSpacing: '0.05em',
};

export function DashboardPage() {
  const { user, logout } = useAuthStore();
  const navigate = useNavigate();
  const currencySymbol = useStoreCurrency();
  const [orders, setOrders] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [addresses, setAddresses] = useState<any[]>([]); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [profile, setProfile] = useState<any>(null); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(true);

  // Profile edit state
  const [editingProfile, setEditingProfile] = useState(false);
  const [fullName, setFullName] = useState('');
  const [savingProfile, setSavingProfile] = useState(false);

  // Address form state
  const [showAddressForm, setShowAddressForm] = useState(false);
  const [editingAddress, setEditingAddress] = useState<any>(null); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [addressForm, setAddressForm] = useState({
    full_name: '',
    phone: '',
    line_1: '',
    line_2: '',
    city: '',
    state: '',
    postal_code: '',
    address_type: 'home',
    is_default: false,
  });
  const [savingAddress, setSavingAddress] = useState(false);

  const fetchData = useCallback(async (isSilent = false) => { // eslint-disable-line complexity
    if (!isSilent) setLoading(true);
    try {
      const results = await Promise.allSettled([
        UserService.getProfile(),
        OrderService.getOrders(),
        UserService.getAddresses(),
      ]);

      if (results[0].status === 'fulfilled' && results[0].value) {
        const profileData = results[0].value.data || results[0].value;
        setProfile(profileData);
        setFullName(profileData.full_name || '');
      }

      if (results[1].status === 'fulfilled' && results[1].value) {
        const ordersData = results[1].value.data || results[1].value;
        setOrders(Array.isArray(ordersData) ? ordersData : []);
      }

      if (results[2].status === 'fulfilled' && results[2].value) {
        const addressesData = results[2].value.data || results[2].value;
        setAddresses(Array.isArray(addressesData) ? addressesData : []);
      }
    } catch (error) {
      console.error('Failed to fetch dashboard data:', error);
      if (!isSilent) alert('Failed to connect to the server.');
    } finally {
      if (!isSilent) setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (user) {
      fetchData(); // eslint-disable-line react-hooks/set-state-in-effect // eslint-disable-line @typescript-eslint/no-floating-promises

      // Real-time updates via Socket.io
      const socket = SocketService.connect(user.id);

      socket.on('order_updated', (data: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
        console.log('[Socket] Order update received:', data); // eslint-disable-line no-console
        fetchData(true); // Silently refresh data // eslint-disable-line @typescript-eslint/no-floating-promises
      });

      return () => {
        SocketService.disconnect();
      };
    }
  }, [user, fetchData]);

  const handleSaveProfile = async () => {
    setSavingProfile(true);
    try {
      const updated = await UserService.updateProfile({ full_name: fullName });
      setProfile(updated);
      setEditingProfile(false);
    } catch (error) { // eslint-disable-line @typescript-eslint/no-unused-vars
      alert('Failed to update profile.');
    } finally {
      setSavingProfile(false);
    }
  };

  const openAddressForm = (addr?: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
    if (addr) {
      setEditingAddress(addr);
      setAddressForm({
        full_name: addr.full_name,
        phone: addr.phone,
        line_1: addr.line_1,
        line_2: addr.line_2 || '',
        city: addr.city,
        state: addr.state,
        postal_code: addr.postal_code,
        address_type: addr.address_type,
        is_default: addr.is_default,
      });
    } else {
      setEditingAddress(null);
      setAddressForm({
        full_name: profile?.full_name || '',
        phone: '',
        line_1: '',
        line_2: '',
        city: '',
        state: '',
        postal_code: '',
        address_type: 'home',
        is_default: addresses.length === 0,
      });
    }
    setShowAddressForm(true);
  };

  const handleSaveAddress = async (e: React.FormEvent) => {
    e.preventDefault();
    setSavingAddress(true);
    try {
      if (editingAddress) {
        await UserService.updateAddress(editingAddress.id, addressForm);
      } else {
        await UserService.addAddress(addressForm);
      }
      await fetchData();
      setShowAddressForm(false);
      setEditingAddress(null);
    } catch (error) { // eslint-disable-line @typescript-eslint/no-unused-vars
      alert('Failed to save address.');
    } finally {
      setSavingAddress(false);
    }
  };

  const handleDeleteAddress = async (id: string) => {
    if (!confirm('Delete this address?')) return;
    try {
      await UserService.deleteAddress(id);
      setAddresses(addresses.filter((a) => a.id !== id));
    } catch (error) { // eslint-disable-line @typescript-eslint/no-unused-vars
      alert('Failed to delete address.');
    }
  };

  const handleSignOut = () => {
    logout();
    navigate('/shop'); // eslint-disable-line @typescript-eslint/no-floating-promises
  };

  const handlePrintInvoice = async (order: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
    try {
      const response = await OrderService.getOrderItems(order.id);
      const items = response.data || [];
      const cmsData = await CMSService.getContent('global');
      printInvoice(order, items, cmsData);
    } catch (err) {
      console.error('Print failed:', err);
      alert('Could not generate invoice.');
    }
  };

  return (
    <div className="min-h-screen bg-[#04080F] text-white p-6 pt-32">
      <div className="mx-auto max-w-5xl">
        <div className="flex items-center justify-between mb-8">
          <h1 className="font-display text-3xl font-bold">My Account</h1>
          <Button
            variant="ghost"
            onClick={handleSignOut}
            className="border border-white/10 text-red-400 hover:bg-red-500/10 flex items-center gap-2"
          >
            <LogOut className="h-4 w-4" /> Sign Out
          </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* Left Sidebar */}
          <div className="space-y-6">
            {/* Profile Card */}
            <Card className="bg-[#070D1A] border border-white/10 p-6">
              <div className="flex items-center gap-4 mb-4">
                <div className="h-14 w-14 rounded-full bg-accent/20 flex items-center justify-center text-2xl font-bold text-accent">
                  {(fullName || user?.email || 'C')[0].toUpperCase()}
                </div>
                <div>
                  {editingProfile ? (
                    <input
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      style={{ ...inputStyle, padding: '6px 10px', fontSize: 15, fontWeight: 600 }}
                      placeholder="Your full name"
                      autoFocus
                    />
                  ) : (
                    <h3 className="font-bold text-lg">{profile?.full_name || 'Customer'}</h3>
                  )}
                  <p className="text-sm text-brand-muted">{user?.email}</p>
                </div>
              </div>

              {editingProfile ? (
                <div className="flex gap-2 mt-2">
                  <button
                    onClick={handleSaveProfile}
                    disabled={savingProfile}
                    style={{
                      flex: 1,
                      padding: '8px',
                      borderRadius: 8,
                      background: '#3b82f6',
                      color: '#fff',
                      border: 'none',
                      fontWeight: 600,
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: 6,
                    }}
                  >
                    <Save size={14} /> {savingProfile ? 'Saving...' : 'Save'}
                  </button>
                  <button
                    onClick={() => {
                      setEditingProfile(false);
                      setFullName(profile?.full_name || '');
                    }}
                    style={{
                      flex: 1,
                      padding: '8px',
                      borderRadius: 8,
                      background: 'rgba(255,255,255,0.05)',
                      color: '#fff',
                      border: '1px solid rgba(255,255,255,0.1)',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: 6,
                    }}
                  >
                    <X size={14} /> Cancel
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setEditingProfile(true)}
                  style={{
                    width: '100%',
                    marginTop: 8,
                    padding: '8px',
                    borderRadius: 8,
                    background: 'rgba(255,255,255,0.04)',
                    border: '1px solid rgba(255,255,255,0.1)',
                    color: '#ccc',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 6,
                  }}
                >
                  <Edit2 size={14} /> Edit Name
                </button>
              )}
            </Card>

            {/* Addresses Card */}
            <Card className="bg-[#070D1A] border border-white/10 p-6">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                  <MapPin className="text-brand-muted" size={18} />
                  <h3 className="font-bold">Addresses</h3>
                </div>
                <button
                  onClick={() => openAddressForm()}
                  style={{
                    padding: '4px 10px',
                    borderRadius: 6,
                    background: 'rgba(59,123,248,0.15)',
                    color: '#3b7bf8',
                    border: 'none',
                    cursor: 'pointer',
                    fontSize: 12,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 4,
                  }}
                >
                  <Plus size={12} /> Add
                </button>
              </div>
              {loading ? (
                <p className="text-sm text-brand-muted">Loading...</p>
              ) : addresses.length === 0 ? (
                <p className="text-sm text-brand-muted italic">No addresses saved yet.</p>
              ) : (
                <div className="space-y-3">
                  {addresses.map((addr) => (
                    <div
                      key={addr.id}
                      style={{
                        padding: 12,
                        borderRadius: 10,
                        background: 'rgba(255,255,255,0.02)',
                        border: '1px solid rgba(255,255,255,0.07)',
                      }}
                    >
                      <div className="flex justify-between items-start">
                        <div>
                          <p className="font-medium text-sm">
                            {addr.full_name}{' '}
                            {addr.is_default && (
                              <span
                                style={{
                                  fontSize: 10,
                                  background: 'rgba(59,123,248,0.2)',
                                  color: '#3b7bf8',
                                  padding: '1px 5px',
                                  borderRadius: 3,
                                }}
                              >
                                Default
                              </span>
                            )}
                          </p>
                          <p className="text-xs text-brand-muted">{addr.line_1}</p>
                          <p className="text-xs text-brand-muted">
                            {addr.city}, {addr.state} - {addr.postal_code}
                          </p>
                          <p className="text-xs text-brand-muted flex items-center gap-1 mt-1">
                            <Phone size={10} /> {addr.phone}
                          </p>
                        </div>
                        <div className="flex gap-1">
                          <button
                            onClick={() => openAddressForm(addr)}
                            style={{
                              padding: 4,
                              borderRadius: 6,
                              background: 'rgba(255,255,255,0.05)',
                              border: 'none',
                              color: '#ccc',
                              cursor: 'pointer',
                            }}
                          >
                            <Edit2 size={12} />
                          </button>
                          <button
                            onClick={() => handleDeleteAddress(addr.id)}
                            style={{
                              padding: 4,
                              borderRadius: 6,
                              background: 'rgba(255,75,75,0.1)',
                              border: 'none',
                              color: '#ff4b4b',
                              cursor: 'pointer',
                            }}
                          >
                            <Trash2 size={12} />
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </Card>
          </div>

          {/* Orders Section */}
          <div className="md:col-span-2 space-y-6">
            <h2 className="font-display text-2xl font-bold flex items-center gap-2">
              <Package /> Order History
            </h2>
            {loading ? (
              <p className="text-brand-muted">Loading orders...</p>
            ) : orders.length === 0 ? (
              <Card className="bg-[#070D1A] border border-white/10 p-8 text-center">
                <p className="text-brand-muted mb-4">You haven't placed any orders yet.</p>
                <Button variant="primary" onClick={() => navigate('/shop')}>
                  Start Shopping
                </Button>
              </Card>
            ) : (
              orders.map((order) => (
                <Card
                  key={order.id}
                  className="bg-[#070D1A] border border-white/10 p-6 flex flex-col gap-4"
                >
                  <div className="flex flex-wrap items-center justify-between border-b border-white/10 pb-4 gap-4">
                    <div>
                      <p className="text-sm text-brand-muted">Order #{order.order_number}</p>
                      <p className="text-xs text-brand-muted">
                        Placed on {new Date(order.created_at).toLocaleDateString()}
                      </p>
                    </div>
                    <div className="flex items-center gap-3">
                      <Badge variant={order.status === 'delivered' ? 'success' : 'primary'}>
                        {order.status.toUpperCase()}
                      </Badge>
                      <Button
                        variant="secondary"
                        size="sm"
                        onClick={() => handlePrintInvoice(order)}
                        className="flex items-center gap-2"
                      >
                        <Printer className="h-4 w-4" /> Invoice
                      </Button>
                      <Button
                        variant="secondary"
                        size="sm"
                        onClick={() => navigate(`/shop/track/${order.tracking_number || order.id}`)}
                      >
                        Track
                      </Button>
                    </div>
                  </div>
                  <div className="space-y-6">
                    {/* Real-time Order Timeline */}
                    <div className="py-4">
                      <div className="relative flex justify-between items-center w-full">
                        {/* Progress Bar Background */}
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-white/5 -translate-y-1/2 z-0" />

                        {/* Active Progress Line */}
                        <div
                          className="absolute top-1/2 left-0 h-0.5 bg-accent -translate-y-1/2 z-0 transition-all duration-500"
                          style={{
                            width:
                              order.status === 'pending'
                                ? '0%'
                                : order.status === 'confirmed'
                                  ? '33%'
                                  : order.status === 'shipped'
                                    ? '66%'
                                    : order.status === 'delivered'
                                      ? '100%'
                                      : '0%',
                          }}
                        />

                        {['pending', 'confirmed', 'shipped', 'delivered'].map((step, idx) => {
                          const steps = ['pending', 'confirmed', 'shipped', 'delivered'];
                          const currentIdx = steps.indexOf(order.status);
                          const isCompleted = idx <= currentIdx;
                          const isActive = idx === currentIdx;

                          return (
                            <div
                              key={step}
                              className="relative z-10 flex flex-col items-center gap-2"
                            >
                              <div
                                className={`w-3 h-3 rounded-full transition-all duration-300 ${
                                  isCompleted
                                    ? 'bg-accent shadow-[0_0_10px_rgba(59,123,248,0.5)]'
                                    : 'bg-white/10'
                                } ${isActive ? 'scale-125 ring-4 ring-accent/20' : ''}`}
                              />
                              <span
                                className={`text-[10px] font-bold uppercase tracking-wider ${
                                  isCompleted ? 'text-accent' : 'text-brand-muted'
                                }`}
                              >
                                {step}
                              </span>
                            </div>
                          );
                        })}
                      </div>
                    </div>

                    <div className="space-y-3">
                      {order.order_items?.map((item: any) => ( // eslint-disable-line @typescript-eslint/no-explicit-any
                        <div key={item.id} className="flex justify-between items-center text-sm">
                          <span className="text-brand-muted">
                            {item.quantity}x {item.product_name}
                          </span>
                          <div className="font-bold text-accent">
                            {currencySymbol}
                            {Number(item.total_price).toFixed(2)}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="flex justify-between items-center pt-4 border-t border-white/5 font-bold">
                    <span>Total Amount</span>
                    <span className="text-accent">
                      {currencySymbol}
                      {Number(order.total_amount).toFixed(2)}
                    </span>
                  </div>
                </Card>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Address Form Modal */}
      {showAddressForm && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: 'rgba(0,0,0,0.8)',
            backdropFilter: 'blur(12px)',
            display: 'flex',
            alignItems: 'center',
            justifySelf: 'center',
            zIndex: 1000,
            padding: 20,
          }}
        >
          <div
            style={{
              background: '#070D1A',
              border: '1px solid rgba(255,255,255,0.1)',
              borderRadius: 24,
              padding: 36,
              maxWidth: 520,
              width: '100%',
              maxHeight: '90vh',
              overflowY: 'auto',
              margin: 'auto',
            }}
          >
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                marginBottom: 28,
              }}
            >
              <h2 style={{ fontSize: 22, fontWeight: 700 }}>
                {editingAddress ? 'Edit Address' : 'Add New Address'}
              </h2>
              <button
                onClick={() => setShowAddressForm(false)}
                style={{
                  padding: 6,
                  borderRadius: 8,
                  background: 'rgba(255,255,255,0.05)',
                  border: 'none',
                  color: '#ccc',
                  cursor: 'pointer',
                }}
              >
                <X size={18} />
              </button>
            </div>
            <form
              onSubmit={handleSaveAddress}
              style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}
            >
              <div style={{ gridColumn: 'span 2' }}>
                <label style={labelStyle}>Full Name *</label>
                <input
                  required
                  style={inputStyle}
                  value={addressForm.full_name}
                  onChange={(e) => setAddressForm({ ...addressForm, full_name: e.target.value })}
                  placeholder="Recipient full name"
                />
              </div>
              <div style={{ gridColumn: 'span 2' }}>
                <label style={labelStyle}>Phone Number *</label>
                <input
                  required
                  style={inputStyle}
                  value={addressForm.phone}
                  onChange={(e) => setAddressForm({ ...addressForm, phone: e.target.value })}
                  placeholder="+91 XXXXX XXXXX"
                />
              </div>
              <div style={{ gridColumn: 'span 2' }}>
                <label style={labelStyle}>Address Line 1 *</label>
                <input
                  required
                  style={inputStyle}
                  value={addressForm.line_1}
                  onChange={(e) => setAddressForm({ ...addressForm, line_1: e.target.value })}
                  placeholder="House/Flat no., Street name"
                />
              </div>
              <div style={{ gridColumn: 'span 2' }}>
                <label style={labelStyle}>Address Line 2</label>
                <input
                  style={inputStyle}
                  value={addressForm.line_2}
                  onChange={(e) => setAddressForm({ ...addressForm, line_2: e.target.value })}
                  placeholder="Landmark, Area (optional)"
                />
              </div>
              <div>
                <label style={labelStyle}>City *</label>
                <input
                  required
                  style={inputStyle}
                  value={addressForm.city}
                  onChange={(e) => setAddressForm({ ...addressForm, city: e.target.value })}
                  placeholder="City"
                />
              </div>
              <div>
                <label style={labelStyle}>State *</label>
                <input
                  required
                  style={inputStyle}
                  value={addressForm.state}
                  onChange={(e) => setAddressForm({ ...addressForm, state: e.target.value })}
                  placeholder="State"
                />
              </div>
              <div>
                <label style={labelStyle}>Pincode *</label>
                <input
                  required
                  style={inputStyle}
                  value={addressForm.postal_code}
                  onChange={(e) => setAddressForm({ ...addressForm, postal_code: e.target.value })}
                  placeholder="400001"
                />
              </div>
              <div>
                <label style={labelStyle}>Type</label>
                <select
                  style={{ ...inputStyle }}
                  value={addressForm.address_type}
                  onChange={(e) => setAddressForm({ ...addressForm, address_type: e.target.value })}
                >
                  <option value="home">Home</option>
                  <option value="work">Work</option>
                  <option value="other">Other</option>
                </select>
              </div>
              <div style={{ gridColumn: 'span 2', display: 'flex', alignItems: 'center', gap: 10 }}>
                <input
                  type="checkbox"
                  id="default-addr"
                  checked={addressForm.is_default}
                  onChange={(e) => setAddressForm({ ...addressForm, is_default: e.target.checked })}
                />
                <label
                  htmlFor="default-addr"
                  style={{ fontSize: 14, color: '#ccc', cursor: 'pointer' }}
                >
                  Set as default address
                </label>
              </div>
              <div style={{ gridColumn: 'span 2', display: 'flex', gap: 12, marginTop: 8 }}>
                <button
                  type="submit"
                  disabled={savingAddress}
                  style={{
                    flex: 1,
                    padding: '12px',
                    borderRadius: 10,
                    background: '#3b82f6',
                    color: '#fff',
                    border: 'none',
                    fontWeight: 600,
                    cursor: 'pointer',
                    fontSize: 15,
                  }}
                >
                  {savingAddress ? 'Saving...' : 'Save Address'}
                </button>
                <button
                  type="button"
                  onClick={() => setShowAddressForm(false)}
                  style={{
                    flex: 1,
                    padding: '12px',
                    borderRadius: 10,
                    background: 'rgba(255,255,255,0.05)',
                    color: '#fff',
                    border: '1px solid rgba(255,255,255,0.1)',
                    fontWeight: 600,
                    cursor: 'pointer',
                    fontSize: 15,
                  }}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { AuthService } from '@byteevolvr/api-client';
import { useAuthStore } from '@byteevolvr/store';
import { Button } from '@byteevolvr/ui';
import { Loader2, Mail, Lock, ArrowRight } from 'lucide-react';

export function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const { setToken, setUser } = useAuthStore();

  const from = location.state?.from?.pathname || '/shop/dashboard';

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const { user, token } = await AuthService.login(email, password);
      setToken(token, 'auth');
      setUser(user);
      navigate(from, { replace: true }); // eslint-disable-line @typescript-eslint/no-floating-promises
    } catch (signInError: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      const error = signInError as any; // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(error.customMessage || error.message || 'An unexpected error occurred');
      setLoading(false);
    }
  };

  return (
    <div className="relative flex min-h-screen items-center justify-center p-6 pt-32 overflow-hidden bg-[#020617]">
      {/* Dynamic Background Effects */}
      <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-accent/20 rounded-full mix-blend-screen filter blur-[100px] animate-pulse z-0"></div>
      <div
        className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-primary/20 rounded-full mix-blend-screen filter blur-[120px] animate-pulse z-0"
        style={{ animationDelay: '2s' }}
      ></div>
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 brightness-100 contrast-150 z-0 pointer-events-none"></div>

      <div className="relative z-10 w-full max-w-md overflow-hidden rounded-2xl bg-white/5 p-10 shadow-2xl backdrop-blur-xl border border-white/10 transition-all hover:border-white/20">
        <div className="mb-10 text-center">
          <div className="inline-flex h-16 w-16 items-center justify-center rounded-full bg-gradient-to-tr from-accent/20 to-primary/20 mb-4 ring-1 ring-white/10 shadow-inner">
            <Lock className="h-8 w-8 text-accent" />
          </div>
          <h1 className="font-display text-4xl font-bold tracking-tight text-white mb-2">
            Welcome Back
          </h1>
          <p className="text-brand-muted font-medium">Log in to continue shopping</p>
        </div>

        {error && (
          <div className="mb-6 flex items-center rounded-xl bg-red-500/10 p-4 text-sm text-red-400 border border-red-500/20 shadow-sm animate-in fade-in slide-in-from-top-2">
            <div className="h-1.5 w-1.5 rounded-full bg-red-400 mr-3 shrink-0"></div>
            {error}
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-5">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-brand-muted ml-1">Email Address</label>
            <div className="relative group">
              <Mail className="absolute left-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-white/40 transition-colors group-focus-within:text-accent" />
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="w-full rounded-xl border border-white/10 bg-white/5 py-3 pl-11 pr-4 text-white placeholder-white/20 outline-none backdrop-blur-sm transition-all focus:border-accent focus:bg-white/10 focus:ring-1 focus:ring-accent"
                placeholder="you@example.com"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <div className="flex justify-between items-center ml-1">
              <label className="text-sm font-medium text-brand-muted">Password</label>
              <a
                href="#"
                className="text-xs font-semibold text-accent hover:text-accent-light transition-colors"
              >
                Forgot password?
              </a>
            </div>
            <div className="relative group">
              <Lock className="absolute left-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-white/40 transition-colors group-focus-within:text-accent" />
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="w-full rounded-xl border border-white/10 bg-white/5 py-3 pl-11 pr-4 text-white placeholder-white/20 outline-none backdrop-blur-sm transition-all focus:border-accent focus:bg-white/10 focus:ring-1 focus:ring-accent"
                placeholder="••••••••"
              />
            </div>
          </div>

          <Button
            type="submit"
            className="group relative w-full overflow-hidden rounded-xl bg-white text-black hover:bg-gray-100 py-6 font-bold tracking-wide transition-all hover:scale-[1.02] active:scale-[0.98]"
            disabled={loading}
