import { useState, useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import { ShippingService } from '@byteevolvr/api-client';
import { Button, Input, Card, Badge } from '@byteevolvr/ui';
import { Loader2, PackageSearch } from 'lucide-react';

export function TrackingPage() {
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const initialId = id || searchParams.get('id') || '';

  const [trackingId, setTrackingId] = useState(initialId);
  const [result, setResult] = useState<any>(null); // eslint-disable-line @typescript-eslint/no-explicit-any
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const fetchTracking = async (idToFetch: string) => {
    if (!idToFetch) return;
    setLoading(true);
    setError('');

    try {
      const data = await ShippingService.getTrackingById(idToFetch);
      setResult(data);
    } catch (err: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setError(err.customMessage || 'Failed to fetch tracking details');
      setResult(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (initialId) {
      fetchTracking(initialId); // eslint-disable-line react-hooks/set-state-in-effect // eslint-disable-line @typescript-eslint/no-floating-promises
    }
  }, [initialId]);

  return (
    <div className="min-h-screen bg-[#04080F] text-white p-6 flex flex-col items-center">
      <div className="w-full max-w-3xl mt-12">
        <div className="text-center mb-10">
          <PackageSearch className="mx-auto h-12 w-12 text-accent mb-4" />
          <h1 className="font-display text-4xl font-bold mb-2">Track Your Order</h1>
          <p className="text-brand-muted">
            Enter your tracking ID to see the real-time status of your shipment.
          </p>
        </div>

        <div className="flex gap-4 mb-12">
          <div className="flex-1">
            <Input
              value={trackingId}
              onChange={(e) => setTrackingId(e.target.value)}
              placeholder="e.g. TRK-ABC-123"
            />
          </div>
          <Button variant="primary" onClick={() => fetchTracking(trackingId)} disabled={loading}>
            {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'Track Status'}
          </Button>
        </div>

        {error && (
          <div className="mb-6 rounded-lg bg-red-500/10 p-4 text-center text-red-500 border border-red-500/20">
            {error}
          </div>
        )}

        {result && (
          <div className="space-y-6">
            <Card className="bg-[#070D1A] border border-white/10 p-8">
              <div className="flex justify-between items-center mb-8 border-b border-white/10 pb-6">
                <div>
                  <div className="text-sm text-brand-muted uppercase tracking-widest mb-1">
                    Current Status
                  </div>
                  <div className="text-3xl font-bold text-accent">{result.status}</div>
                </div>
                <Badge variant="primary">{result.courierName}</Badge>
              </div>

              <div className="relative pl-8">
                {/* Timeline Line */}
                <div className="absolute left-[7px] top-2 bottom-2 w-0.5 bg-white/10" />

                <div className="space-y-8">
                  {result.events.map((event: any, i: number) => ( // eslint-disable-line @typescript-eslint/no-explicit-any
                    <div key={i} className="relative z-10">
                      {/* Timeline Dot */}
                      <div
                        className={`absolute -left-[31px] top-1 h-4 w-4 rounded-full border-2 ${
                          i === 0
                            ? 'bg-accent border-accent shadow-[0_0_10px_rgba(59,130,246,0.5)]'
                            : 'bg-[#04080F] border-white/20'
                        }`}
                      />

                      <div
                        className={`font-semibold text-lg ${i === 0 ? 'text-white' : 'text-white/60'}`}
                      >
                        {event.status}
                      </div>
                      <div className="text-sm text-brand-muted mt-1">{event.description}</div>
                      <div className="text-xs text-white/40 mt-2">{event.timestamp}</div>
                    </div>
                  ))}
                </div>
              </div>
            </Card>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Send, Phone, Mail, MapPin, Clock, Loader2, CheckCircle2 } from 'lucide-react';
import { MarketingService } from '@byteevolvr/api-client';

import { PageSeo } from '@/components/seo/PageSeo';
import { useCMS } from '@/features/cms/useCMS';

export function ContactPage() { // eslint-disable-line complexity
  const { data: contactPageCms } = useCMS('contact_page');
  const { data: globalCms } = useCMS('global');

  const contactPageDetails = contactPageCms?.details || {};
  const globalContact = globalCms?.contact || {};

  const contactData = {
    address:
      contactPageDetails.address ||
      globalContact.address ||
      'Chaltakonda, Routhkhanda, Near Kali Mata Mandir, Joypur, Bankura, West Bengal',
    pincode: contactPageDetails.pincode || globalContact.pincode || '722138',
    phone: contactPageDetails.phone || globalContact.phone || '+91 78889 57575',
    email: contactPageDetails.email || globalContact.email || 'hello@byteevolvr.com',
    workingHours:
      contactPageDetails.workingHours || globalContact.workingHours || 'Mon-Sat: 9:00 AM - 7:00 PM',
    mapUrl: contactPageDetails.mapUrl || globalContact.mapUrl || '',
  };

  const details = contactData;

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    subject: '',
    message: '',
  });
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('loading');

    try {
      const data = await MarketingService.submitLead(formData);
      setStatus('success');
      setMessage(data.message || 'Inquiry sent successfully!');
      setFormData({ name: '', email: '', phone: '', subject: '', message: '' });
    } catch (error: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
      setStatus('error');
      setMessage(error.customMessage || 'Failed to connect to the server.');
    }
  };

  const containerVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 },
  };

  return (
    <>
      <PageSeo
        title="Contact | ByteeVolvr"
        description="Reach ByteeVolvr for AMC, consulting, B2B supply, and support enquiries."
      />
      <motion.section
        className="mx-auto max-w-7xl px-6 pb-24 pt-40 lg:px-8"
        initial="hidden"
        animate="visible"
        variants={containerVariants}
      >
        <motion.span
          variants={itemVariants}
          className="mb-4 block font-mono text-xs uppercase tracking-widest text-accent"
        >
          // Get In Touch
        </motion.span>
        <motion.h1
          variants={itemVariants}
          className="mb-6 font-display text-5xl font-bold leading-[0.9] text-white lg:text-7xl"
        >
          Contact
          <span className="block text-[rgba(139,155,184,0.5)]">Us</span>
        </motion.h1>
        <motion.p
          variants={itemVariants}
          className="max-w-xl text-lg leading-relaxed text-brand-muted"
        >
          Have a requirement or a question? Send us a message and our technical team will get back
          to you within 24 hours.
        </motion.p>

        <div className="mt-12 grid gap-10 lg:grid-cols-12">
          <motion.div variants={itemVariants} className="glass-panel rounded-2xl p-8 lg:col-span-4">
            <h2 className="mb-8 font-display text-xl font-semibold text-white">
              Contact Information
            </h2>
            <div className="space-y-6">
              <div className="flex items-start gap-4">
                <MapPin className="h-5 w-5 text-accent mt-1" />
                <div className="text-sm">
                  <p className="text-white font-medium">Visit Us</p>
                  <p className="text-brand-muted">
                    {details.address} {details.pincode ? `- ${details.pincode}` : ''}
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-4">
                <Phone className="h-5 w-5 text-accent mt-1" />
                <div className="text-sm">
                  <p className="text-white font-medium">Call Us</p>
                  <p className="text-brand-muted">{details.phone}</p>
                </div>
              </div>
              <div className="flex items-start gap-4">
                <Mail className="h-5 w-5 text-accent mt-1" />
                <div className="text-sm">
                  <p className="text-white font-medium">Email Us</p>
                  <p className="text-brand-muted">{details.email}</p>
                </div>
              </div>
              <div className="flex items-start gap-4">
                <Clock className="h-5 w-5 text-accent mt-1" />
                <div className="text-sm">
                  <p className="text-white font-medium">Working Hours</p>
                  <p className="text-brand-muted">
                    {details.workingHours || 'Mon-Sat: 9:00 AM - 7:00 PM'}
                  </p>
                </div>
              </div>

              {/* Google Maps Embed */}
              <div className="mt-8 overflow-hidden rounded-xl border border-white/5 bg-white/5 h-48 w-full grayscale opacity-70 hover:grayscale-0 hover:opacity-100 transition-all duration-500">
                <iframe
                  src={(() => {
                    const url = details.mapUrl;
                    if (url && url.includes('google.com/maps')) {
                      if (url.includes('embed') || url.includes('output=embed')) return url;
                      // Convert standard search/place URL to embed
                      return `https://www.google.com/maps?q=${encodeURIComponent(details.address)}&output=embed`;
                    }
                    return (
                      url ||
                      `https://www.google.com/maps?q=${encodeURIComponent(details.address)}&output=embed`
                    );
                  })()}
                  width="100%"
                  height="100%"
                  style={{ border: 0 }}
                  allowFullScreen={true}
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                ></iframe>
              </div>
            </div>
          </motion.div>

          <motion.form
            variants={itemVariants}
            className="glass-panel rounded-2xl p-8 lg:col-span-8"
            onSubmit={handleSubmit}
          >
            <h2 className="mb-6 font-display text-xl font-semibold text-white">
              Send us a Message
            </h2>
            <div className="grid gap-5 sm:grid-cols-2">
              <div className="space-y-2">
                <label className="text-xs font-medium text-brand-muted uppercase tracking-wider ml-1">
                  Full Name
                </label>
                <input
                  required
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  className="contact-input w-full"
                  placeholder="John Doe"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-medium text-brand-muted uppercase tracking-wider ml-1">
                  Email Address
                </label>
                <input
                  required
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  className="contact-input w-full"
                  placeholder="john@example.com"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-medium text-brand-muted uppercase tracking-wider ml-1">
                  Phone Number
                </label>
                <input
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  className="contact-input w-full"
                  placeholder="+91 98765 43210"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-medium text-brand-muted uppercase tracking-wider ml-1">
                  Subject
                </label>
                <input
                  name="subject"
                  value={formData.subject}
                  onChange={handleChange}
                  className="contact-input w-full"
                  placeholder="Requirement details"
                />
              </div>
            </div>
            <div className="mt-5 space-y-2">
              <label className="text-xs font-medium text-brand-muted uppercase tracking-wider ml-1">
                Message
              </label>
              <textarea
                required
                name="message"
                value={formData.message}
                onChange={handleChange}
                className="contact-input min-h-40 w-full resize-none"
                placeholder="Tell us about your requirement..."
              />
            </div>

            <div className="mt-6 flex flex-col sm:flex-row items-center gap-4">
              <button
                disabled={status === 'loading'}
                type="submit"
                className="btn-primary flex items-center justify-center gap-2 rounded-xl px-8 py-3 text-sm font-semibold text-white w-full sm:w-auto disabled:opacity-50"
              >
                {status === 'loading' ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Send className="h-4 w-4" />
                )}
                {status === 'loading' ? 'Sending...' : 'Send Message'}
              </button>

              {status === 'success' && (
                <motion.p
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  className="text-emerald-400 text-sm flex items-center gap-2"
                >
                  <CheckCircle2 className="h-4 w-4" />
                  {message}
                </motion.p>
              )}
              {status === 'error' && (
                <motion.p
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  className="text-rose-400 text-sm"
                >
                  {message}
                </motion.p>
              )}
            </div>
          </motion.form>
        </div>
      </motion.section>
    </>
  );
}

