import { createRateLimiters } from './middleware.js';

export function bootstrapRoutes(app: Express) {
  const { generalLimiter, authLimiter, webhookLimiter } = createRateLimiters();

  // Mount Routes with Specific Rate Limits
  app.use('/api/v1/auth', authLimiter, authRoutes);
  app.use('/api/v1/webhooks', webhookLimiter, webhookRoutes);

  app.use('/api/v1/accounting', generalLimiter, accountingRoutes);
  app.use('/api/v1/products', generalLimiter, productRoutes);
  app.use('/api/v1/orders', generalLimiter, orderRoutes);
  app.use('/api/v1/admin', generalLimiter, adminRoutes);
  app.use('/api/v1/reviews', generalLimiter, reviewRoutes);
  app.use('/api/v1/cms', generalLimiter, cmsRoutes);
  app.use('/api/v1/wishlist', generalLimiter, wishlistRoutes);
  app.use('/api/v1/payments', generalLimiter, paymentRoutes);
  app.use('/api/v1/shipping', generalLimiter, shippingRoutes);
  app.use('/api/v1/warehouse', inventoryRoutes);
  app.use('/api/v1/users', userRoutes);
  app.use('/api/v1/pos', posRoutes);
  app.use('/api/v1/marketing', marketingRoutes);
  app.use('/api/v1/leads', leadRoutes);
  app.use('/api/v1/support', supportRoutes);
  app.use('/api/v1/suppliers', supplierRoutes);
  app.use('/api/v1/whatsapp', whatsappRoutes);

  // Legacy compatibility
  app.use('/api/leads', leadRoutes);

  app.get(
    '/api/v1/reports/export',
    authenticate,
    authorize('admin', 'super-admin'),
    reportController.exportReport
  );

  // Health Check
  app.get(['/health', '/api/health'], (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });
}

import logger from '../services/logger.js';

const REQUIRED_ENV = [
  // eslint-disable-line @typescript-eslint/no-unused-vars
  'JWT_SECRET',
  'SUPABASE_URL',
  'SUPABASE_ANON_KEY',
  'SUPABASE_SERVICE_ROLE_KEY',
  'REDIS_URL',
];

export const validateEnvironment = () => {
  const missing: string[] = [];

  const supabaseUrl =
    process.env.SUPABASE_URL ||
    process.env.NEXT_PUBLIC_SUPABASE_URL ||
    process.env.VITE_SUPABASE_URL;

  const supabaseAnonKey =
    process.env.SUPABASE_ANON_KEY ||
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
    process.env.VITE_SUPABASE_ANON_KEY ||
    process.env.SUPABASE_KEY;

  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY;

  if (!supabaseUrl) missing.push('SUPABASE_URL (or VITE_/NEXT_ fallback)');
  if (!supabaseAnonKey) missing.push('SUPABASE_ANON_KEY (or VITE_/NEXT_ fallback)');
  if (!serviceRoleKey) missing.push('SUPABASE_SERVICE_ROLE_KEY');
  if (!process.env.JWT_SECRET) missing.push('JWT_SECRET');
  if (!process.env.REDIS_URL) missing.push('REDIS_URL');

  if (missing.length > 0) {
    logger.error(
      `❌ [Env Validation] Missing critical environment variables: ${missing.join(', ')}`
    );
    console.error(
      `❌ Critical environment variables missing: ${missing.join(', ')}. Server process shutting down.`
    );
    process.exit(1);
  }

  logger.info('✅ [Env Validation] All critical environment variables are present');
};

import path from 'path';
import { fileURLToPath } from 'url';

import { createClient } from '@supabase/supabase-js';
import dotenv from 'dotenv';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.resolve(__dirname, '../../../.env') });

const supabaseUrl =
  process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.VITE_SUPABASE_URL;

const supabaseKey =
  process.env.SUPABASE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
  process.env.VITE_SUPABASE_ANON_KEY;

const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_KEY;

if (!supabaseUrl) {
  throw new Error('CRITICAL: SUPABASE_URL is missing in environment variables.');
}
console.log(`[Supabase] Connecting to URL: ${supabaseUrl.substring(0, 15)}...`);
if (!supabaseKey) {
  throw new Error('CRITICAL: SUPABASE_KEY (anon key) is missing in environment variables.');
}

export const supabase = createClient(supabaseUrl!, supabaseKey!);

let adminClient: any = null;
// eslint-disable-line @typescript-eslint/no-explicit-any
let cachedAdminToken: string | null = null;
let tokenExpiresAt = 0;
let adminClientInitialized = false; // track whether service-role client was created

let adminClientPromise: Promise<any> | null = null;
// eslint-disable-line @typescript-eslint/no-explicit-any

export const getAdminClient = async () => {
  // 1. Preferred: Service Role Key (Bypasses RLS)
  if (serviceRoleKey) {
    if (!adminClientInitialized) {
      console.log('[Supabase] Initializing Admin Client with Service Role Key');
      adminClient = createClient(supabaseUrl!, serviceRoleKey, {
        auth: { persistSession: false },
      });
      adminClientInitialized = true;
    }
    return adminClient;
  }

  // 2. Fallback: Authenticate as Admin user
  if (adminClient && cachedAdminToken && Date.now() < tokenExpiresAt) {
    return adminClient;
  }

  // If already logging in, wait for that
  if (adminClientPromise) {
    return adminClientPromise;
  }

  adminClientPromise = (async () => {
    try {
      console.warn('[Supabase] Service Role Key missing. Falling back to Admin Auth.');
      const adminEmail = process.env.ADMIN_EMAIL;
      const adminPassword = process.env.ADMIN_PASSWORD;

      if (!adminEmail || !adminPassword) {
        throw new Error('Missing Admin credentials');
      }

      const tempClient = createClient(supabaseUrl!, supabaseKey!);
      const { data, error } = await tempClient.auth.signInWithPassword({
        email: adminEmail,
        password: adminPassword,
      });

      if (error || !data.session) {
        throw error || new Error('Auth failed');
      }

      cachedAdminToken = data.session.access_token;
      tokenExpiresAt = Date.now() + data.session.expires_in * 1000 - 60000;

      adminClient = createClient(supabaseUrl!, supabaseKey!, {
        global: { headers: { Authorization: `Bearer ${cachedAdminToken}` } },
      });

      return adminClient;
    } catch (err) {
      console.error('[Supabase] Admin login failed:', err);
      return supabase; // Final fallback
    } finally {
      adminClientPromise = null;
    }
  })();

  return adminClientPromise;
};

import { Queue } from 'bullmq';

import { getAdminClient } from '../../config/supabase.js';
import logger from '../../services/logger.js';
import { redis } from '../../config/redis.js';

export const automationQueue = new Queue('marketing-automation', { connection: redis });

export class AutomationEngine {
  /**
   * Listen for system events and trigger relevant automations
   * Example: evaluateTrigger('order.created', { customerId: '123', orderId: '456' })
   */
  static async evaluateTrigger(eventName: string, payload: Record<string, any>) {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    logger.info(`[AutomationEngine] Evaluating trigger: ${eventName}`);

    const admin = await getAdminClient();

    // Find all active flows listening to this event
    const { data: flows, error } = await admin
      .from('automation_flows')
      .select('*')
      .eq('trigger_event', eventName)
      .eq('is_active', true);

    if (error) {
      logger.error('[AutomationEngine] Failed to fetch flows', error);
      return;
    }

    if (!flows || flows.length === 0) {
      logger.info(`[AutomationEngine] No active flows found for event: ${eventName}`);
      return;
    }

    // For each flow, create an automation_run and enqueue the first step
    for (const flow of flows) {
      // Evaluate conditions here before starting the run if trigger_conditions exist
      // For now, assume it passes the base trigger

      const { data: run, error: runError } = await admin
        .from('automation_runs')
        .insert({
          flow_id: flow.id,
          user_id: payload.customerId || payload.userId || null,
          trigger_data: payload,
          current_step_index: 0,
          status: 'active',
        })
        .select()
        .single();

      if (runError || !run) {
        logger.error(`[AutomationEngine] Failed to create run for flow ${flow.id}`, runError);
        continue;
      }

      logger.info(`[AutomationEngine] Started flow run ${run.id} for flow ${flow.id}`);

      // Enqueue the first step execution
      await automationQueue.add(
        'execute-flow-step',
        {
          runId: run.id,
          flowId: flow.id,
          stepIndex: 0,
        },
        {
          removeOnComplete: true,
          attempts: 3,
          backoff: { type: 'exponential', delay: 5000 },
        }
      );
    }
  }
}

