import { Resend } from 'resend';

import logger from '../../services/logger.js';

import { IProvider, SendMessagePayload, SendMessageResult } from './IProvider.js';

export class ResendEmailProvider implements IProvider {
  public readonly name = 'resend-email';
  private client: Resend | null = null;

  async initialize(config?: any): Promise<void> {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const apiKey = config?.resendApiKey || process.env.RESEND_API_KEY;
    if (apiKey) {
      this.client = new Resend(apiKey);
      logger.info('[ResendEmailProvider] Initialized successfully');
    } else {
      logger.warn('[ResendEmailProvider] Missing API KEY, provider running in mock mode');
    }
  }

  async sendMessage(payload: SendMessagePayload): Promise<SendMessageResult> {
    if (!this.client) {
      logger.info(
        `[ResendEmailProvider MOCK] Would send email to ${payload.to} with subject: ${payload.subject}`
      );
      return {
        success: true,
        messageId: `mock-${Date.now()}`,
        timestamp: new Date().toISOString(),
      };
    }

    try {
      const { data, error } = await this.client.emails.send({
        from: 'ByteEvolvr <noreply@byteevolvr.com>',
        to: payload.to,
        subject: payload.subject || 'ByteEvolvr Notification',
        html: payload.content,
      });

      if (error) {
        throw error;
      }

      return {
        success: true,
        messageId: data?.id,
        timestamp: new Date().toISOString(),
      };
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(`[ResendEmailProvider] Failed to send email to ${payload.to}:`, err);
      return {
        success: false,
        error: err.message,
        timestamp: new Date().toISOString(),
      };
    }
  }

  async isHealthy(): Promise<boolean> {
    if (!this.client) return false;
    try {
      // Perform a lightweight API call to verify the key works
      const { error } = await this.client.domains.list();
      return !error;
    } catch (e) {
      // eslint-disable-line @typescript-eslint/no-unused-vars
      return false;
    }
  }
}

import axios, { AxiosInstance } from 'axios';

import logger from '../../services/logger.js';

import { IProvider, SendMessagePayload, SendMessageResult } from './IProvider.js';

export class BrevoProvider implements IProvider {
  public readonly name = 'brevo-email';
  private client: AxiosInstance | null = null;
  private fromAddress: string = 'noreply@byteevolvr.com';

  async initialize(config?: any): Promise<void> {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const brevoApiKey = config?.brevoApiKey || process.env.BREVO_API_KEY;
    if (!brevoApiKey) {
      logger.warn('[BrevoProvider] Brevo API Key is missing');
    } else {
      this.client = axios.create({
        baseURL: 'https://api.brevo.com/v3',
        headers: {
          'api-key': brevoApiKey,
          'Content-Type': 'application/json',
        },
      });
      logger.info('[BrevoProvider] Initialized successfully');
    }
  }

  async sendMessage(payload: SendMessagePayload): Promise<SendMessageResult> {
    if (!this.client) {
      return {
        success: false,
        error: 'BrevoProvider not initialized',
        timestamp: new Date().toISOString(),
      };
    }

    try {
      const toList = Array.isArray(payload.to) ? payload.to : [payload.to];

      const response = await this.client.post('/smtp/email', {
        sender: { email: this.fromAddress },
        to: toList.map((email: string) => ({ email })),
        subject: payload.subject || 'Notification from ByteEvolvr',
        htmlContent: payload.content,
      });

      return {
        success: true,
        messageId: response.data.messageId,
        timestamp: new Date().toISOString(),
      };
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error('[BrevoProvider] Send error:', err?.response?.data || err.message);
      return {
        success: false,
        error: err?.response?.data?.message || err.message,
        timestamp: new Date().toISOString(),
      };
    }
  }

  async isHealthy(): Promise<boolean> {
    return this.client !== null;
  }
}

import admin from 'firebase-admin';

import logger from '../../services/logger.js';

import { IProvider, SendMessagePayload, SendMessageResult } from './IProvider.js';

export class FirebaseProvider implements IProvider {
  public readonly name = 'firebase-push';
  private app: admin.app.App | null = null;

  async initialize(): Promise<void> {
    const serviceAccountBase64 = process.env.FIREBASE_SERVICE_ACCOUNT_BASE64;
    if (!serviceAccountBase64) {
      logger.warn('[FirebaseProvider] Missing FIREBASE_SERVICE_ACCOUNT_BASE64');
    } else {
      try {
        const serviceAccount = JSON.parse(
          Buffer.from(serviceAccountBase64, 'base64').toString('utf-8')
        );
        if (!admin.apps.length) {
          admin.initializeApp({
            credential: admin.credential.cert(serviceAccount),
          });
        }
        this.app = admin.app();
        logger.info('[FirebaseProvider] Initialized successfully');
      } catch (err: any) {
        // eslint-disable-line @typescript-eslint/no-explicit-any
        logger.error('[FirebaseProvider] Failed to initialize:', err);
      }
    }
  }

  async sendMessage(payload: SendMessagePayload): Promise<SendMessageResult> {
    if (!this.app) {
      return {
        success: false,
        error: 'FirebaseProvider not initialized',
        timestamp: new Date().toISOString(),
      };
    }

    try {
      const tokens = Array.isArray(payload.to) ? payload.to : [payload.to];

      const message = {
        notification: {
          title: payload.subject || 'ByteEvolvr Notification',
          body: payload.content,
        },
        token: tokens[0],
      };

      const messageId = await this.app.messaging().send(message);
      return { success: true, messageId, timestamp: new Date().toISOString() };
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error('[FirebaseProvider] Send error:', err);
      return { success: false, error: err.message, timestamp: new Date().toISOString() };
    }
  }

  async sendBulk(payloads: SendMessagePayload[]): Promise<SendMessageResult[]> {
    if (!this.app) {
      return payloads.map(() => ({
        success: false,
        error: 'FirebaseProvider not initialized',
        timestamp: new Date().toISOString(),
      }));
    }

    try {
      const messages = payloads.map((p) => ({
        notification: {
          title: p.subject || 'ByteEvolvr Notification',
          body: p.content,
        },
        token: Array.isArray(p.to) ? p.to[0] : p.to,
      }));

      const response = await this.app.messaging().sendEach(messages);

      return response.responses.map((res) => ({
        success: res.success,
        messageId: res.messageId,
        error: res.error?.message,
        timestamp: new Date().toISOString(),
      }));
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error('[FirebaseProvider] Unexpected bulk error:', err);
      return payloads.map(() => ({
        success: false,
        error: err.message,
        timestamp: new Date().toISOString(),
      }));
    }
  }

  async isHealthy(): Promise<boolean> {
    return this.app !== null;
  }
}

import nodemailer from 'nodemailer';

import logger from '../../services/logger.js';

import { IProvider, SendMessagePayload, SendMessageResult } from './IProvider.js';

export class SmtpProvider implements IProvider {
  public readonly name = 'smtp-email';
  private transporter: nodemailer.Transporter | null = null;
  private fromAddress: string = 'noreply@byteevolvr.com';

  async initialize(config?: any): Promise<void> {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const smtpHost = config?.smtpHost || process.env.SMTP_HOST;
    const smtpPort = config?.smtpPort || process.env.SMTP_PORT;
    const smtpUser = config?.smtpUser || process.env.SMTP_USER;
    const smtpPass = config?.smtpPass || process.env.SMTP_PASS;
    const secure = config?.smtpSecure !== undefined ? config.smtpSecure : Number(smtpPort) === 465;

    if (config?.defaultFromAddress) {
      this.fromAddress = config.defaultFromAddress;
    }

    if (!smtpHost || !smtpPort) {
      logger.warn('[SmtpProvider] Missing SMTP configurations');
    } else {
      this.transporter = nodemailer.createTransport({
        host: smtpHost,
        port: Number(smtpPort),
        secure: secure,
        auth: {
          user: smtpUser,
          pass: smtpPass,
        },
      });
      logger.info('[SmtpProvider] Initialized successfully');
    }
  }

  async sendMessage(payload: SendMessagePayload): Promise<SendMessageResult> {
    if (!this.transporter) {
      return {
        success: false,
        error: 'SmtpProvider not initialized',
        timestamp: new Date().toISOString(),
      };
    }

    try {
      const toList = Array.isArray(payload.to) ? payload.to.join(',') : payload.to;

      const info = await this.transporter.sendMail({
        from: this.fromAddress,
        to: toList,
        subject: payload.subject || 'Notification from ByteEvolvr',
        html: payload.content,
      });

      return { success: true, messageId: info.messageId, timestamp: new Date().toISOString() };
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error('[SmtpProvider] Send error:', err);
      return { success: false, error: err.message, timestamp: new Date().toISOString() };
    }
  }

  async isHealthy(): Promise<boolean> {
    if (!this.transporter) return false;
    try {
      return await this.transporter.verify();
    } catch (e) {
      logger.warn('[SmtpProvider] Health check failed:', e);
      return false;
    }
  }
}

import logger from '../../services/logger.js';

export class TemplateEngine {
  /**
   * Renders a template string by replacing {{variable}} with values from context
   * @param template - The raw template string
   * @param context - Key-value pairs for substitution
   * @returns The rendered string
   */
  static render(template: string, context: Record<string, any>): string {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    if (!template) return '';
    if (!context) return template;

    try {
      // Regex to match {{ variable_name }} or {{variable_name}}
      return template.replace(/\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/g, (match, key) => {
        // Resolve nested keys e.g. {{ user.name }}
        const value = this.resolveKey(key, context);
        return value !== undefined && value !== null ? String(value) : '';
      });
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error('[TemplateEngine] Error rendering template:', err);
      return template;
    }
  }

  /**
   * Evaluates a dot-notated key against a context object
   */
  private static resolveKey(key: string, context: any): any {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    return key
      .split('.')
      .reduce((acc, part) => (acc && acc[part] !== undefined ? acc[part] : undefined), context);
  }
}

import { Worker, Job } from 'bullmq';

import { redis } from '../config/redis.js';
import logger from '../services/logger.js';
import { getAdminClient } from '../config/supabase.js';
import { AutomationRunnerService } from '../modules/marketing/services/automation-runner.service.js';
import { AutomationRunPayload } from '../core/contracts/automation.js';

const automationRunner = new AutomationRunnerService();

export const automationWorker = new Worker(
  'marketing-automation',
  async (job: Job<AutomationRunPayload>) => {
    const { runId, flowId, stepIndex } = job.data;
    logger.info(`[AutomationWorker] Processing run ${runId}, step ${stepIndex}`);

    const admin = await getAdminClient();

    try {
      const { nextStepIndex, delayMs } = await automationRunner.executeStep(
        runId,
        flowId,
        stepIndex
      );

      if (nextStepIndex !== undefined) {
        const { automationQueue } = await import('../core/automation/AutomationEngine.js');
        await automationQueue.add(
          'execute-flow-step',
          { runId, flowId, stepIndex: nextStepIndex },
          { delay: delayMs, removeOnComplete: true }
        );
      }
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(`[AutomationWorker] Error executing step ${stepIndex} for run ${runId}:`, err);
      // Mark run as failed
      await admin.from('automation_runs').update({ status: 'failed' }).eq('id', runId);
      throw err;
    }
  },
  {
    connection: redis,
    stalledInterval: 300_000, // Check stalled jobs every 5 min (default: 30s)
    lockDuration: 600_000, // Lock for 10 min (must exceed stalledInterval)
    drainDelay: 60, // Poll every 60s when idle — saves ~1M Redis commands/month vs 10s
    removeOnComplete: { count: 100 }, // Auto-cleanup completed jobs
    removeOnFail: { count: 200 }, // Keep last 200 failures for debugging
  }
);

