import logger from '../services/logger.js';
import { WhatsAppRepository } from '../modules/whatsapp/whatsapp.repository.js';
// eslint-disable-line @typescript-eslint/no-unused-vars
import {
  emailQueue,
  notificationQueue,
  analyticsQueue,
  marketingAutomationQueue,
  whatsappQueue,
} from '../core/queues/index.js';
import { SocketGateway } from '../core/notifications/SocketGateway.js';

import { automationWorker } from './automation.worker.js';
import { whatsappWorker } from './whatsapp.worker.js';

// Define Workers
// REDIS OPTIMISATION: stalledInterval controls how often BullMQ polls for stalled jobs.
// Default is 30s which generates many Redis commands. We set it to 300s (5 min).
// lockDuration must be larger than stalledInterval.
const WORKER_OPTIONS = {
  connection: redis,
  stalledInterval: 300_000, // Check for stalled jobs every 5 min (default: 30s)
  lockDuration: 600_000, // Hold job lock for 10 min
  drainDelay: 60, // Poll every 60s when queue is empty (was 10s).
  // At 10s: 5 workers × 6 polls/min × 60×24×30 = ~1,296,000 cmds/month ❌
  // At 60s: 5 workers × 1 poll/min × 60×24×30 = ~216,000 cmds/month ✅
  removeOnComplete: { count: 100 }, // Keep only last 100 completed jobs in Redis
  removeOnFail: { count: 500 }, // Keep only last 500 failed jobs
};

export const emailWorker = new Worker(
  'email-queue',
  async (job: Job) => {
    const { to, subject, html } = job.data;
    logger.info(`[Job] Sending email to ${to}...`);
    try {
      await EmailService.sendEmail(to, subject, html);
    } catch (err) {
      logger.error(`[Job] Email failed for ${to}:`, err);
      throw err;
    }
  },
  WORKER_OPTIONS
);

export const notificationWorker = new Worker(
  'notification-queue',
  async (job: Job) => {
    const { title, message, type, priority } = job.data;
    logger.info(`[Job] Creating system notification: ${title}`);
    try {
      await NotificationService.send({ title, message, type, priority });
    } catch (err) {
      logger.error(`[Job] Notification failed:`, err);
    }
  },
  WORKER_OPTIONS
);

export const analyticsWorker = new Worker(
  'analytics-queue',
  async (job: Job) => {
    const { type, payload } = job.data;
    logger.info(`[Job] Processing analytics event: ${type}`);
    try {
      await AnalyticsService.recordEvent(type, payload);
      logger.info(`[Analytics] Successfully processed event: ${type}`);
    } catch (err) {
      logger.error(`[Job] Analytics event failed:`, err);
      throw err;
    }
  },
  WORKER_OPTIONS
);

// Dead-Letter Queue Logic
const setupDLQ = (worker: Worker) => {
  worker.on('failed', async (job: Job | undefined, err: Error) => {
    if (!job) return;

    // Check if it's permanently failed (exhausted retries)
    if (job.attemptsMade >= (job.opts.attempts || 1)) {
      logger.error(`[DLQ] Job ${job.id} in ${job.name} permanently failed. Moving to DLQ.`);
      try {
        const { getAdminClient } = await import('../config/supabase.js');
        const admin = await getAdminClient();

        await admin.from('dlq_jobs').insert({
          queue_name: worker.name,
          job_name: job.name,
          payload: job.data,
          error_message: err.message,
          stack_trace: err.stack,
          status: 'unresolved',
        });
        logger.info(`[DLQ] Job ${job.id} successfully recorded in dlq_jobs table.`);
      } catch (dlqErr) {
        logger.error(`[DLQ] Failed to record dead-letter job:`, dlqErr);
      }
    }
  });
};

setupDLQ(emailWorker);
setupDLQ(notificationWorker);
setupDLQ(analyticsWorker);
setupDLQ(automationWorker);
setupDLQ(whatsappWorker);

// Telemetry loop for Admin Panel Dashboard
const queues = [
  emailQueue,
  notificationQueue,
  analyticsQueue,
  marketingAutomationQueue,
  whatsappQueue,
];

// Telemetry broadcasts queue stats to the admin panel via WebSocket.
// IMPORTANT: Reduced from 5s to 60s to stay within Upstash 500k commands/month free tier.
// At 60s: 5 queues × 4 cmds × 1/min × 60 × 24 × 30 = ~43,200 cmds/month.
const telemetryInterval = setInterval(async () => {
  for (const q of queues) {
    try {
      const counts = await q.getJobCounts();
      SocketGateway.broadcastQueueStatus(q.name, {
        waiting: counts.waiting,
        active: counts.active,
        failed: counts.failed,
        completed: counts.completed,
      });
    } catch (e) {
      // eslint-disable-line @typescript-eslint/no-unused-vars
      // Ignore if redis goes down temporarily
    }
  }
}, 60_000); // 60 seconds — was 5000ms, reduced to save Redis commands

// Graceful shutdown
export const shutdownJobs = async () => {
  clearInterval(telemetryInterval);
  await emailQueue.close();
  await notificationQueue.close();
  await whatsappQueue.close();
  await analyticsQueue.close();
  await marketingAutomationQueue.close();
  await emailWorker.close();
  await notificationWorker.close();
  await analyticsWorker.close();
  await automationWorker.close();
  await whatsappWorker.close();
};

logger.info('[Jobs] Background workers initialized. Queue telemetry active.');

import { Worker, Job } from 'bullmq';

import { redis } from '../config/redis.js';
import logger from '../services/logger.js';
import { WhatsAppRepository } from '../modules/whatsapp/whatsapp.repository.js';
import { WhatsAppProviderFactory } from '../modules/marketing/providers/whatsapp/whatsappProviderFactory.js';

const whatsappRepo = new WhatsAppRepository();
const providerFactory = new WhatsAppProviderFactory();

export const whatsappWorker = new Worker(
  'whatsapp-queue',
  async (job: Job) => {
    // eslint-disable-line complexity
    // Handle remote control commands
    if (job.name === 'control') {
      return { success: true };
    }

    const { to, payload, jobId, providerOverride } = job.data;
    logger.info(`[WhatsApp Worker] Processing job ${job.id} to send message to ${to}`);

    try {
      // 1. Initialize/Re-fetch provider configs from DB
      await providerFactory.initializeProviders();

      // 2. Identify message type
      let type: 'text' | 'media' | 'template' = 'text';
      if (payload.type === 'template') type = 'template';
      if (payload.type === 'image' || payload.type === 'document') type = 'media';

      // 3. Prepare unified payload
      const providerPayload: any = {
        // eslint-disable-line @typescript-eslint/no-explicit-any
        to,
        content: payload.content || '',
        metadata: payload,
      };

      if (type === 'media') {
        providerPayload.mediaUrl = payload.mediaUrl;
        providerPayload.caption = payload.content;
        providerPayload.fileName = payload.fileName;
        providerPayload.mimeType = payload.mimeType;
      } else if (type === 'template') {
        providerPayload.templateId = payload.templateId;
        providerPayload.languageCode = payload.languageCode;
        providerPayload.components = payload.components;
      }

      // 4. Send via Factory (automatically handles failover)
      const result = await providerFactory.sendWithFailover(
        providerPayload,
        type,
        providerOverride
      );

      if (!result.success) {
        // Validation / Invalid Recipient check (non-existent WhatsApp number)
        const isValidationFailure =
          result.error?.includes('not registered on WhatsApp') ||
          result.error?.includes('exists:false') ||
          result.error?.includes('invalid number') ||
          result.error?.includes('exists is false');

        if (isValidationFailure) {
          logger.warn(
            `[WhatsApp Worker] Recipient validation failed for ${to}: ${result.error}. Resolving job gracefully as permanently failed.`
          );
          if (jobId) {
            await whatsappRepo.updateMessageStatus(jobId, 'failed', result.error);
          }
          return {
            success: false,
            status: 'invalid_recipient',
            error: result.error,
            providerUsed: result.provider,
          };
        }

        throw new Error(result.error || 'Unknown provider error');
      }

      // 5. Update Legacy DB Status (Optional, keeping for dashboard backward compatibility)
      if (jobId) {
        await whatsappRepo.updateMessageStatus(jobId, 'sent');
        // Update the new columns
        const admin = await import('../config/supabase.js').then((m) => m.getAdminClient());
        await admin
          .from('whatsapp_messages')
          .update({
            provider_used: result.provider,
            external_id: result.messageId,
            updated_at: new Date().toISOString(),
          })
          .eq('id', jobId);
      }

      return { success: true, messageId: result.messageId, providerUsed: result.provider };
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(`[WhatsApp Worker] Failed to send message:`, err);
      if (jobId) await whatsappRepo.updateMessageStatus(jobId, 'failed', err.message);
      throw err;
    }
  },
  {
    connection: redis,
    concurrency: 5,
    stalledInterval: 300_000, // Check stalled jobs every 5 min (default: 30s)
    lockDuration: 600_000, // Hold job lock for 10 min
    drainDelay: 60, // Poll every 60s when idle — saves ~1M Redis commands/month vs 10s
    removeOnComplete: { count: 100 }, // Keep only last 100 completed jobs
    removeOnFail: { count: 500 }, // Keep only last 500 failed jobs
  }
);

whatsappWorker.on('failed', (job, err) => {
  logger.error(`[WhatsApp Worker] Job ${job?.id} failed in queue:`, err);
});

import { Response, NextFunction } from 'express';

import { AuditService } from '../services/auditService.js';

import { AuthRequest } from './auth.js';

export const auditLog = (module: string, action: string) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    const originalJson = res.json;

    res.json = function (data: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      // Log after response is sent
      if (res.statusCode >= 200 && res.statusCode < 300) {
        AuditService.log({
          user_id: req.user?.id,
          action: action,
          module: module,
          entity_id: req.params.id || data.id,
          new_data: req.method !== 'GET' ? req.body : undefined,
          ip_address: req.ip,
          user_agent: req.headers['user-agent'],
        });
      }
      return originalJson.call(this, data);
    };

    next();
  };
};

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

import { supabase, getAdminClient } from '../config/supabase.js';
import logger from '../services/logger.js';
import { redis } from '../config/redis.js';

import { AppError } from './error.js';

const jwtSecret = process.env.JWT_SECRET;

if (!jwtSecret) {
  throw new Error('JWT_SECRET is required for backend authentication');
}

const JWT_SECRET: string = jwtSecret;

// ─── L1 In-Memory Auth Profile Cache ─────────────────────────────────────────
// Sits in front of Redis to avoid a network round-trip on every API request.
// At 10k users with ~15 reqs/day each → saves ~855k Redis GET commands/month.
interface ProfileEntry {
  role: string;
  fullName: string;
  expiresAt: number;
}
const profileL1 = new Map<string, ProfileEntry>();
const L1_AUTH_TTL_MS = 2 * 60 * 1000; // 2 minutes in-memory
const REDIS_AUTH_TTL_S = 86_400; // 24 hours in Redis (was 3600)

const getProfileL1 = (userId: string): ProfileEntry | null => {
  const entry = profileL1.get(userId);
  if (!entry) return null;
  if (Date.now() > entry.expiresAt) {
    profileL1.delete(userId);
    return null;
  }
  return entry;
};

const setProfileL1 = (userId: string, role: string, fullName: string): void => {
  profileL1.set(userId, { role, fullName, expiresAt: Date.now() + L1_AUTH_TTL_MS });
};

const delProfileL1 = (userId: string): void => {
  // eslint-disable-line @typescript-eslint/no-unused-vars
  profileL1.delete(userId);
};

export interface AuthRequest extends Request {
  user?: any;
  // eslint-disable-line @typescript-eslint/no-explicit-any
}

/**
 * Revokes/blacklists a token in Redis until its natural expiration.
 */
export const blacklistToken = async (token: string, expiresAtUnix: number): Promise<void> => {
  try {
    if (redis && redis.status === 'ready') {
      const ttl = Math.max(0, expiresAtUnix - Math.floor(Date.now() / 1000));
      if (ttl > 0) {
        await redis.set(`blacklist:token:${token}`, '1', 'EX', ttl);
        logger.info(`[Auth] Token successfully blacklisted for ${ttl} seconds`);
      }
    }
  } catch (err) {
    logger.error(`[Auth] Failed to blacklist token: ${(err as Error).message}`);
  }
};

export const authenticate = async (req: AuthRequest, res: Response, next: NextFunction) => {
  // eslint-disable-line complexity
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return next(new AppError('Unauthorized', 401));
    }

    const token = authHeader.split(' ')[1];

    // Check if token is blacklisted
    try {
      if (redis && redis.status === 'ready') {
        const isBlacklisted = await redis.get(`blacklist:token:${token}`);
        if (isBlacklisted) {
          logger.warn(`[Auth] Access attempted with blacklisted token for path: ${req.path}`);
          return next(new AppError('Invalid or expired token', 401));
        }
      }
    } catch (redisErr) {
      logger.error(`[Auth] Blacklist check error: ${(redisErr as Error).message}`);
    }

    let user: any = null;
    // eslint-disable-line @typescript-eslint/no-explicit-any
    let role: string = 'user';
    let fullName: string = '';

    const decodedUnverified: any = jwt.decode(token);
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const isSupabaseToken =
      decodedUnverified && decodedUnverified.iss && decodedUnverified.iss.includes('supabase');

    if (isSupabaseToken) {
      // 1. Try Supabase Auth
      const {
        data: { user: sbUser },
        error: sbError,
      } = await supabase.auth.getUser(token);

      if (sbUser && !sbError) {
        user = sbUser;

        const cacheKey = `user_profile:${user.id}`;

        // ── L1 check (zero Redis cost) ──
        const l1Hit = getProfileL1(user.id);
        if (l1Hit) {
          role = l1Hit.role;
          fullName = l1Hit.fullName;
        } else {
          // ── L2 Redis check ──
          let cachedProfile: any = null;
          // eslint-disable-line @typescript-eslint/no-explicit-any
          try {
            if (redis.status === 'ready') {
              const data = await redis.get(cacheKey);
              if (data) cachedProfile = JSON.parse(data);
            }
          } catch (_e) {
            /* ignore */
          }

          if (cachedProfile) {
            role = cachedProfile.role;
            fullName = cachedProfile.fullName;
            setProfileL1(user.id, role, fullName); // backfill L1
          } else {
            // ── DB fetch (cache miss) ──
            try {
              const admin = await getAdminClient();
              const { data: profile } = await admin
                .from('user_profiles')
                .select('role, full_name')
                .eq('id', user.id)
                .single();

              role = profile?.role || 'user';
              fullName = profile?.full_name || user.email?.split('@')[0];

              // Write to L1 and L2
              setProfileL1(user.id, role, fullName);
              try {
                if (redis.status === 'ready') {
                  await redis.set(
                    cacheKey,
                    JSON.stringify({ role, fullName }),
                    'EX',
                    REDIS_AUTH_TTL_S
                  );
                }
              } catch (_e) {
                /* ignore */
              }
            } catch (profileError: any) {
              // eslint-disable-line @typescript-eslint/no-explicit-any
              logger.error(`[Auth] Profile fetch failed: ${profileError.message}`);
              role = 'user';
              fullName = user.email?.split('@')[0];
            }
          }
        }
      }
    } else {
      // 2. Try Local JWT (for hardcoded admin)
      try {
        const decoded: any = jwt.verify(token, JWT_SECRET);
        // eslint-disable-line @typescript-eslint/no-explicit-any
        user = { id: decoded.id, email: decoded.email };
        role = decoded.role || 'user';
        fullName = 'Main Admin';
      } catch (jwtError) {
        logger.warn(`[Auth] Validation failed for ${req.path}: ${(jwtError as Error).message}`);
        return next(new AppError('Invalid or expired token', 401));
      }
    }

    req.user = {
      ...user,
      role,
      fullName,
    };

    next();
  } catch (err) {
    next(err);
  }
};

export const authenticateOptional = async (req: AuthRequest, res: Response, next: NextFunction) => {
  // eslint-disable-line complexity
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return next();
    }

    const token = authHeader.split(' ')[1];

    // Check if token is blacklisted
    try {
      if (redis && redis.status === 'ready') {
        const isBlacklisted = await redis.get(`blacklist:token:${token}`);
        if (isBlacklisted) {
          logger.warn(`[Auth] Optional auth: Attempted use of blacklisted token`);
          return next();
        }
      }
    } catch (redisErr) {
      logger.error(`[Auth] Blacklist check error: ${(redisErr as Error).message}`);
    }

    const decodedUnverified: any = jwt.decode(token);
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const isSupabaseToken =
      decodedUnverified && decodedUnverified.iss && decodedUnverified.iss.includes('supabase');

    if (isSupabaseToken) {
      const {
        data: { user: sbUser },
        error: sbError,
      } = await supabase.auth.getUser(token);

      if (sbUser && !sbError) {
        const cacheKey = `user_profile:${sbUser.id}`;
        let cachedProfile: any = null;
        // eslint-disable-line @typescript-eslint/no-explicit-any

        try {
          if (redis.status === 'ready') {
            const data = await redis.get(cacheKey);
            if (data) cachedProfile = JSON.parse(data);
          }
        } catch (_e) {
          /* ignore cache errors */
        }

        if (cachedProfile) {
          req.user = {
            ...sbUser,
            role: cachedProfile.role,
            fullName: cachedProfile.fullName,
          };
        } else {
          try {
            const admin = await getAdminClient();
            const { data: profile } = await admin
              .from('user_profiles')
              .select('role, full_name')
              .eq('id', sbUser.id)
              .single();

            const role = profile?.role || 'user';
            const fullName = profile?.full_name || sbUser.email?.split('@')[0];

            req.user = { ...sbUser, role, fullName };

            // Cache it
            try {
              if (redis.status === 'ready') {
                await redis.set(cacheKey, JSON.stringify({ role, fullName }), 'EX', 3600);
              }
            } catch (_e) {
              /* ignore cache errors */
            }
          } catch (_profileErr: any) {
            // eslint-disable-line @typescript-eslint/no-explicit-any
            req.user = {
              ...sbUser,
              role: 'user',
              fullName: sbUser.email?.split('@')[0],
            };
          }
        }
      }
    } else {
      // Try local JWT fallback
      try {
        const decoded: any = jwt.verify(token, JWT_SECRET);
        // eslint-disable-line @typescript-eslint/no-explicit-any
        req.user = {
          id: decoded.id,
          email: decoded.email,
          role: decoded.role || 'user',
          fullName: 'Main Admin',
        };
      } catch (jwtErr) {
        // eslint-disable-line @typescript-eslint/no-unused-vars
        // Proceed as guest
      }
    }
  } catch (err) {
    logger.debug(`[Auth] Optional auth failed: ${(err as Error).message}`);
  }
  next();
};

export const authorize = (...roles: string[]) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    try {
      if (!req.user) {
        return next(new AppError('Unauthorized', 401));
      }

      if (!roles.includes(req.user.role)) {
        logger.warn(
          `[Auth] Access denied for user ${req.user.id}. Role: ${req.user.role}. Required: ${roles.join(', ')}`
        );
        return next(new AppError('Forbidden: Access denied', 403));
      }

      next();
    } catch (err) {
      next(err);
    }
  };
};

