import { Request, Response, NextFunction } from 'express';

import logger from '../services/logger.js';

export class AppError extends Error {
  statusCode: number;
  isOperational: boolean;

  constructor(message: string, statusCode: number) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

export const errorHandler = (err: any, req: Request, res: Response, next: NextFunction) => {
  // eslint-disable-line @typescript-eslint/no-explicit-any
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  logger.error(
    `${err.statusCode} - ${err.message} - ${req.originalUrl} - ${req.method} - ${req.ip}`
  );

  if (process.env.NODE_ENV === 'development') {
    res.status(err.statusCode).json({
      success: false,
      message: err.message,
      error: err,
      stack: err.stack,
    });
  } else {
    // Production: Don't leak error details
    if (err.isOperational) {
      res.status(err.statusCode).json({
        success: false,
        message: err.message,
      });
    } else {
      res.status(500).json({
        success: false,
        message: 'Internal Server Error',
      });
    }
  }
};

export const catchAsync = (fn: Function) => {
  return (req: Request, res: Response, next: NextFunction) => {
    fn(req, res, next).catch(next);
  };
};

import { Request, Response, NextFunction } from 'express';
import { GrowthBook } from '@growthbook/growthbook';

// Initialize a generic GrowthBook instance for the backend
const growthbook = new GrowthBook({
  apiHost: process.env.GROWTHBOOK_API_HOST || 'https://cdn.growthbook.io',
  clientKey: process.env.GROWTHBOOK_CLIENT_KEY || 'development_key',
});

// Load features initially and periodically
growthbook.loadFeatures({ autoRefresh: true }).catch((err) => {
  console.warn('[GrowthBook] Failed to load features on startup:', err);
});

export const featureFlagMiddleware = (req: Request, res: Response, next: NextFunction) => {
  // Create a request-specific GrowthBook instance
  const gb = new GrowthBook({
    apiHost: process.env.GROWTHBOOK_API_HOST || 'https://cdn.growthbook.io',
    clientKey: process.env.GROWTHBOOK_CLIENT_KEY || 'development_key',
    // We reuse the features loaded in the global instance
    features: growthbook.getFeatures(),
    attributes: {
      id: (req as any).user?.id || 'anonymous',
      // eslint-disable-line @typescript-eslint/no-explicit-any
      userAgent: req.headers['user-agent'],
      url: req.originalUrl,
    },
  });

  // Attach to request for downstream use
  (req as any).growthbook = gb;
  // eslint-disable-line @typescript-eslint/no-explicit-any

  next();
};

// Helper for route guards
export const requireFeature = (featureKey: string) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const gb = (req as any).growthbook as GrowthBook;
    // eslint-disable-line @typescript-eslint/no-explicit-any

    if (!gb || !gb.isOn(featureKey)) {
      return res.status(403).json({
        error: 'Forbidden',
        message: `Feature '${featureKey}' is not enabled.`,
      });
    }

    next();
  };
};

import { Request, Response, NextFunction } from 'express';

import { getAdminClient } from '../config/supabase.js';
import logger from '../services/logger.js';

export const idempotencyMiddleware = async (req: Request, res: Response, next: NextFunction) => {
  const idempotencyKey = req.headers['idempotency-key'] as string;

  if (!idempotencyKey) {
    // If no key is provided, we just proceed (or we could enforce it).
    // For now, we make it optional but highly recommended.
    return next();
  }

  const admin = await getAdminClient();
  const path = req.originalUrl;
  const method = req.method;

  try {
    // 1. Check if key exists
    const { data: existingKey, error: fetchError } = await admin
      .from('idempotency_keys')
      .select('*')
      .eq('key', idempotencyKey)
      .maybeSingle();

    if (fetchError) {
      logger.error('[Idempotency] Error fetching key:', fetchError);
      return next(); // Fail open if DB issue
    }

    if (existingKey) {
      if (existingKey.status === 'processing') {
        return res.status(409).json({
          success: false,
          message: 'A request with this idempotency key is currently processing.',
        });
      }

      // If completed, return cached response
      logger.info(`[Idempotency] Returning cached response for key: ${idempotencyKey}`);
      return res.status(existingKey.response_code || 200).json(existingKey.response_body);
    }

    // 2. Lock the key (insert as processing)
    const { error: insertError } = await admin.from('idempotency_keys').insert({
      key: idempotencyKey,
      path,
      method,
      status: 'processing',
      request_body: req.body,
    });

    if (insertError) {
      // Possible race condition: another request just inserted it
      if (insertError.code === '23505') {
        // Unique violation
        return res.status(409).json({
          success: false,
          message: 'A request with this idempotency key is currently processing.',
        });
      }
      logger.error('[Idempotency] Error inserting key:', insertError);
      return next(); // Fail open
    }

    // 3. Intercept response to save it
    const originalJson = res.json;
    res.json = function (body) {
      // Restore original json to avoid double-calling issues
      res.json = originalJson;

      // Update the DB asynchronously so it doesn't block the response
      admin
        .from('idempotency_keys')
        .update({
          status: 'completed',
          response_code: res.statusCode,
          response_body: body,
        })
        .eq('key', idempotencyKey)
        .then(({ error }: any) => {
          // eslint-disable-line @typescript-eslint/no-explicit-any
          if (error) logger.error('[Idempotency] Failed to update key status:', error);
        });

      return originalJson.call(this, body);
    };

    next();
  } catch (error) {
    logger.error('[Idempotency] Middleware error:', error);
    next();
  }
};

import { Request, Response, NextFunction } from 'express';
import { ZodError, type ZodTypeAny } from 'zod';

import { AppError } from './error.js';

export const validate = (schema: ZodTypeAny) => {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      await schema.parseAsync({
        body: req.body,
        query: req.query,
        params: req.params,
      });
      return next();
    } catch (error) {
      if (error instanceof ZodError) {
        const message = error.issues
          .map((err: any) => `${err.path.join('.')}: ${err.message}`)
          // eslint-disable-line @typescript-eslint/no-explicit-any
          .join(', ');
        return next(new AppError(message, 400));
      }
      return next(error);
    }
  };
};

import { AccountingRepository } from './accounting.repository.js';
import { Invoice, InvoiceLineItem, JournalEntry } from './accounting.types.js';
// eslint-disable-line @typescript-eslint/no-unused-vars

export class AccountingService {
  static async createInvoice(
    invoicePayload: Partial<Invoice>,
    lineItems: Partial<InvoiceLineItem>[]
  ) {
    // Basic validation
    if (!invoicePayload.type || !invoicePayload.customer_name || lineItems.length === 0) {
      throw new Error('Missing required fields for invoice creation');
    }

    if (invoicePayload.type === 'b2b' && !invoicePayload.customer_gst) {
      throw new Error('GST Number is required for B2B invoices');
    }

    // Calculate totals
    let subtotal = 0;
    let tax_total = 0;

    const processedLineItems = lineItems.map((item) => {
      const quantity = item.quantity || 1;
      const unit_price = item.unit_price || 0;
      const tax_rate = item.tax_rate || 0;

      const itemSubtotal = quantity * unit_price;
      const itemTaxAmount = (itemSubtotal * tax_rate) / 100;
      const itemTotal = itemSubtotal + itemTaxAmount;

      subtotal += itemSubtotal;
      tax_total += itemTaxAmount;

      return {
        product_id: item.product_id,
        description: item.description || 'Custom Item',
        quantity,
        unit_price,
        tax_rate,
        tax_amount: itemTaxAmount,
        total_price: itemTotal,
      };
    });

    const total = subtotal + tax_total;

    const fullInvoice: Omit<Invoice, 'id' | 'created_at' | 'updated_at'> = {
      invoice_number: invoicePayload.invoice_number || `INV-${Date.now()}`,
      type: invoicePayload.type as 'b2b' | 'b2c',
      status: invoicePayload.status || 'draft',
      customer_id: invoicePayload.customer_id,
      customer_name: invoicePayload.customer_name,
      customer_email: invoicePayload.customer_email,
      customer_phone: invoicePayload.customer_phone,
      customer_gst: invoicePayload.customer_gst,
      customer_address: invoicePayload.customer_address,
      due_date: invoicePayload.due_date,
      notes: invoicePayload.notes,
      subtotal,
      tax_total,
      total,
    };

    const createdInvoice = await AccountingRepository.createInvoice(
      fullInvoice,
      processedLineItems
    );

    // If it's sent or paid immediately, we post a journal entry
    if (createdInvoice.status !== 'draft' && createdInvoice.status !== 'cancelled') {
      await this.postInvoiceJournalEntry(
        createdInvoice.id,
        fullInvoice.invoice_number,
        total,
        invoicePayload.type as 'b2b' | 'b2c'
      );
    }

    return createdInvoice;
  }

  static async postInvoiceJournalEntry(
    invoiceId: string,
    invoiceNumber: string,
    amount: number,
    type: 'b2b' | 'b2c'
  ) {
    const description = `Auto-generated entry for ${type.toUpperCase()} Invoice ${invoiceNumber}`;

    // Debit Accounts Receivable
    await AccountingRepository.createJournalEntry({
      entry_date: new Date().toISOString(),
      account_type: 'Asset',
      account_name: 'Accounts Receivable',
      amount: amount,
      is_credit: false,
      description,
      reference_type: 'invoice',
      reference_id: invoiceId,
    });

    // Credit Sales Revenue
    await AccountingRepository.createJournalEntry({
      entry_date: new Date().toISOString(),
      account_type: 'Revenue',
      account_name: 'Sales Revenue',
      amount: amount,
      is_credit: true,
      description,
      reference_type: 'invoice',
      reference_id: invoiceId,
    });
  }

  static async getProfitLossReport() {
    return AccountingRepository.getAggregatedProfitLoss();
  }

  static async getGSTReport() {
    // Fetch all sent/paid invoices
    const b2bInvoices = await AccountingRepository.getInvoices({ type: 'b2b' });
    const b2cInvoices = await AccountingRepository.getInvoices({ type: 'b2c' });

    const aggregateTax = (invoices: any[]) => {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      return invoices
        .filter((inv) => inv.status !== 'draft' && inv.status !== 'cancelled')
        .reduce((sum, inv) => sum + Number(inv.tax_total), 0);
    };

    const aggregateSales = (invoices: any[]) => {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      return invoices
        .filter((inv) => inv.status !== 'draft' && inv.status !== 'cancelled')
        .reduce((sum, inv) => sum + Number(inv.subtotal), 0);
    };

    const b2bTax = aggregateTax(b2bInvoices);
    const b2cTax = aggregateTax(b2cInvoices);

    const b2bSales = aggregateSales(b2bInvoices);
    const b2cSales = aggregateSales(b2cInvoices);

    return {
      total_sales: b2bSales + b2cSales,
      total_tax_collected: b2bTax + b2cTax,
      breakdown: {
        b2b: { sales: b2bSales, tax: b2bTax, count: b2bInvoices.length },
        b2c: { sales: b2cSales, tax: b2cTax, count: b2cInvoices.length },
      },
    };
  }
}

