  /**
   * Send an approved template message
   */
  sendTemplate(payload: WhatsAppTemplatePayload): Promise<ProviderResponse>;

  /**
   * Send bulk messages
   */
  sendBulk?(payloads: WhatsAppMessagePayload[]): Promise<ProviderResponse[]>;

  /**
   * Get delivery status of a previously sent message
   */
  getStatus?(messageId: string): Promise<ProviderResponse>;

  /**
   * Check if the provider is healthy and ready to send
   */
  healthCheck(): Promise<boolean>;
}

import axios from 'axios';

import logger from '../../../../services/logger.js';

import {
  IWhatsAppProvider,
  ProviderResponse,
  WhatsAppMessagePayload,
  WhatsAppMediaPayload,
  WhatsAppTemplatePayload,
} from './IWhatsAppProvider.js';

export class EvolutionProvider implements IWhatsAppProvider {
  public readonly name = 'evolution';
  private baseUrl: string | null = null;
  private apiKey: string | null = null;
  private instanceName: string | null = null;

  async initialize(config?: any): Promise<void> { // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
    // Expected config: { baseUrl: 'https://wa.byteevolvr.com', apiKey: '...', instanceName: 'byteevolvr' }
    this.baseUrl = config?.baseUrl || null;
    this.apiKey = config?.apiKey || null;
    this.instanceName = config?.instanceName || null;

    if (!this.baseUrl || !this.apiKey || !this.instanceName) {
      logger.warn('[EvolutionProvider] Initialized without credentials. Messages will fail.');
    } else {
      // Ensure no trailing slash
      this.baseUrl = this.baseUrl.replace(/\/$/, '');
      logger.info('[EvolutionProvider] Initialized successfully.');
    }
  }

  async sendMessage(payload: WhatsAppMessagePayload): Promise<ProviderResponse> {
    if (!this.baseUrl || !this.apiKey || !this.instanceName) {
      return this.createErrorResponse('Missing Evolution API Credentials');
    }

    try {
      const url = `${this.baseUrl}/message/sendText/${this.instanceName}`;

      const data = {
        number: payload.to,
        options: {
          delay: 1200,
          presence: 'composing',
        },
        text: payload.content || '',
      };

      const response = await axios.post(url, data, this.getHeaders());
      return this.createSuccessResponse(response.data?.key?.id); // eslint-disable-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(
        '[EvolutionProvider] Error sending text message:',
        error.response?.data || error.message
      );
      return this.createErrorResponse(this.extractErrorMessage(error));
    }
  }

  async sendMedia(payload: WhatsAppMediaPayload): Promise<ProviderResponse> {
    if (!this.baseUrl || !this.apiKey || !this.instanceName) {
      return this.createErrorResponse('Missing Evolution API Credentials');
    }

    try {
      const url = `${this.baseUrl}/message/sendMedia/${this.instanceName}`;

      const data = {
        number: payload.to,
        options: {
          delay: 1200,
          presence: 'composing',
        },
        mediaMessage: {
          mediatype: payload.mimeType?.includes('pdf') ? 'document' : 'image',
          caption: payload.caption || '',
          media: payload.mediaUrl, // URL to the media
          fileName: payload.fileName || 'file',
        },
      };

      const response = await axios.post(url, data, this.getHeaders()); // eslint-disable-line @typescript-eslint/no-explicit-any
      return this.createSuccessResponse(response.data?.key?.id);
    } catch (error: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(
        '[EvolutionProvider] Error sending media message:',
        error.response?.data || error.message
      );
      return this.createErrorResponse(this.extractErrorMessage(error));
    } // eslint-disable-line @typescript-eslint/no-unused-vars
  }

  async sendTemplate(payload: WhatsAppTemplatePayload): Promise<ProviderResponse> {
    // eslint-disable-line @typescript-eslint/no-unused-vars
    // Evolution API typically relies on Meta Cloud for official templates if configured,
    // or standard messages if running a normal WhatsApp Web session.
    // Assuming standard implementation if Evolution is linked to an official WABA.
    logger.warn(
      '[EvolutionProvider] Template sending via Evolution API is limited. Ensure WABA configuration.'
    );
    return this.createErrorResponse(
      'Template messaging requires specific Evolution API WABA configuration.'
    );
  }

  async healthCheck(): Promise<boolean> {
    if (!this.baseUrl || !this.apiKey || !this.instanceName) return false;
    try {
      // Check instance connection state
      const url = `${this.baseUrl}/instance/connectionState/${this.instanceName}`;
      const response = await axios.get(url, this.getHeaders());
      return response.data?.instance?.state === 'open';
    } catch (error) {
      logger.error('[EvolutionProvider] Health check failed:', error);
      return false;
    }
  }

  private getHeaders() {
    return {
      headers: {
        apikey: this.apiKey,
        'Content-Type': 'application/json',
      },
    };
  }

  private createSuccessResponse(messageId: string): ProviderResponse {
    return {
      success: true,
      provider: this.name,
      messageId: messageId || `evo-${Date.now()}`,
      status: 'sent',
    };
  }

  private createErrorResponse(error: string): ProviderResponse {
    return {
      success: false,
      provider: this.name,
      error,
      status: 'failed', // eslint-disable-line @typescript-eslint/no-explicit-any
    };
  }

  private extractErrorMessage(error: any): string {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    if (error.response?.data) {
      const data = error.response.data;
      if (data.response?.message?.[0]?.exists === false) {
        return 'Recipient number is not registered on WhatsApp';
      }
      if (data.message) {
        return typeof data.message === 'string' ? data.message : JSON.stringify(data.message);
      }
      if (data.error) {
        return typeof data.error === 'string' ? data.error : JSON.stringify(data.error);
      }
    }
    return error.message || 'Unknown Evolution API Error';
  }
}

import axios from 'axios';

import logger from '../../../../services/logger.js';

import {
  IWhatsAppProvider,
  ProviderResponse,
  WhatsAppMessagePayload,
  WhatsAppMediaPayload,
  WhatsAppTemplatePayload,
} from './IWhatsAppProvider.js';

export class MetaCloudProvider implements IWhatsAppProvider {
  public readonly name = 'meta';
  private accessToken: string | null = null;
  private phoneNumberId: string | null = null;

  async initialize(config?: any): Promise<void> { // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
    this.accessToken = config?.accessToken || process.env.WHATSAPP_ACCESS_TOKEN || null;
    this.phoneNumberId = config?.phoneNumberId || process.env.WHATSAPP_PHONE_NUMBER_ID || null;

    if (!this.accessToken || !this.phoneNumberId) {
      logger.warn('[MetaCloudProvider] Initialized without credentials. Messages will fail.');
    } else {
      logger.info('[MetaCloudProvider] Initialized successfully.');
    }
  }

  async sendMessage(payload: WhatsAppMessagePayload): Promise<ProviderResponse> {
    if (!this.accessToken || !this.phoneNumberId) {
      return this.createErrorResponse('Missing Cloud API Credentials');
    }

    try {
      const url = `https://graph.facebook.com/v19.0/${this.phoneNumberId}/messages`;
      const data = {
        messaging_product: 'whatsapp',
        to: payload.to,
        type: 'text',
        text: { body: payload.content || '' },
      };

      const response = await axios.post(url, data, this.getHeaders());
      return this.createSuccessResponse(response.data?.messages?.[0]?.id); // eslint-disable-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(
        '[MetaCloudProvider] Error sending text message:',
        error.response?.data || error.message
      );
      return this.createErrorResponse(error.response?.data?.error?.message || error.message);
    }
  }

  async sendMedia(payload: WhatsAppMediaPayload): Promise<ProviderResponse> {
    if (!this.accessToken || !this.phoneNumberId) {
      return this.createErrorResponse('Missing Cloud API Credentials');
    }

    try {
      const url = `https://graph.facebook.com/v19.0/${this.phoneNumberId}/messages`;

      // Basic detection for document vs image based on mimeType/url extension.
      // Assuming 'image' as default if not specified.
      const isDocument = payload.mimeType?.includes('pdf') || payload.fileName;
      const mediaType = isDocument ? 'document' : 'image'; // eslint-disable-line @typescript-eslint/no-explicit-any

      const data: any = {
        // eslint-disable-line @typescript-eslint/no-explicit-any
        messaging_product: 'whatsapp',
        to: payload.to,
        type: mediaType,
      };

      data[mediaType] = { link: payload.mediaUrl };
      if (payload.caption) data[mediaType].caption = payload.caption;
      if (payload.fileName && isDocument) data[mediaType].filename = payload.fileName;
 // eslint-disable-line @typescript-eslint/no-explicit-any
      const response = await axios.post(url, data, this.getHeaders());
      return this.createSuccessResponse(response.data?.messages?.[0]?.id);
    } catch (error: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(
        '[MetaCloudProvider] Error sending media message:',
        error.response?.data || error.message
      );
      return this.createErrorResponse(error.response?.data?.error?.message || error.message);
    }
  }

  async sendTemplate(payload: WhatsAppTemplatePayload): Promise<ProviderResponse> {
    if (!this.accessToken || !this.phoneNumberId) {
      return this.createErrorResponse('Missing Cloud API Credentials');
    }

    try {
      const url = `https://graph.facebook.com/v19.0/${this.phoneNumberId}/messages`;

      const data = {
        messaging_product: 'whatsapp',
        to: payload.to,
        type: 'template',
        template: {
          name: payload.templateId,
          language: { code: payload.languageCode || 'en_US' },
          components: payload.components || [],
        },
      }; // eslint-disable-line @typescript-eslint/no-explicit-any

      const response = await axios.post(url, data, this.getHeaders());
      return this.createSuccessResponse(response.data?.messages?.[0]?.id);
    } catch (error: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      logger.error(
        '[MetaCloudProvider] Error sending template message:',
        error.response?.data || error.message
      );
      return this.createErrorResponse(error.response?.data?.error?.message || error.message);
    }
  }

  async healthCheck(): Promise<boolean> {
    if (!this.accessToken || !this.phoneNumberId) return false;
    try {
      const url = `https://graph.facebook.com/v19.0/${this.phoneNumberId}?fields=verified_name,display_phone_number`;
      const response = await axios.get(url, this.getHeaders());
      return !!response.data?.id;
    } catch (e) {
      logger.warn('[MetaCloudProvider] Health check failed:', e);
      return false;
    }
  }

  private getHeaders() {
    return {
      headers: {
        Authorization: `Bearer ${this.accessToken}`,
        'Content-Type': 'application/json',
      },
    };
  }

  private createSuccessResponse(messageId: string): ProviderResponse {
    return {
      success: true,
      provider: this.name,
      messageId,
      status: 'sent',
    };
  }

  private createErrorResponse(error: string): ProviderResponse {
    return {
      success: false,
      provider: this.name,
      error,
      status: 'failed',
    };
  }
}

import { getAdminClient } from '../../../../config/supabase.js';
import logger from '../../../../services/logger.js';

import {
  IWhatsAppProvider,
  ProviderResponse,
  WhatsAppMessagePayload,
} from './IWhatsAppProvider.js';
import { MetaCloudProvider } from './metaCloudProvider.js';
import { EvolutionProvider } from './evolutionProvider.js';

export class WhatsAppProviderFactory {
  private providers: Map<string, IWhatsAppProvider> = new Map();
  private defaultProviderName: 'meta' | 'evolution' = 'meta';

  constructor() {
    this.providers.set('meta', new MetaCloudProvider());
    this.providers.set('evolution', new EvolutionProvider());
  }

  /**
   * Initializes all enabled providers from the DB config.
   */
  async initializeProviders(): Promise<void> {
    try {
      const admin = await getAdminClient();
      const { data: configs, error } = await admin
        .from('provider_configs')
        .select('*')
        .eq('is_enabled', true)
        .order('priority', { ascending: true });

      if (error) {
        logger.error('[WhatsAppProviderFactory] Failed to fetch provider configs:', error);
        return;
      }

      if (configs && configs.length > 0) {
        // The highest priority enabled provider becomes default
        this.defaultProviderName = configs[0].provider_name as any; // eslint-disable-line @typescript-eslint/no-explicit-any
        // eslint-disable-line @typescript-eslint/no-explicit-any

        for (const config of configs) {
          const provider = this.providers.get(config.provider_name);
          if (provider) {
            await provider.initialize(config.config);
          }
        }
      }
    } catch (err) {
      logger.error('[WhatsAppProviderFactory] Init error:', err);
    }
  }

  /**
   * Resolves the primary provider based on override or default.
   */
  getProvider(providerNameOverride?: string): IWhatsAppProvider {
    if (providerNameOverride && this.providers.has(providerNameOverride)) {
      return this.providers.get(providerNameOverride)!;
    }
    return this.providers.get(this.defaultProviderName)!;
  }

  /**
   * Orchestrates sending a message with automatic failover.
   * If the primary provider fails, it attempts the next available enabled provider.
   */
  async sendWithFailover(
    payload: WhatsAppMessagePayload,
    type: 'text' | 'media' | 'template' = 'text',
    providerOverride?: string
  ): Promise<ProviderResponse> {
    const admin = await getAdminClient();

    // Determine sequence
    const primaryName = providerOverride || this.defaultProviderName;
    const primaryProvider = this.providers.get(primaryName)!;

    const response = await this.executeSend(primaryProvider, payload, type);

    if (response.success) {
      return response;
    }

    // --- FAILOVER LOGIC ---
    logger.warn(
      `[WhatsAppProviderFactory] Primary provider (${primaryName}) failed. Attempting failover.`
    );

    await this.logProviderEvent(
      primaryName,
      'failover',
      `Primary provider failed: ${response.error}`
    );

    // Fetch fallback providers (enabled, excluding the primary)
    const { data: fallbacks } = await admin
      .from('provider_configs')
      .select('provider_name')
      .eq('is_enabled', true)
      .neq('provider_name', primaryName)
      .order('priority', { ascending: true });

    if (!fallbacks || fallbacks.length === 0) {
      logger.error('[WhatsAppProviderFactory] No fallback providers available.');
      return response; // Return original failure
    }

    for (const fallback of fallbacks) {
      const fallbackProvider = this.providers.get(fallback.provider_name);
      if (!fallbackProvider) continue;

      logger.info(`[WhatsAppProviderFactory] Trying fallback provider: ${fallback.provider_name}`);

      const fallbackResponse = await this.executeSend(fallbackProvider, payload, type);

      if (fallbackResponse.success) {
        logger.info(`[WhatsAppProviderFactory] Failover to ${fallback.provider_name} succeeded.`);
        return fallbackResponse;
      } else {
        await this.logProviderEvent(
          fallback.provider_name,
          'failover_failed',
          fallbackResponse.error
        );
      }
    }

    return response; // All failed, return primary failure
  }

  private async executeSend(
    provider: IWhatsAppProvider,
    payload: WhatsAppMessagePayload,
    type: 'text' | 'media' | 'template'
  ): Promise<ProviderResponse> {
    switch (type) {
      case 'media': // eslint-disable-line @typescript-eslint/no-explicit-any
        return provider.sendMedia(payload as any);
      // eslint-disable-line @typescript-eslint/no-explicit-any
      case 'template':
        return provider.sendTemplate(payload as any);
      // eslint-disable-line @typescript-eslint/no-explicit-any
      default:
        return provider.sendMessage(payload);
    }
  }

  private async logProviderEvent(providerName: string, eventType: string, message?: string) {
    try {
      const admin = await getAdminClient();
      await admin.from('provider_logs').insert({
