import { getAdminClient } from '../../config/supabase.js';
import { AppError } from '../../middlewares/error.js';

export class SegmentService {
  /**
   * Get all defined audience segments
   */
  async getSegments() {
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('audience_segments')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data;
  }

  /**
   * Create a new audience segment
   */
  async createSegment(payload: Record<string, any>) { // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();

    // Estimate count before saving
    const count = await this.estimateAudienceCount(payload.filter_rules);

    const { data, error } = await admin
      .from('audience_segments')
      .insert({
        ...payload,
        estimated_count: count,
        created_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  }

  /**
   * Run the filter rules against the users/orders tables to count matching users
   */ // eslint-disable-line @typescript-eslint/no-explicit-any
  async estimateAudienceCount(filterRules: any): Promise<number> {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();

    if (filterRules?.type === 'all') {
      const { count } = await admin.from('users').select('*', { count: 'exact', head: true });
      return count || 0;
    }

    let query = admin.from('users').select('*', { count: 'exact', head: true });
    query = this.applyRulesToQuery(query, filterRules);

    const { count, error } = await query;
    if (error) {
      console.error('[SegmentService] Error estimating count:', error);
      return 0;
    }
    return count || 0;
  }

  /**
   * Translates JSON rules into Supabase PostgREST query builders // eslint-disable-line @typescript-eslint/no-explicit-any
   */
  private applyRulesToQuery(query: any, filterRules: any) {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    if (!filterRules || !filterRules.rules || !Array.isArray(filterRules.rules)) {
      return query;
    }

    // Example rule format: { field: 'email', operator: 'like', value: '%@gmail.com' }
    for (const rule of filterRules.rules) {
      const { field, operator, value } = rule;
      switch (operator) {
        case 'eq':
          query = query.eq(field, value);
          break;
        case 'neq':
          query = query.neq(field, value);
          break;
        case 'gt':
          query = query.gt(field, value);
          break;
        case 'gte':
          query = query.gte(field, value);
          break;
        case 'lt':
          query = query.lt(field, value);
          break;
        case 'lte':
          query = query.lte(field, value);
          break;
        case 'like':
          query = query.ilike(field, value); // Using case-insensitive like
          break;
        case 'in':
          query = query.in(field, Array.isArray(value) ? value : [value]);
          break;
        default:
          break;
      }
    }
    return query;
  }

  /** // eslint-disable-line @typescript-eslint/no-explicit-any
   * Fetch actual user emails/phones based on a segment ID
   */
  async resolveSegmentUsers(segmentId: string): Promise<any[]> {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();

    const { data: segment, error: segError } = await admin
      .from('audience_segments')
      .select('*')
      .eq('id', segmentId)
      .single();

    if (segError || !segment) {
      throw new AppError('Segment not found', 404);
    }

    if (segment.filter_rules?.type === 'all') {
      const { data: users } = await admin.from('users').select('id, email, phone, metadata');
      return users || [];
    }

    let query = admin.from('users').select('id, email, phone, metadata');
    query = this.applyRulesToQuery(query, segment.filter_rules);

    const { data: users, error: queryError } = await query;
    if (queryError) {
      throw new AppError(`Failed to resolve segment users: ${queryError.message}`, 500);
    }

    return users || [];
  }
}

import { getAdminClient } from '../../../config/supabase.js';
import { JobService } from '../../../services/jobService.js';
import { WhatsAppService } from '../../whatsapp/whatsapp.service.js';
import { TemplateEngine } from '../../../core/template/TemplateEngine.js';
import logger from '../../../services/logger.js';
import { FlowStep } from '../../../core/contracts/automation.js';

export class AutomationRunnerService {
  /**
   * Executes a specific step in an automation flow run
   */
  async executeStep( // eslint-disable-line complexity
    // eslint-disable-line complexity
    runId: string,
    flowId: string,
    stepIndex: number
  ): Promise<{ nextStepIndex?: number; delayMs: number }> {
    const admin = await getAdminClient();

    const [flowRes, runRes] = await Promise.all([
      admin.from('automation_flows').select('*').eq('id', flowId).single(),
      admin.from('automation_runs').select('*').eq('id', runId).single(),
    ]);

    if (flowRes.error || !flowRes.data) throw new Error('Flow not found');
    if (runRes.error || !runRes.data) throw new Error('Run not found');

    const flow = flowRes.data;
    const run = runRes.data;

    if (run.status !== 'active') {
      logger.info(`[AutomationRunner] Run ${runId} is no longer active.`);
      return { delayMs: 0 };
    }

    const steps: FlowStep[] = flow.flow_steps || [];
    if (stepIndex >= steps.length) {
      await admin.from('automation_runs').update({ status: 'completed' }).eq('id', runId);
      logger.info(`[AutomationRunner] Flow run ${runId} completed.`);
      return { delayMs: 0 };
    }

    const currentStep = steps[stepIndex];
    const nextStepIndex = stepIndex + 1;
    let delayMs = 0;

    switch (currentStep.type) {
      case 'action_email': {
        const emailAddress = run.trigger_data?.email;
        if (emailAddress) {
          const rawSubject = currentStep.config?.subject || 'Update from ByteEvolvr';
          const rawContent = currentStep.config?.content || 'Here is your update.';
          await JobService.sendEmail(
            emailAddress,
            TemplateEngine.render(rawSubject, run.trigger_data),
            TemplateEngine.render(rawContent, run.trigger_data)
          );
        }
        break;
      }
      case 'action_whatsapp': {
        const phone = run.trigger_data?.phone;
        if (phone) {
          const rawContent = currentStep.config?.content || 'ByteEvolvr Notification';
          await WhatsAppService.enqueueMessage(phone, {
            content: TemplateEngine.render(rawContent, run.trigger_data),
            type: 'text',
          });
        }
        break;
      }
      case 'condition_delay': {
        const minutes = currentStep.config?.delayMinutes || 0;
        delayMs = minutes * 60 * 1000;
        logger.info(`[AutomationRunner] Run ${runId} delaying next step by ${minutes} minutes.`);
        break;
      }
      default:
        logger.warn(`[AutomationRunner] Unknown node type ${currentStep.type} in flow ${flowId}`);
        break;
    }

    await admin
      .from('automation_runs')
      .update({ current_step_index: nextStepIndex })
      .eq('id', runId);

    if (nextStepIndex >= steps.length) {
      await admin.from('automation_runs').update({ status: 'completed' }).eq('id', runId);
      logger.info(`[AutomationRunner] Flow run ${runId} completed.`);
      return { delayMs: 0 };
    }

    return { nextStepIndex, delayMs };
  }
}

