      tags: Array.isArray(data.tags) ? data.tags : data.tags ? [data.tags] : [],
      slug: data.slug || slugify(data.name || 'product'),
      variants: data.variants || [],
    }));

    return await productRepo.bulkCreate(sanitizedProducts, userId);
