      .single();

    if (poError || !po) throw new AppError('PO not found', 404); // eslint-disable-line @typescript-eslint/no-explicit-any
    return po;
  }

  async createPurchaseOrder(poData: any) {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();
    const { data: po, error: poError } = await admin
      .from('purchase_orders')
      .insert(poData)
      .select()
      .single();
 // eslint-disable-line @typescript-eslint/no-explicit-any
    if (poError || !po) throw new AppError('Failed to create PO', 500);
