export const getTasks = async (req: Request, res: Response) => {
  try {
    const jobs = await whatsappQueue.getJobs([
      'waiting',
      'active',
      'completed',
      'failed',
      'delayed',
    ]);
    // Filter to only return necessary data to avoid giant payloads
    const formattedJobs = jobs.map((j) => ({ // eslint-disable-line @typescript-eslint/no-unused-vars
      // eslint-disable-line @typescript-eslint/no-unused-vars
      id: j.id,
      name: j.name,
      data: j.data,
      opts: j.opts,
      progress: j.progress,
      delay: j.delay,
      timestamp: j.timestamp,
      finishedOn: j.finishedOn,
      processedOn: j.processedOn,
      returnvalue: j.returnvalue,
      failedReason: j.failedReason,
      stacktrace: j.stacktrace,
      attemptsMade: j.attemptsMade,
      isFailed: !!j.failedReason,
    }));

    // Determine status for UI
    const result = await Promise.all(
      jobs.map(async (j) => {
        const state = await j.getState();
        return {
          id: j.id,
          name: j.name,
          data: j.data,
          state,
          failedReason: j.failedReason,
          timestamp: j.timestamp,
          attemptsMade: j.attemptsMade,
        };
      })
    );
    res.json({ success: true, data: result });
  } catch (error) {
    logger.error('[WhatsAppController] Error getting tasks:', error);
    res.status(500).json({ success: false, message: 'Failed to get tasks' });
  }
};

