export const updateProvider = async (req: Request, res: Response) => {
  try {
    const { provider_name, is_enabled, priority, config } = req.body;
    if (!provider_name)
      return res.status(400).json({ success: false, message: 'provider_name is required' });

    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('provider_configs')
      .upsert(
        {
          provider_name,
          is_enabled,
          priority,
          config,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'provider_name' }
      )
      .select()
      .single();

    if (error) throw error;
    res.json({ success: true, data });
  } catch (error) {
    logger.error('[WhatsAppController] Error updating provider:', error);
    res.status(500).json({ success: false, message: 'Failed to update provider settings' });
  }
};

import { getAdminClient } from '../../config/supabase.js';
import logger from '../../services/logger.js';

import { WhatsAppMessageRecord, WhatsAppSession } from './whatsapp.types.js';

export class WhatsAppRepository {
  async getSession(sessionName: string = 'default'): Promise<WhatsAppSession | null> {
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('whatsapp_sessions')
      .select('*')
      .eq('session_name', sessionName)
      .maybeSingle();

    if (error) {
      logger.error('[WhatsAppRepository] Error getting session:', error);
      return null;
    }
    return data;
  }

  async updateSessionState(sessionName: string, state: Partial<WhatsAppSession>) {
    const admin = await getAdminClient();
    const { data: existing, error: selectErr } = await admin
      .from('whatsapp_sessions')
      .select('id')
      .eq('session_name', sessionName)
      .maybeSingle();

    if (selectErr) {
      logger.error('[WhatsAppRepository] Error checking existing session:', selectErr);
    }

    if (existing) {
      const { error: updateErr } = await admin
        .from('whatsapp_sessions')
        .update({
          ...state,
          updated_at: new Date().toISOString(),
          last_active: new Date().toISOString(),
        })
        .eq('id', existing.id);
      if (updateErr) logger.error('[WhatsAppRepository] Error updating session:', updateErr);
    } else {
      const { error: insertErr } = await admin.from('whatsapp_sessions').insert({
        session_name: sessionName,
        ...state,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        last_active: new Date().toISOString(),
      });
      if (insertErr) logger.error('[WhatsAppRepository] Error inserting session:', insertErr);
    }
  }

  async createMessageRecord(
    record: Partial<WhatsAppMessageRecord>
  ): Promise<WhatsAppMessageRecord> {
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('whatsapp_messages')
      .insert({
        ...record,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  }

  async updateMessageStatus(
    id: string,
    status: 'sent' | 'failed' | 'delivered',
    errorLog?: string
  ) {
    const admin = await getAdminClient();
    const { error } = await admin
      .from('whatsapp_messages')
      .update({
        status,
        error_log: errorLog || null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', id);

    if (error) {
      logger.error(`[WhatsAppRepository] Failed to update message ${id} status:`, error);
    }
  }

  async updateMessageStatusByExternalId(
    externalId: string,
    status: 'sent' | 'failed' | 'delivered',
    errorLog?: string
  ) {
    const admin = await getAdminClient();
    const { error } = await admin
      .from('whatsapp_messages')
      .update({
        status,
        error_log: errorLog || null,
        updated_at: new Date().toISOString(),
      })
      .eq('external_id', externalId);

    if (error) {
      logger.error(
        `[WhatsAppRepository] Failed to update message by external ID ${externalId} status:`,
        error
      );
    }
  }

  async logEvent(level: 'info' | 'error' | 'warn', message: string, meta?: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();
    await admin.from('whatsapp_logs').insert({
      level,
      message,
      meta,
      created_at: new Date().toISOString(),
    });
  }

  async getRecentMessages(page: number = 1, limit: number = 50) {
    const admin = await getAdminClient();
    const offset = (page - 1) * limit;

    const { data, count, error } = await admin
      .from('whatsapp_messages')
      .select('*', { count: 'exact' })
      .order('created_at', { ascending: false })
      .range(offset, offset + limit - 1);

    if (error) throw error;
    return { data, count: count || 0, page, limit };
  }

  async getSystemStatus() {
    const admin = await getAdminClient();
    const { data: session } = await admin
      .from('whatsapp_sessions')
      .select('*')
      .eq('session_name', 'default')
      .maybeSingle();
    const { count: failedCount } = await admin
      .from('whatsapp_messages')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'failed');

    return {
      session: session || null,
      failedCount: failedCount || 0,
    };
  }

  async updateSessionLastActive() {
    const admin = await getAdminClient();
    await admin
      .from('whatsapp_sessions')
      .update({ last_active: new Date().toISOString() })
      .eq('session_name', 'default');
  }

  // --- Templates Management ---

  async getTemplates() {
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('whatsapp_templates')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data;
  }

  async getTemplateById(id: string) {
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('whatsapp_templates')
      .select('*')
      .eq('id', id)
      .single();

    if (error) throw error;
    return data;
  }

  async createTemplate(template: {
    name: string;
    content: string; // eslint-disable-line @typescript-eslint/no-explicit-any
    variables: any[];
    // eslint-disable-line @typescript-eslint/no-explicit-any
    is_active?: boolean;
  }) {
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('whatsapp_templates')
      .insert({
        ...template,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  } // eslint-disable-line @typescript-eslint/no-explicit-any

  async updateTemplate(id: string, updates: any) {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();
    const { data, error } = await admin
      .from('whatsapp_templates')
      .update({ ...updates, updated_at: new Date().toISOString() })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data;
  }

  async deleteTemplate(id: string) {
    const admin = await getAdminClient();
    const { error } = await admin.from('whatsapp_templates').delete().eq('id', id);

    if (error) throw error;
  }
}

import { whatsappQueue } from '../../jobs/whatsapp.queue.js';
import logger from '../../services/logger.js';

import { WhatsAppMessagePayload } from './whatsapp.types.js';
import { WhatsAppRepository } from './whatsapp.repository.js';

const repository = new WhatsAppRepository();

export class WhatsAppService {
  /**
   * Enqueues a WhatsApp message to be sent asynchronously by the worker.
   */
  static async enqueueMessage(
    to: string,
    payload: Omit<WhatsAppMessagePayload, 'to'>,
    priority: number = 0
  ) {
    logger.info(`[WhatsAppService] Enqueueing message for ${to}`);

    // Create DB Record first for tracking
    const record = await repository.createMessageRecord({
      recipient: to,
      payload,
      status: 'queued',
    });

    const isServerlessOrProd =
      !!process.env.VERCEL || !!process.env.RENDER || process.env.NODE_ENV === 'production';

    if (isServerlessOrProd) {
      logger.info(
        `[WhatsAppService] Running in serverless/production environment. Processing synchronously to guarantee delivery.`
      );
      try {
        const { WhatsAppProviderFactory } =
          await import('../marketing/providers/whatsapp/whatsappProviderFactory.js');
        const providerFactory = new WhatsAppProviderFactory();
        await providerFactory.initializeProviders();

        let type: 'text' | 'media' | 'template' = 'text';
        if (payload.type === 'template') type = 'template';
        if (payload.type === 'image' || payload.type === 'document') type = 'media';

        const providerPayload: any = { // eslint-disable-line @typescript-eslint/no-explicit-any
          // eslint-disable-line @typescript-eslint/no-explicit-any
          to,
          content: payload.content || '',
          metadata: payload,
        };

        if (type === 'media') { // eslint-disable-line @typescript-eslint/no-explicit-any
          providerPayload.mediaUrl = (payload as any).mediaUrl;
          // eslint-disable-line @typescript-eslint/no-explicit-any
          providerPayload.caption = payload.content; // eslint-disable-line @typescript-eslint/no-explicit-any
          providerPayload.fileName = (payload as any).fileName;
          // eslint-disable-line @typescript-eslint/no-explicit-any
          providerPayload.mimeType = (payload as any).mimeType; // eslint-disable-line @typescript-eslint/no-explicit-any
          // eslint-disable-line @typescript-eslint/no-explicit-any
        } else if (type === 'template') {
          providerPayload.templateId = (payload as any).templateId;
          // eslint-disable-line @typescript-eslint/no-explicit-any
          providerPayload.languageCode = (payload as any).languageCode;
          // eslint-disable-line @typescript-eslint/no-explicit-any
          providerPayload.components = (payload as any).components;
          // eslint-disable-line @typescript-eslint/no-explicit-any
        }

        const result = await providerFactory.sendWithFailover(providerPayload, type);

        if (!result.success) {
          logger.warn(`[WhatsAppService] Sync send failed with error: ${result.error}`);
          await repository.updateMessageStatus(record.id, 'failed', result.error);
        } else {
          logger.info(`[WhatsAppService] Sync send succeeded with ID: ${result.messageId}`);
          await repository.updateMessageStatus(record.id, 'sent');
          const admin = await import('../../config/supabase.js').then((m) => m.getAdminClient());
          await admin
            .from('whatsapp_messages')
            .update({ // eslint-disable-line @typescript-eslint/no-explicit-any
              provider_used: result.provider,
              external_id: result.messageId,
              updated_at: new Date().toISOString(),
            })
            .eq('id', record.id);
        }
      } catch (error: any) {
        // eslint-disable-line @typescript-eslint/no-explicit-any
        logger.error(`[WhatsAppService] Unhandled sync send error:`, error);
        await repository.updateMessageStatus(record.id, 'failed', error.message);
      }
      return record;
    }

    // Add to BullMQ for local / traditional daemon environments
    await whatsappQueue.add(
      'send-message',
      {
        jobId: record.id,
        to,
        payload: { ...payload, to },
      },
      {
        jobId: `wa-${record.id}`, // Dedup key: BullMQ will reject any duplicate with the same ID
        priority,
        attempts: 2, // 1 try + 1 retry — 3 was showing as 4 entries in queue
        backoff: { type: 'exponential', delay: 3000 },
      }
    );

    // Update DB with BullMQ Job ID
    return record;
  }

  static async getStatus() {
    return repository.getSystemStatus();
  }

  static async getLogs(page: number = 1, limit: number = 50) {
    return repository.getRecentMessages(page, limit);
  }
}

export interface WhatsAppMessagePayload {
  to: string;
  content: string;
  type?: 'text' | 'image' | 'document' | 'template';
  mediaUrl?: string;
  templateId?: string;
  variables?: Record<string, string>;
}

export interface WhatsAppJobData {
  jobId?: string;
  payload: WhatsAppMessagePayload;
  priority?: number;
}

export interface WhatsAppSession {
  id: string;
  session_name: string;
  status: 'connected' | 'disconnected' | 'authenticating' | 'qr_ready';
  qr_code?: string;
  last_active: string;
  created_at: string;
  updated_at: string;
}

export interface WhatsAppMessageRecord {
  id: string;
  job_id?: string;
  recipient: string;
  payload: Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  // eslint-disable-line @typescript-eslint/no-explicit-any
  status: 'queued' | 'sent' | 'failed' | 'delivered';
  error_log?: string;
  created_at: string;
  updated_at: string;
}

