import { emailQueue, notificationQueue, analyticsQueue } from '../core/queues/index.js';
import { redis } from '../config/redis.js';

import { EmailService } from './email.js';
import { NotificationService } from './notificationService.js';
import logger from './logger.js';

export class JobService {
  private static isRedisAvailable(): boolean {
    return redis.status === 'ready';
  }

  static async sendEmail(to: string, subject: string, html: string) {
    if (this.isRedisAvailable()) {
      try {
        await emailQueue.add(
          'send-email',
          { to, subject, html },
          {
            attempts: 3,
            backoff: { type: 'exponential', delay: 1000 },
          }
        );
        logger.info(`[JobService] Email to ${to} queued.`);
        return;
      } catch (err) {
        logger.error('[JobService] Failed to queue email, falling back to sync:', err);
      }
    }

    // Fallback to synchronous sending
    logger.warn(`[JobService] Redis unavailable. Sending email to ${to} synchronously.`);
    return EmailService.sendEmail(to, subject, html);
  }

  static async sendNotification(data: {
    userId?: string;
    title: string;
    message: string;
    type: 'info' | 'success' | 'warning' | 'error';
    priority?: 'low' | 'medium' | 'high';
    metadata?: any; // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
  }) {
    if (this.isRedisAvailable()) {
      try {
        await notificationQueue.add('send-notification', data);
        logger.info(`[JobService] Notification "${data.title}" queued.`);
        return;
      } catch (err) {
        logger.error('[JobService] Failed to queue notification, falling back to sync:', err);
      }
    }

    // Fallback to synchronous sending
    logger.warn(
      `[JobService] Redis unavailable. Sending notification "${data.title}" synchronously.`
    );
    return NotificationService.send(data);
  }
 // eslint-disable-line @typescript-eslint/no-explicit-any
  static async dispatchAnalyticsEvent(type: string, payload: Record<string, any>) {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    if (this.isRedisAvailable()) {
      try {
        await analyticsQueue.add(
          'record-event',
          { type, payload },
          {
            attempts: 5,
            backoff: { type: 'exponential', delay: 2000 },
          }
        );
        logger.info(`[JobService] Analytics event '${type}' queued.`);
        return;
      } catch (err) {
        logger.error('[JobService] Failed to queue analytics event:', err);
      }
    } else {
      logger.warn(`[JobService] Redis unavailable. Analytics event '${type}' ignored.`);
    }
  }
}

import { getAdminClient } from '../config/supabase.js';

import logger from './logger.js';

export class NotificationService {
  static async send(data: {
    userId?: string; // If empty, consider it a system-wide admin notification
    title: string;
    message: string;
    type: 'info' | 'success' | 'warning' | 'error';
    priority?: 'low' | 'medium' | 'high';
    metadata?: any; // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
  }) {
    logger.info(`Notification [${data.type}]: ${data.title} - ${data.message}`);

    try {
      const admin = await getAdminClient();
      await admin.from('notifications').insert({
        user_id: data.userId,
        title: data.title,
        message: data.message,
        type: data.type,
        priority: data.priority || 'medium',
        metadata: data.metadata,
        is_read: false,
        created_at: new Date().toISOString(),
      });

      // Real-time broadcast (via Supabase Realtime or Socket.io)
      // This is handled automatically by Supabase if the client subscribes to 'notifications'
    } catch (err) {
      logger.error('Failed to persist notification:', err);
    }
  }

  static async notifyLowStock(productName: string, warehouseName: string, currentStock: number) {
    await this.send({
      title: 'Low Stock Alert',
      message: `${productName} in ${warehouseName} is running low (${currentStock} left).`,
      type: 'warning',
      priority: 'high',
      metadata: { module: 'inventory', warehouse: warehouseName },
    });
  }

  static async notifyOrderEvent(orderNumber: string, status: string, notes?: string) {
    const isCritical = ['cancelled', 'returned'].includes(status);
    await this.send({
      title: `Order ${status.toUpperCase()}`,
      message: `Order #${orderNumber} has been ${status}.${notes ? ` Note: ${notes}` : ''}`,
      type: isCritical ? 'error' : 'info',
      priority: isCritical ? 'high' : 'medium',
      metadata: { module: 'orders', orderNumber },
    });
  }
}

