export class PdfService {
  /**
   * Generates a professional tax invoice PDF for an order
   */ // eslint-disable-line complexity // eslint-disable-line @typescript-eslint/no-explicit-any
  static async generateInvoice(order: any, res: Response) {
    // eslint-disable-line complexity
    const doc = new PDFDocument({ margin: 50, size: 'A4' });

    // Stream the PDF to the response
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename=invoice-${order.order_number}.pdf`);
    doc.pipe(res);

    // --- Header ---
    doc.fillColor('#3b82f6').fontSize(24).text('ByteEvolvr', 50, 50);
    doc.fillColor('#444444').fontSize(10).text('101, Tech Park, Andheri East', 50, 80);
    doc.text('Mumbai, MH 400069', 50, 95);
    doc.text('Phone: +91 99999 88888', 50, 110);
    doc.text('GSTIN: 27AABCB1234F1Z5', 50, 125);

    doc.fillColor('#000000').fontSize(20).text('TAX INVOICE', 400, 50, { align: 'right' });
    doc.fontSize(10).text(`Invoice #: ${order.order_number}`, 400, 80, { align: 'right' });
    doc.text(`Date: ${new Date(order.created_at).toLocaleDateString()}`, 400, 95, {
      align: 'right',
    });

    doc.moveTo(50, 150).lineTo(550, 150).stroke();

    // --- Addresses ---
    doc.fontSize(12).font('Helvetica-Bold').text('Billed To:', 50, 170);
    const billing = {
      name: order.customer_name || 'Walk-in Customer',
      email: order.customer_email || '',
    };
    doc.fontSize(10).font('Helvetica').text(billing.name, 50, 185);
    doc.text(billing.email, 50, 200);

    // Shipping Address Resolution
    let shipping = order.shipping_address;
    if (!shipping && order.addresses) {
      shipping = Array.isArray(order.addresses) ? order.addresses[0] : order.addresses;
    }

    if (shipping) {
      doc.fontSize(12).font('Helvetica-Bold').text('Ship To:', 300, 170);
      doc
        .fontSize(10)
        .font('Helvetica')
        .text(shipping.full_name || shipping.name || billing.name, 300, 185);
      doc.text(
        `${shipping.line_1 || ''}${shipping.line_2 ? `, ${shipping.line_2}` : ''}`,
        300,
        200
      );
      doc.text(
        `${shipping.city || ''}, ${shipping.state || ''} - ${shipping.postal_code || ''}`,
        300,
        215
      );
      if (shipping.phone || shipping.mobile) {
        doc.text(`Phone: ${shipping.phone || shipping.mobile}`, 300, 230);
      }
    }

    doc.moveTo(50, 250).lineTo(550, 250).stroke();

    // --- Table Header ---
    let y = 270;
    doc.fontSize(10).font('Helvetica-Bold');
    doc.text('Description', 50, y);
    doc.text('SKU', 250, y);
    doc.text('Qty', 350, y, { width: 50, align: 'right' });
    doc.text('Price', 400, y, { width: 70, align: 'right' });
    doc.text('Total', 480, y, { width: 70, align: 'right' });

    doc
      .moveTo(50, y + 15)
      .lineTo(550, y + 15)
      .stroke();
    y += 25;

    // --- Table Rows ---
    doc.font('Helvetica'); // eslint-disable-line @typescript-eslint/no-explicit-any
    const items = order.order_items || [];
    items.forEach((item: any) => {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      doc.text(item.product_name, 50, y);
      doc.text(item.sku, 250, y);
      doc.text(item.quantity.toString(), 350, y, { width: 50, align: 'right' });
      doc.text(`Rs ${Number(item.unit_price).toFixed(2)}`, 400, y, { width: 70, align: 'right' });
      doc.text(`Rs ${Number(item.total_price).toFixed(2)}`, 480, y, { width: 70, align: 'right' });
      y += 20;

      if (y > 700) {
        doc.addPage();
        y = 50;
      }
    });

    // --- Totals ---
    y += 20;
    doc.moveTo(350, y).lineTo(550, y).stroke();
    y += 10;

    doc.text('Subtotal:', 350, y, { width: 100, align: 'right' });
    doc.text(
      `Rs ${Number(order.subtotal || order.total_amount - (order.tax_amount || 0) - (order.shipping_amount || 0)).toFixed(2)}`,
      450,
      y,
      { width: 100, align: 'right' }
    );
    y += 15;

    if (order.shipping_amount > 0) {
      doc.text('Shipping:', 350, y, { width: 100, align: 'right' });
      doc.text(`Rs ${Number(order.shipping_amount).toFixed(2)}`, 450, y, {
        width: 100,
        align: 'right',
      });
      y += 15;
    }

    doc.text('GST (18%):', 350, y, { width: 100, align: 'right' });
    doc.text(`Rs ${Number(order.tax_amount).toFixed(2)}`, 450, y, { width: 100, align: 'right' });
    y += 20;

    doc.fontSize(14).font('Helvetica-Bold');
    doc.fillColor('#3b82f6').text('Total:', 350, y, { width: 100, align: 'right' });
    doc.text(`Rs ${Number(order.total_amount).toFixed(2)}`, 450, y, { width: 100, align: 'right' });

    // --- Footer ---
    doc
      .fillColor('#999999')
      .fontSize(8)
      .font('Helvetica')
      .text(
        'This is a computer generated document. Terms: 1. Goods once sold will not be taken back. 2. Subject to Mumbai Jurisdiction.',
        50,
        780,
        { align: 'center' }
      );

    doc.end();
  }
}

import { getAdminClient } from '../config/supabase.js';
import { InventoryService } from '../modules/inventory/inventory.service.js';
import { AppError } from '../middlewares/error.js';

import { AuditService } from './auditService.js';
import logger from './logger.js'; // eslint-disable-line @typescript-eslint/no-unused-vars
// eslint-disable-line @typescript-eslint/no-unused-vars

export class ReturnService {
  /**
   * Create a new return request (RMA)
   */
  async createReturnRequest(data: {
    orderId: string;
    userId: string;
    reason: string;
    items: { orderItemId: string; quantity: number; reason?: string }[];
  }) {
    const admin = await getAdminClient();
    const rmaNumber = `RMA-${Date.now()}`;

    // 1. Create the Return Record
    const { data: returnRecord, error: returnError } = await admin
      .from('order_returns')
      .insert({
        order_id: data.orderId,
        user_id: data.userId,
        rma_number: rmaNumber,
        reason: data.reason,
        status: 'pending',
      })
      .select()
      .single();

    if (returnError) throw returnError;

    // 2. Create Return Items
    const returnItems = data.items.map((item) => ({
      return_id: returnRecord.id,
      order_item_id: item.orderItemId,
      quantity: item.quantity,
      reason: item.reason,
    }));

    const { error: itemsError } = await admin.from('order_return_items').insert(returnItems);
    if (itemsError) throw itemsError;

    // 3. Log Activity
    await AuditService.logOrderActivity({
      order_id: data.orderId,
      status: 'pending',
      notes: `Return request created: ${rmaNumber}. Reason: ${data.reason}`,
      performed_by: data.userId,
    });

    return returnRecord;
  }

  /**
   * Approve or Reject a return request
   */
  async updateReturnStatus(
    returnId: string,
    status: 'approved' | 'rejected' | 'received' | 'refunded',
    notes?: string,
    adminId?: string
  ) {
    const admin = await getAdminClient();

    const { data: returnRecord, error: fetchError } = await admin
      .from('order_returns')
      .select('*, order_return_items(*)')
      .eq('id', returnId)
      .single();

    if (fetchError || !returnRecord) throw new AppError('Return request not found', 404);

    const { error: updateError } = await admin
      .from('order_returns')
      .update({ status, updated_at: new Date().toISOString() })
      .eq('id', returnId);

    if (updateError) throw updateError;

    // Logic for 'received' - Restock Inventory
    if (status === 'received') {
      // Resolve warehouse for restocking (orders table has no warehouse_id)
      const { data: defaultWh } = await admin
        .from('warehouses')
        .select('id')
        .eq('is_active', true)
        .limit(1)
        .single();

      const warehouseId = defaultWh?.id;

      for (const item of returnRecord.order_return_items) {
        // Fetch product_id from order_item
        const { data: orderItem } = await admin
          .from('order_items')
          .select('product_id')
          .eq('id', item.order_item_id)
          .single();

        if (orderItem) {
          await InventoryService.adjustStock({
            productId: orderItem.product_id,
            warehouseId: warehouseId, // Restock to original warehouse or central hub
            quantity: item.quantity,
            type: 'return',
            referenceType: 'order',
            referenceId: returnRecord.order_id,
            notes: `Inventory restocked from RMA ${returnRecord.rma_number}`,
            userId: adminId,
          });
        }
      }
    }

    // Logic for 'refunded' - Update order payment status
    if (status === 'refunded') {
      await admin
        .from('orders')
        .update({ payment_status: 'refunded', status: 'returned' })
        .eq('id', returnRecord.order_id);
    }

    // Log Activity
    await AuditService.logOrderActivity({
      order_id: returnRecord.order_id,
      status: status === 'refunded' ? 'returned' : 'pending',
      notes: `Return ${returnRecord.rma_number} status updated to ${status}. ${notes || ''}`,
      performed_by: adminId,
    });

    await AuditService.log({
      user_id: adminId,
      action: 'RMA_STATUS_UPDATE',
      module: 'returns',
      entity_id: returnId,
      new_data: { status, notes },
    });

    return { success: true };
  }
 // eslint-disable-line @typescript-eslint/no-explicit-any
  async getAllReturns(filters: any = {}) {
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient();
    let query = admin
      .from('order_returns')
      .select('*, user_profiles(full_name), orders(order_number)')
      .order('created_at', { ascending: false });

    if (filters.status) query = query.eq('status', filters.status);

    const { data, error } = await query;
    if (error) throw error;
    return data;
  }
}

import { Server as HttpServer } from 'http';

import { Server } from 'socket.io';

import logger from '../services/logger.js';

let io: Server;

export const initSockets = (server: HttpServer) => {
  io = new Server(server, {
    cors: {
      origin: '*', // In production, replace with actual origin
      methods: ['GET', 'POST'],
    },
  });

  io.on('connection', (socket) => {
    const userId = socket.handshake.query.userId;
    logger.info(`[Socket] User connected: ${userId || 'anonymous'} (ID: ${socket.id})`);

    // Join room based on role or userId if needed
    if (userId) {
      socket.join(`user:${userId}`); // eslint-disable-line @typescript-eslint/no-floating-promises
    }

    socket.on('disconnect', () => {
      logger.info(`[Socket] User disconnected: ${socket.id}`);
    });
  });

  return io;
};

export const getIO = () => {
  if (!io) {
    throw new Error('Socket.io not initialized!');
  }
  return io;
};

/**
 * Emit a real-time event to specific rooms
 */
export const emitToRoom = (room: string, event: string, data: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
  // eslint-disable-line @typescript-eslint/no-explicit-any
  if (io) {
    io.to(room).emit(event, data);
  }
};

/**
 * Broadcast to all admins
 */ // eslint-disable-line @typescript-eslint/no-explicit-any
export const notifyAdmins = (event: string, data: any) => {
  // eslint-disable-line @typescript-eslint/no-explicit-any
  if (io) {
    io.emit(`admin:${event}`, data);
  }
};

