import { InventoryService } from '../modules/inventory/inventory.service.js';
import { OrderService } from '../modules/order/order.service.js'; // eslint-disable-line @typescript-eslint/no-unused-vars
// eslint-disable-line @typescript-eslint/no-unused-vars
import { OrderRepository } from '../modules/order/order.repository.js';
import { AuditService } from '../services/auditService.js';
import { AppError } from '../middlewares/error.js'; // eslint-disable-line @typescript-eslint/no-unused-vars
import { getAdminClient } from '../config/supabase.js';
// eslint-disable-line @typescript-eslint/no-unused-vars
import logger from '../services/logger.js';

import { RefundWorkflow } from './refundWorkflow.service.js';

const orderRepo = new OrderRepository();

export class InventoryWorkflow {
  static async reserveStock(data: {
    productId: string;
    warehouseId: string;
    quantity: number;
    userId?: string;
  }) {
    return await InventoryService.reserveStock(data);
  }

  static async releaseReservation(data: {
    productId: string;
    warehouseId: string;
    quantity: number;
    reservationId: string;
  }) {
    return await InventoryService.releaseReservation(data);
  }

  static async adjustStock(data: {
    productId: string;
    warehouseId: string;
    quantity: number;
    type: 'in' | 'out' | 'transfer' | 'adjustment' | 'return';
    referenceType?: string;
    referenceId?: string;
    notes?: string;
    userId?: string;
  }) {
    return await InventoryService.adjustStock(data);
  }

  static async transferStock(data: {
    productId: string;
    fromWarehouseId: string;
    toWarehouseId: string;
    quantity: number;
    notes?: string;
    userId?: string;
  }) {
    // Phase 4 will add transactional safety here
    await InventoryService.adjustStock({
      productId: data.productId,
      warehouseId: data.fromWarehouseId,
      quantity: -Math.abs(data.quantity),
      type: 'transfer',
      notes: data.notes || `Transfer to ${data.toWarehouseId}`,
      userId: data.userId,
    });
    try {
      return await InventoryService.adjustStock({
        productId: data.productId,
        warehouseId: data.toWarehouseId,
        quantity: Math.abs(data.quantity),
        type: 'transfer',
        notes: data.notes || `Transfer from ${data.fromWarehouseId}`,
        userId: data.userId,
      });
    } catch (error) {
      // Rollback
      await InventoryService.adjustStock({
        productId: data.productId,
        warehouseId: data.fromWarehouseId,
        quantity: Math.abs(data.quantity),
        type: 'adjustment',
        notes: `Rollback: Transfer failed`,
        userId: data.userId,
      });
      throw error;
    }
  }

  static async processReturn(
    id: string,
    data: {
      items: { productId: string; quantity: number }[];
      warehouseId: string;
      reason: string;
      refundAmount?: number;
      userId: string;
    }
  ) {
    // Extract processReturn from OrderService here
    const order = await orderRepo.getById(id);
    if (!order) throw new AppError('Order not found', 404);

    for (const item of data.items) {
      await InventoryService.adjustStock({
        productId: item.productId,
        warehouseId: data.warehouseId,
        quantity: item.quantity,
        type: 'return',
        referenceType: 'order',
        referenceId: id,
        notes: `Customer return: ${data.reason}`,
        userId: data.userId,
      });
    }

    await AuditService.logOrderActivity({
      order_id: id,
      status: 'returned',
      notes: `Return processed for ${data.items.length} items. Reason: ${data.reason}`,
      performed_by: data.userId,
    });

    if (data.refundAmount && data.refundAmount > 0) {
      logger.info(`Initiating refund of ₹${data.refundAmount} for order ${order.order_number}`);
      await RefundWorkflow.processRefund(id, data.refundAmount, data.reason, data.userId);
    }

    await orderRepo.update(id, { status: 'returned' });
    return { success: true };
  }
}

import { OrderService } from '../modules/order/order.service.js';
import { InventoryService } from '../modules/inventory/inventory.service.js';
import { AppError } from '../middlewares/error.js';
import { JobService } from '../services/jobService.js';
import { getAdminClient } from '../config/supabase.js';
import logger from '../services/logger.js';

const orderService = new OrderService();

export class OrderWorkflow {
  static async processCheckout(userId: string | undefined, orderData: any, userEmail?: string) { // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const admin = await getAdminClient(); // eslint-disable-line @typescript-eslint/no-unused-vars
    const { items, shippingAddress } = orderData;
    // eslint-disable-line @typescript-eslint/no-unused-vars
    let warehouseId = orderData.warehouseId;

    if (!warehouseId) {
      const { data: defaultWh } = await admin
        .from('warehouses')
        .select('id')
        .eq('is_active', true)
        .limit(1)
        .single();
      warehouseId = defaultWh?.id;
    }

    // 1. Validate & Reserve Inventory
    const reservations: string[] = [];
    try {
      for (const item of items) {
        const { reservationId } = await InventoryService.reserveStock({
          productId: item.productId || item.product_id,
          warehouseId,
          quantity: Number(item.quantity),
          userId,
        });
        reservations.push(reservationId); // eslint-disable-line @typescript-eslint/no-explicit-any
      }
    } catch (err: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      // Rollback successful reservations (future: transaction handling)
      throw new AppError(`Order failed during inventory reservation: ${err.message}`, 400);
    }

    try {
      // 2. Create Order & Payment (orchestrates multiple steps)
      const order = await orderService.createOrder(userId, orderData, userEmail);

      // 3. Commit reservations (convert reserved to actual deductions)
      for (const item of items) {
        await InventoryService.adjustStock({
          productId: item.productId || item.product_id,
          warehouseId,
          quantity: -Number(item.quantity),
          type: 'out',
          referenceType: 'order',
          referenceId: order.id,
          userId,
        });
      }
      // 4. Dispatch analytics event asynchronously
      await JobService.dispatchAnalyticsEvent('order_created', {
        orderId: order.id,
        userId,
        totalAmount: order.total_amount,
      }); // eslint-disable-line @typescript-eslint/no-explicit-any

      return order;
    } catch (orderErr: any) {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      // Rollback reservations
      logger.error('[OrderWorkflow] Order creation failed, rolling back reservations:', orderErr);
      for (const rId of reservations) {
        try {
          // We need to release the reservation. The reservations array just has the IDs,
          // but our releaseReservation method requires productId, warehouseId, and quantity.
          // Since we have the items array, we can use it to reconstruct the release.
          // Note: This assumes 1:1 mapping of reservations to items.
          const index = reservations.indexOf(rId);
          if (index !== -1) {
            const item = items[index];
            await InventoryService.releaseReservation({
              productId: item.productId || item.product_id,
              warehouseId,
              quantity: Number(item.quantity),
              reservationId: rId,
            });
          }
        } catch (rollbackErr) {
          logger.error(`[OrderWorkflow] Failed to rollback reservation ${rId}:`, rollbackErr);
        }
      }
      throw new AppError(`Order processing failed: ${orderErr.message}`, 500);
    }
  }
}

import crypto from 'node:crypto';

import Razorpay from 'razorpay';

import { getAdminClient } from '../config/supabase.js';
import { AppError } from '../middlewares/error.js';
import logger from '../services/logger.js';

const RAZORPAY_KEY_ID = process.env.RAZORPAY_KEY_ID;
const RAZORPAY_KEY_SECRET = process.env.RAZORPAY_KEY_SECRET;

const razorpay =
  RAZORPAY_KEY_ID && RAZORPAY_KEY_SECRET
    ? new Razorpay({
        key_id: RAZORPAY_KEY_ID,
        key_secret: RAZORPAY_KEY_SECRET,
      })
    : null;

if (!razorpay) {
  logger.warn('⚠️ [PaymentWorkflow] Razorpay credentials missing. Payments will not function.');
}

export class PaymentWorkflow {
  static async createOrder( // eslint-disable-line @typescript-eslint/no-explicit-any
    items: any[],
    receipt: string,
    shippingFee: number = 0,
    discountAmount: number = 0
  ) { // eslint-disable-line @typescript-eslint/no-explicit-any
    // eslint-disable-line @typescript-eslint/no-explicit-any
    if (!Array.isArray(items) || items.length === 0) {
      throw new AppError('Payment order must include at least one item', 400);
    }

    const normalizedItems = items.map((item: any) => ({
      // eslint-disable-line @typescript-eslint/no-explicit-any
      productId: item.productId || item.product_id,
      quantity: Number(item.quantity),
    }));

    for (const item of normalizedItems) { // eslint-disable-line @typescript-eslint/no-explicit-any
      if (!item.productId || !Number.isInteger(item.quantity) || item.quantity <= 0) {
        throw new AppError('Invalid payment item', 400);
      }
    }

    const admin = await getAdminClient();
    const productIds = [...new Set(normalizedItems.map((item: any) => item.productId))];
    // eslint-disable-line @typescript-eslint/no-explicit-any
    const { data: products, error } = await admin // eslint-disable-line @typescript-eslint/no-explicit-any
      .from('products')
      .select('id, price, status') // eslint-disable-line @typescript-eslint/no-explicit-any
      .in('id', productIds);

    if (error) throw error;

    const productById = new Map<string, any>(
      // eslint-disable-line @typescript-eslint/no-explicit-any
      (products || []).map((product: any) => [product.id, product])
      // eslint-disable-line @typescript-eslint/no-explicit-any
    );
    const subtotal = normalizedItems.reduce((sum: number, item: any) => {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      const product = productById.get(item.productId);
      if (!product || product.status !== 'active') {
        throw new AppError(`Product ${item.productId} is not available`, 400);
      }
      return sum + Number(product.price) * item.quantity;
    }, 0);
    const tax = Math.round(subtotal * 0.18 * 100) / 100;
    const finalTotal = Math.max(0, subtotal + tax + shippingFee - discountAmount);
    const amount = Math.round(finalTotal * 100); // Razorpay expects amount in paise

    if (!razorpay) {
      throw new AppError('Payment system is not configured', 500);
    }

    const order = await razorpay.orders.create({
      amount,
      currency: 'INR',
      receipt,
    });

    return {
      provider: 'razorpay',
      key: process.env.RAZORPAY_KEY_ID,
      order,
    };
  }

  static verifyPayment(orderId: string, paymentId: string, signature: string): boolean {
    const expectedSignature = crypto
      .createHmac('sha256', process.env.RAZORPAY_KEY_SECRET || '')
      .update(`${orderId}|${paymentId}`)
      .digest('hex');

    return expectedSignature === signature;
  }
}

import Razorpay from 'razorpay';

import logger from '../services/logger.js';
import { getAdminClient } from '../config/supabase.js';
import { AppError } from '../middlewares/error.js';

import { NotificationWorkflow } from './notificationWorkflow.service.js';

const RAZORPAY_KEY_ID = process.env.RAZORPAY_KEY_ID;
const RAZORPAY_KEY_SECRET = process.env.RAZORPAY_KEY_SECRET;

const razorpay =
  RAZORPAY_KEY_ID && RAZORPAY_KEY_SECRET
    ? new Razorpay({
        key_id: RAZORPAY_KEY_ID,
        key_secret: RAZORPAY_KEY_SECRET,
      })
    : null;

export class RefundWorkflow {
  static async processRefund(
    orderId: string,
    refundAmount: number,
    notes?: string,
    performedBy?: string
  ) {
    if (!razorpay) {
      logger.warn(
        '[RefundWorkflow] Razorpay not configured. Skipping actual payment gateway refund.'
      );
    }

    const admin = await getAdminClient();
    const { data: order, error } = await admin
      .from('orders')
      .select('*')
      .eq('id', orderId)
      .single();

    if (error || !order) {
      throw new AppError('Order not found for refund', 404);
    }

    // 1. Process Gateway Refund
    let gatewayRefundId = null;
    if (razorpay && order.payment_intent_id) {
      try {
        const refund = await razorpay.payments.refund(order.payment_intent_id, {
          amount: Math.round(refundAmount * 100),
          notes: {
            reason: notes || 'Customer Requested Refund',
          },
        });
        gatewayRefundId = refund.id;
        logger.info(`[RefundWorkflow] Razorpay refund successful: ${refund.id}`);
      } catch (refundErr: any) { // eslint-disable-line @typescript-eslint/no-explicit-any
        // eslint-disable-line @typescript-eslint/no-explicit-any
        logger.error('[RefundWorkflow] Razorpay refund failed:', refundErr);
        throw new AppError(
          `Payment gateway refund failed: ${refundErr.description || refundErr.message}`,
          500
        );
      }
    } else {
      logger.info(
        `[RefundWorkflow] Simulated refund of ₹${refundAmount} for order ${order.order_number}`
      );
    }

    // 2. Log Refund in Database
    await admin.from('refunds').insert({
      order_id: orderId,
      amount: refundAmount,
      gateway_refund_id: gatewayRefundId,
      reason: notes,
      status: 'completed',
      processed_by: performedBy,
    });

    // 3. Notify Customer
    await NotificationWorkflow.notifyCustomerOrderUpdate({
      orderNumber: order.order_number,
      status: 'refunded',
      notes: `A refund of ₹${refundAmount} has been processed. ${notes || ''}`,
      phone: order.shipping_address?.phone || order.phone,
      email: order.customer_email,
      userId: order.user_id,
    });

    return { success: true, refundId: gatewayRefundId };
  }
}

import axios, { AxiosInstance, AxiosError, InternalAxiosRequestConfig } from 'axios';

const metaEnv = (
  import.meta as ImportMeta & {
    env?: Record<string, string | undefined>;
  }
).env;

let BASE_URL = metaEnv?.VITE_API_BASE_URL ?? 'http://localhost:8080/api/v1';
if (BASE_URL.endsWith('/')) {
  BASE_URL = BASE_URL.slice(0, -1);
}

export const apiClient: AxiosInstance = axios.create({
  baseURL: BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 30000,
});

// Retry Logic Helper
const MAX_RETRIES = 3;
const RETRY_DELAY = 1000; // 1s

// Request Interceptor: Auth Injection
apiClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const token = localStorage.getItem('auth_token') || localStorage.getItem('admin_token');
    if (token && config.headers) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Response Interceptor: Data Extraction & Error Handling
apiClient.interceptors.response.use(
  (response) => {
    // Automatically extract 'data' if the response follows the { success, data } standard
    if (
      response.data &&
      typeof response.data === 'object' &&
      response.data.success === true &&
      response.data.data !== undefined
    ) {
      return {
        ...response,
        data: response.data.data,
      };
    }
    return response;
  },
  async (error: AxiosError) => {
    const config = error.config as InternalAxiosRequestConfig & { _retryCount?: number };

    // 1. Handle Retry for Network Errors or 5xx
    const isNetworkError = !error.response;
    const isServerError = error.response && error.response.status >= 500;

    if ((isNetworkError || isServerError) && (config._retryCount || 0) < MAX_RETRIES) {
      config._retryCount = (config._retryCount || 0) + 1;
      const delay = RETRY_DELAY * Math.pow(2, config._retryCount - 1); // Exponential backoff

      console.warn(
        `[API] Retrying request (${config._retryCount}/${MAX_RETRIES}) in ${delay}ms... Status: ${error.response?.status || 'Network Error'}`
      );
      await new Promise((resolve) => setTimeout(resolve, delay));
      return apiClient(config);
    }

    // 2. Handle 401 Unauthorized (Token expired)
    if (error.response?.status === 401) {
      // Clear token if definitely invalid
      localStorage.removeItem('auth_token');
      localStorage.removeItem('admin_token');
      localStorage.removeItem('byteevolvr-user-storage'); // Clear persisted user state on auth failure
      console.error('Session expired. Please login again.');

      // Redirect to login if on the client side
      if (typeof window !== 'undefined' && !window.location.pathname.includes('/login')) {
        const loginPath = window.location.pathname.startsWith('/shop') ? '/shop/login' : '/login';
        window.location.href = loginPath;
      }
    }

    // 3. Centralized Error Reporting
    const errorMessage =
      (error.response?.data as any)?.message || error.message || 'An unexpected error occurred'; // eslint-disable-line @typescript-eslint/no-explicit-any

    return Promise.reject({
      ...error,
      customMessage: errorMessage,
      status: error.response?.status,
      timestamp: new Date().toISOString(),
    });
  }
);

