import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface User {
  id: string;
  email: string;
  role: string;
  full_name?: string;
  avatar_url?: string;
  user_metadata?: {
    full_name?: string;
    role?: string;
    [key: string]: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  };
}

interface AuthState {
  user: User | null;
  token: string | null;
  isAdmin: boolean;
  isLoading: boolean;
  error: string | null;

  // Actions
  setUser: (user: User | null) => void;
  setToken: (token: string | null, type: 'auth' | 'admin') => void;
  logout: () => void;
  initialize: () => void;
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set) => ({
      user: null,
      token: null,
      isAdmin: false,
      isLoading: false,
      error: null,

      setUser: (user) =>
        set({
          user,
          isAdmin: user?.role === 'admin',
        }),

      setToken: (token, type) => {
        if (token) {
          localStorage.setItem(type === 'admin' ? 'admin_token' : 'auth_token', token);
        }
        set({ token });
      },

      logout: () => {
        localStorage.removeItem('auth_token');
        localStorage.removeItem('admin_token');
        set({ user: null, token: null, isAdmin: false });
      },

      initialize: () => {
        const adminToken = localStorage.getItem('admin_token');
        const authToken = localStorage.getItem('auth_token');
        const token = adminToken || authToken;
        if (!token) {
          set({ user: null, token: null, isAdmin: false });
          return;
        }
        set({ token, isAdmin: !!adminToken });
      },
    }),
    {
      name: 'byteevolvr-user-storage',
      partialize: (state) => ({ user: state.user, isAdmin: state.isAdmin }),
    }
  )
);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  sku?: string;
  image_url?: string;
}

interface CartState {
  items: CartItem[];
  isLoading: boolean;
  error: string | null;
  addItem: (item: any, quantity?: number) => void; // eslint-disable-line @typescript-eslint/no-explicit-any
  removeItem: (id: string) => void;
  updateQuantity: (id: string, quantity: number) => void;
  clearCart: () => void;
  totalAmount: () => number;
  totalItems: () => number;
  appliedDiscount: { code: string; discount: number; couponId: string } | null;
  setAppliedDiscount: (
    discount: { code: string; discount: number; couponId: string } | null
  ) => void;
}

export const useCartStore = create<CartState>()(
  persist(
    (set, get) => ({
      items: [],
      isLoading: false,
      error: null,
      appliedDiscount: null,

      setAppliedDiscount: (discount) => set({ appliedDiscount: discount }),

      addItem: (item, quantity = 1) => {
        const items = get().items;
        const existingItem = items.find((i) => i.id === item.id);
        const itemPrice = Number(item.price);
        const itemQty = Number(quantity);

        if (existingItem) {
          set({
            items: items.map((i) =>
              i.id === item.id ? { ...i, quantity: i.quantity + itemQty } : i
            ),
          });
        } else {
          set({ items: [...items, { ...item, price: itemPrice, quantity: itemQty }] });
        }
      },

      removeItem: (id) => {
        set({ items: get().items.filter((i) => i.id !== id) });
      },

      updateQuantity: (id, quantity) => {
        const newQty = Math.max(0, Math.floor(Number(quantity) || 0));
        if (newQty <= 0) {
          get().removeItem(id);
          return;
        }
        set({
          items: get().items.map((i) => (i.id === id ? { ...i, quantity: newQty } : i)),
        });
      },

      clearCart: () => set({ items: [], appliedDiscount: null }),

      totalAmount: () => {
        return get().items.reduce((total, item) => {
          const price = Number(item.price) || 0;
          const qty = Number(item.quantity) || 0;
          return total + price * qty;
        }, 0);
      },

      totalItems: () => {
        return get().items.reduce((total, item) => total + (Number(item.quantity) || 0), 0);
      },
    }),
    {
      name: 'byteevolvr-cart-storage',
    }
  )
);

